def _skl_instantiate(cls, kwargs, random_state=None):
    """Instancia um modelo scikit-learn, injetando random_state apenas se a classe aceitar o parâmetro."""
    kwargs = dict(kwargs or {})
    try:
        sig_params = inspect.signature(cls.__init__).parameters
    except (TypeError, ValueError):
        sig_params = {}
    if random_state is not None and "random_state" in sig_params and "random_state" not in kwargs:
        kwargs["random_state"] = random_state
    return cls(**kwargs)


def _skl_force_single_thread_kwargs(cls, kwargs):
    """XGBoost/LightGBM/CatBoost usam threading nativo próprio (OpenMP), independente do backend
    do joblib — 'joblib.parallel_backend(\"threading\")' não tem efeito sobre eles. Em loops que
    reinstanciam e refazem fit() dezenas/centenas de vezes numa QThread de background (ex.: curva
    Sort metric vs. Parameter/n_features), forçamos single-thread para evitar instabilidade do
    threading nativo repetido. CatBoost usa 'thread_count' em vez de 'n_jobs'."""
    module_name = getattr(cls, "__module__", "") or ""
    if module_name.startswith("xgboost") or module_name.startswith("lightgbm"):
        kwargs = dict(kwargs)
        kwargs["n_jobs"] = 1
    elif module_name.startswith("catboost"):
        kwargs = dict(kwargs)
        kwargs["thread_count"] = 1
    return kwargs


def _skl_split_grid_values(values_text):
    """Splits a hyperparameter grid cell's raw text into individual candidate value strings, on
    commas at parenthesis depth 0 only. A naive text.split(",") would shatter a single
    tuple-valued candidate (e.g. MLPRegressor/MLPClassifier's hidden_layer_sizes, entered as
    '(50,),(100,),(100,50)') into bogus fragments like '(100' and '50)' at its own internal
    comma, each of which then fails ast.literal_eval in _skl_parse_grid_value() below and is
    kept as a plain (invalid) string - breaking every combination that uses it."""
    parts = []
    depth = 0
    current = []
    for ch in values_text:
        if ch == "(":
            depth += 1
            current.append(ch)
        elif ch == ")":
            depth = max(0, depth - 1)
            current.append(ch)
        elif ch == "," and depth == 0:
            parts.append("".join(current))
            current = []
        else:
            current.append(ch)
    parts.append("".join(current))
    return parts


def _skl_parse_grid_value(text):
    """Converte uma célula de texto (ex: '100', 'None', 'True', '(100, 50)') no valor Python correspondente,
    usado para montar o param_grid do GridSearchCV/RandomizedSearchCV a partir da tabela editável de hiperparâmetros."""
    text = (text or "").strip()
    if text == "":
        return text
    if text == "None":
        return None
    if text == "True":
        return True
    if text == "False":
        return False
    if text.startswith("(") and text.endswith(")"):
        try:
            return ast.literal_eval(text)
        except Exception:
            return text
    try:
        if "." in text or "e" in text.lower():
            return float(text)
        return int(text)
    except ValueError:
        return text


def _skl_regression_metrics_label(y_true, y_pred):
    """Monta o texto (R2/MAE/RMSE/MSE) exibido na legenda dos gráficos de regressão da STEP 6 quando
    o checkbox 'Metric Legend' está marcado."""
    r2 = r2_score(y_true, y_pred)
    mae_value = mae(y_true, y_pred)
    mse_value = mse(y_true, y_pred)
    rmse_value = mse_value ** 0.5
    return f"R² = {r2:.4f}\nMAE = {mae_value:.4f}\nRMSE = {rmse_value:.4f}\nMSE = {mse_value:.4f}"


def _ensure_sklearn_usi_dirs(job_dir, usi_key):
    """Cria (se necessário) as subpastas de resultados da STEP 5 (screening scikit-learn) dentro de
    RESULTS/USI/<usi_key>."""
    usi_key = _normalize_usi_key(usi_key)
    base = os.path.join(job_dir, "RESULTS", "USI", usi_key)
    paths = {
        "base": base,
        "data": os.path.join(base, "DATA"),
        "midia": os.path.join(base, "MIDIA"),
        "models": os.path.join(base, "MODELS"),
        "predictions": os.path.join(base, "PREDICTIONS"),
    }
    for path in paths.values():
        os.makedirs(path, exist_ok=True)
    return paths


