# ====================================================== CUSTOM QT WIDGETS =================================================================
# ==========================================================================================================================================
class QComboBox(_QtQComboBox): # type: ignore
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._sync_focus_editor()

    def setEditable(self, editable):
        super().setEditable(editable)
        self._sync_focus_editor()

    def _sync_focus_editor(self):
        editor = self.lineEdit()
        if editor is None:
            return
        editor.removeEventFilter(self)
        editor.installEventFilter(self)

    def _has_visual_focus(self):
        editor = self.lineEdit()
        return self.hasFocus() or (editor is not None and editor.hasFocus())

    def eventFilter(self, watched, event):
        if watched is self.lineEdit() and event.type() in (QEvent.FocusIn, QEvent.FocusOut):
            self.update()
        return super().eventFilter(watched, event)

    def focusInEvent(self, event):
        super().focusInEvent(event)
        self.update()

    def focusOutEvent(self, event):
        super().focusOutEvent(event)
        self.update()

    def paintEvent(self, event):
        super().paintEvent(event)
        if not self.isEnabled() or not self._has_visual_focus():
            return

        painter = QPainter(self)
        painter.setRenderHint(QPainter.Antialiasing, True)
        painter.setBrush(Qt.NoBrush)
        painter.setPen(QPen(QColor("#2ECC71"), 2))
        painter.drawRoundedRect(self.rect().adjusted(1, 1, -1, -1), 4, 4)

