def _style_dialog_buttons(*pairs):
    """Aplica estilos padrão a pares (btn_save, btn_close) de diálogos.
    Uso: _style_dialog_buttons(btn_save, btn_close)
    """
    for i, btn in enumerate(pairs):
        if btn is None:
            continue
        if i % 2 == 0:          # posição par  → Save (verde)
            btn.setProperty("role", "primary")
            btn.setStyleSheet(_SS_BTN_PRIMARY)
        else:                    # posição ímpar → Close (salmão)
            btn.setProperty("role", "danger")
            btn.setStyleSheet(_SS_BTN_DANGER)

def evaluate_subset_cv(X, y, task_type: str, scoring=None, cv: int = 5, random_state: int = 123):
    # """Avalia um subconjunto de features via cross-validation.
    # - Para classificação: F1-macro (padrão) com StratifiedKFold.
    # - Para regressão: R² (padrão) com KFold.
    # Retorna: (média, desvio-padrão)."""
    from sklearn.model_selection import cross_val_score, StratifiedKFold, KFold
    from sklearn.ensemble import RandomForestClassifier, RandomForestRegressor
    task_type = (task_type or "").lower()
    if task_type.startswith("class"):
        model = RandomForestClassifier(n_estimators=300, random_state=random_state, n_jobs=-1)
        cvobj = StratifiedKFold(n_splits=cv, shuffle=True, random_state=random_state)
        scoring = scoring or "f1_macro"
    else:
        model = RandomForestRegressor(n_estimators=300, random_state=random_state, n_jobs=-1)
        cvobj = KFold(n_splits=cv, shuffle=True, random_state=random_state)
        scoring = scoring or "r2"
    scores = cross_val_score(model, X, y, cv=cvobj, scoring=scoring, n_jobs=-1)
    return float(np.mean(scores)), float(np.std(scores))

def _auto_n_components_for_all(df, first_col, last_col, method_name,
                               y_series=None, task_type="classification",
                               var_thr=None, seed=42):

    # --- fatia bloco X e saneia ---
    cols = list(df.columns.astype(str))
    if first_col not in cols or last_col not in cols:
        return 2  # fallback seguro
    i0, i1 = cols.index(first_col), cols.index(last_col)
    if i0 > i1: i0, i1 = i1, i0
    X = df.iloc[:, i0:i1+1].apply(pd.to_numeric, errors="coerce").fillna(0.0).values

    # limites de posto
    n_samples, n_features = X.shape
    if n_features == 0:
        return 2
    max_rank = max(1, min(n_samples - 1, n_features))

    # --- PCA completo só para estimar k por variância ---
    Xs = StandardScaler().fit_transform(X)
    pca_full = PCA(n_components=max_rank, random_state=seed).fit(Xs)
    cum = np.cumsum(pca_full.explained_variance_ratio_)
    k_pca = int(np.searchsorted(cum, var_thr) + 1)
    k_pca = max(1, min(k_pca, max_rank))

    m = (method_name or "").lower()

    # --- regras por método (apenas *clamp* do k_pca) ---
    if "lda" in m:
        # classificação: n_comp <= n_classes-1
        if y_series is not None:
            n_classes = pd.Categorical(pd.Series(y_series)).unique()
            return max(1, min(k_pca, max(1, n_classes - 1)))
        return max(1, min(k_pca, 2))  # fallback

    if "pls-da" in m or "pls da" in m:
        if y_series is not None:
            n_classes = pd.Categorical(pd.Series(y_series)).unique()
            return max(2, min(k_pca, max(1, n_classes - 1)))
        return max(2, min(k_pca, 3))

    if "pls" in m:  # regressão
        return max(2, min(k_pca, max_rank))

    if "nmf" in m:
        # evitar degenera: ≥2 e < n_features
        return max(2, min(k_pca, max(2, n_features - 1)))

    if "kernel pca" in m or "kpca" in m:
        return max(2, min(k_pca, n_features, 50))  # 50 como teto prático

    if "svd" in m or "truncatedsvd" in m:
        return max(2, min(k_pca, max_rank))

    if "tsne" in m or "t-sne" in m:
        # o módulo já limita a <=3; mantemos alinhado
        return max(2, min(k_pca, 3))

    if "umap" in m or "isomap" in m or "spectral" in m:
        # manifold/embedding para visualização: 2–10 costuma ser razoável
        return max(2, min(k_pca, 10))

    # PCA (ou default)
    return max(2, min(k_pca, n_features))

def _compact_matrix_str(arr):
    """Monta string de uma única 'matriz' com 4 quadrantes e separadores '...'.
    - Para >=3D: fatia arr[0] repetidamente até virar 2D (anota a fatia).
    - Para 2D: mostra 3 primeiras/3 últimas linhas e colunas em uma grade única.
    - Para 1D: mostra head e tail (10 + 10).
    - Para escalares: mostra o valor.
    Retorna (texto, info_extra) onde info_extra pode conter aviso de fatia.
    """
    import numpy as _np

    if arr is None:
        return "(vazio)", ""

    # Converte torch/TF para numpy quando possível
    try:
        import torch as _torch
    except Exception:
        _torch = None
    try:
        import tensorflow as _tf
    except Exception:
        _tf = None

    if _torch is not None and isinstance(arr, _torch.Tensor):
        arr = arr.detach().cpu().numpy()
    elif _tf is not None and hasattr(arr, "numpy"):
        try:
            arr = arr.numpy()
        except Exception:
            pass

    # Se não for ndarray, tenta converter
    if not isinstance(arr, _np.ndarray):
        try:
            arr = _np.asarray(arr)
        except Exception:
            return repr(arr), ""

    # Escalar
    if arr.shape == () or _np.isscalar(arr):
        return str(arr), f"shape={arr.shape}, dtype={arr.dtype}"

    info = [f"shape={arr.shape}, dtype={arr.dtype}"]
    A = arr
    slice_info = []
    while A.ndim > 2:
        slice_info.append(0)
        A = A[0]
    if slice_info:
        info.append(f"fatia usada p/ reduzir a 2D: {tuple(slice_info)}")

    if A.ndim == 1:
        n = A.shape[0]
        head = A[:min(10, n)]
        tail = A[max(0, n-10):] if n > 10 else _np.array([])
        out = ["— 1D head —", _np.array2string(head, precision=6, max_line_width=120)]
        if tail.size:
            out += ["— 1D tail —", _np.array2string(tail, precision=6, max_line_width=120)]
        return "\n".join(out), " | ".join(info)

    if A.ndim != 2:
        # Algum caso estranho: imprime de forma segura
        return _np.array2string(A, precision=6, max_line_width=120), " | ".join(info)

    R, C = A.shape
    r_head = min(3, R); r_tail = (min(3, R - r_head) if R > 3 else 0)
    c_head = min(3, C); c_tail = (min(3, C - c_head) if C > 3 else 0)

    TL = A[:r_head, :c_head]
    TR = A[:r_head, -c_tail:] if c_tail > 0 else None
    BL = A[-r_tail:, :c_head] if r_tail > 0 else None
    BR = A[-r_tail:, -c_tail:] if (r_tail > 0 and c_tail > 0) else None

    def _fmt(block):
        if block is None:
            return None
        return _np.vectorize(lambda x: f"{x:.6g}")(block)

    TLs = _fmt(TL); TRs = _fmt(TR); BLs = _fmt(BL); BRs = _fmt(BR)

    col_sep_needed = (C > (c_head + c_tail))
    row_sep_needed = (R > (r_head + r_tail))

    col_sep_top = _np.array([["..."]] * (TLs.shape[0] if TLs is not None else 0), dtype=object) if col_sep_needed else None
    col_sep_bot = _np.array([["..."]] * (BLs.shape[0] if BLs is not None else 0), dtype=object) if col_sep_needed and BLs is not None else None

    row_sep_len = ((TLs.shape[1] if TLs is not None else 0)
                + (1 if col_sep_top is not None else 0)
                + (TRs.shape[1] if TRs is not None else 0))
    row_sep = _np.array([["..."] * row_sep_len], dtype=object) if row_sep_needed else None

    # monta topo / base
    top_row = TLs
    if col_sep_top is not None:
        top_row = _np.hstack([top_row, col_sep_top]) if top_row is not None else col_sep_top
    if TRs is not None:
        top_row = _np.hstack([top_row, TRs]) if top_row is not None else TRs

    bottom_row = None
    if BLs is not None:
        bottom_row = BLs
        if col_sep_bot is not None:
            bottom_row = _np.hstack([bottom_row, col_sep_bot])
        if BRs is not None:
            bottom_row = _np.hstack([bottom_row, BRs])

    # junta tudo
    if bottom_row is not None and row_sep is not None:
        out = _np.vstack([top_row, row_sep, bottom_row])
    elif bottom_row is not None:
        out = _np.vstack([top_row, bottom_row])
    else:
        out = top_row

    # imprime como linhas de strings
    lines = ["— Compact 3×3 … 3×3 —"]
    for line in out:
        lines.append("  ".join(map(str, line)))
    return "\n".join(lines), " | ".join(info)

def _preview_matrix_compact(name, arr):
    txt, info = _compact_matrix_str(arr)
    header = f"[{name}] {info}".strip()
    return f"{header}\n{txt}"

def _show_tensor_preview(parent, X_out, y_out=None, w_out=None):
    from PyQt5.QtWidgets import QDialog, QVBoxLayout, QTextEdit, QPushButton, QHBoxLayout
    dlg = QDialog(parent)
    dlg.setWindowTitle("Preview do Tensor gerado")
    lay = QVBoxLayout(dlg)

    view = QTextEdit()
    view.setReadOnly(True)

    blocks = []
    blocks.append(_preview_matrix_compact("X_out", X_out))
    if y_out is not None:
        blocks.append(_preview_matrix_compact("y_out", y_out))
    if w_out is not None:
        blocks.append(_preview_matrix_compact("w_out", w_out))
    view.setText("\n\n".join(blocks))

    lay.addWidget(view)
    btns = QHBoxLayout()
    ok = QPushButton("Close")
    ok.setProperty("role", "danger")
    ok.setStyleSheet(_SS_BTN_DANGER)
    ok.clicked.connect(dlg.accept)
    btns.addStretch(1); btns.addWidget(ok)
    lay.addLayout(btns)
    dlg.resize(900, 600)
    dlg.exec_()

def _ensure_models_dir(job_dir, task: str):
    base = os.path.join(job_dir, "MODELS")
    sub = {
        "classification": "CLASSIFICATION",
        "regression": "REGRESSION",
        "clustering": "CLUSTERING"
    }.get((task or "").lower(), "REGRESSION")
    out = os.path.join(base, sub)
    os.makedirs(out, exist_ok=True)
    return out

def _normalize_usi_key(usi_key: str) -> str:
    cleaned = str(usi_key or "").strip()
    return cleaned or "LOAD"

def _generate_new_usi_code(job_dir: str) -> str:
    """Gera um código USI de 4 caracteres alfanuméricos ainda não usado em RESULTS/USI/<job_dir>,
    garantindo que cada execução (ex.: Run Screening da STEP 6) grave em uma pasta nova, sem
    misturar/sobrescrever resultados de tentativas anteriores."""
    usi_root = os.path.join(job_dir or "", "RESULTS", "USI")
    alphabet = string.ascii_uppercase + string.digits
    for _ in range(100):
        code = "".join(random.choices(alphabet, k=4))
        if not os.path.isdir(os.path.join(usi_root, code)):
            return code
    return "".join(random.choices(alphabet, k=8))

def _ui_bool_from_combo(cb):
    """Mapeia 'True'/'False'/'Auto' para bool/None."""
    if cb is None:
        return None
    val = str(cb.currentText()).strip().lower()
    if val == "true": return True
    if val == "false": return False
    if val == "auto": return None
    return None

def _ui_get_if_checked(chk, widget_getter):
    """Retorna valor apenas se o checkbox estiver marcado; senão None (não envia o arg)."""
    try:
        if chk is not None and chk.isChecked():
            return widget_getter()
    except Exception:
        pass
    return None

def _ui_csv_to_list(s: str):
    """Converte texto 'a,b , c' -> ['a','b','c'] (sem vazios)."""
    items = []
    for token in str(s or "").split(","):
        cleaned = token.strip().strip("[](){} ").strip("\"'")
        if cleaned:
            items.append(cleaned)
    return items

def _ensure_models_dir(job_dir, task: str):
    base = os.path.join(job_dir, "MODELS")
    sub = {
        "classification": "CLASSIFICATION",
        "regression": "REGRESSION",
        "clustering": "CLUSTERING"
    }.get((task or "").lower(), "REGRESSION")
    out = os.path.join(base, sub)
    os.makedirs(out, exist_ok=True)
    return out

def check_chembl_status() -> bool:
    """Retorna True se o servidor ChEMBL está respondendo."""
    try:
        req = urllib.request.urlopen(
            "https://www.ebi.ac.uk/chembl/api/data/status.json",
            timeout=8
        )
        return req.status == 200
    except Exception:
        return False

def get_chembl_client(max_retries=5, backoff=(5, 10, 20, 40, 60)):
    """
    Retorna new_client com retry no carregamento do schema (/spore).
    Usa cache em disco para evitar nova requisição se o schema já foi baixado.
    """
    # Cache do schema em disco (~/.chembl_schema_cache)
    cache_dir = os.path.join(os.path.expanduser("~"), ".chembl_cache")
    os.makedirs(cache_dir, exist_ok=True)
    os.environ.setdefault("CHEMBL_CACHE_BACKEND", "sqlite")
    os.environ.setdefault("CHEMBL_CACHE_NAME", os.path.join(cache_dir, "chembl_cache"))

    # ── Corrige um bug de paginação do chembl_webresource_client ──
    # `chembl_webresource_client.new_client` constrói os QuerySets de cada recurso (activity,
    # assay, molecule, ...) UMA ÚNICA VEZ, no momento em que o módulo é importado pela primeira
    # vez no processo — e cada QuerySet fixa Settings.MAX_LIMIT (padrão 20) como seu tamanho de
    # página interno naquele instante, para sempre. Se ajustarmos MAX_LIMIT depois desse primeiro
    # import (ex.: dentro de fetch_chembl_paginated), já é tarde: o QuerySet já foi construído
    # com limit=20. Isso faz [offset:offset+page_size] com offset>0 devolver só ~20 registros por
    # página (erro de aritmética do próprio cliente ao encadear páginas internas), interrompendo
    # o download bem antes do total real. Por isso o ajuste precisa ocorrer AQUI, antes do
    # primeiro `from chembl_webresource_client.new_client import new_client` do processo.
    try:
        from chembl_webresource_client.settings import Settings
        Settings.Instance().MAX_LIMIT = 1000
    except Exception:
        pass

    last_exc = None
    for attempt, wait in enumerate(backoff[:max_retries], start=1):
        try:
            from chembl_webresource_client.new_client import new_client
            # Força validação do schema agora (não lazy)
            _ = new_client.activity
            return new_client
        except Exception as exc:
            last_exc = exc
            print(f"[ChEMBL] Tentativa {attempt}/{max_retries} falhou: {exc}. "
                  f"Aguardando {wait}s...")
            time.sleep(wait)

    raise RuntimeError(
        f"The ChEMBL server is unavailable after {max_retries} attempts. "
        f"Last error: {last_exc}\n"
        f"Check the status page: https://chembl.github.io/status/"
    ) from last_exc

def _chembl_total_count(resource_name, filter_kwargs, max_retries=5, backoff=(2, 5, 10, 20, 40)):
    params = {k: v for k, v in (filter_kwargs or {}).items() if v not in (None, "")}
    params.update({"limit": 1, "offset": 0})
    query = urllib.parse.urlencode(params, doseq=True)
    url = f"https://www.ebi.ac.uk/chembl/api/data/{resource_name}.json?{query}"

    last_exc = None
    for attempt in range(max_retries):
        try:
            with urllib.request.urlopen(url, timeout=30) as response:
                payload = json.load(response)
            page_meta = payload.get("page_meta") if isinstance(payload, dict) else None
            total_count = page_meta.get("total_count") if isinstance(page_meta, dict) else None
            if total_count is None:
                raise RuntimeError("Response did not include page_meta.total_count.")
            return int(total_count)
        except Exception as exc:
            last_exc = exc
            wait = backoff[min(attempt, len(backoff) - 1)]
            if attempt == max_retries - 1:
                break
            time.sleep(wait)

    raise RuntimeError(
        "Could not confirm how many records the ChEMBL portal should return for this query. "
        "Please try again later or check https://chembl.github.io/status/"
    ) from last_exc

class ChemblPartialDownload(Exception):
    """Levantada quando o usuário escolhe 'Stop Waiting' durante uma espera por página vazia.
    Carrega os registros já baixados até o momento da interrupção."""
    def __init__(self, records, expected_total, offset):
        self.records = records
        self.expected_total = expected_total
        self.offset = offset
        super().__init__(
            "The download was stopped by the user. "
            f"Partial dataset with {len(records)} of "
            f"{expected_total if expected_total is not None else '?'} expected records."
        )

def fetch_chembl_paginated(
    resource,
    filter_kwargs,
    fields,
    page_size=1000,
    max_retries=5,
    backoff=(2, 5, 10, 20, 40),
    resource_name=None,
    empty_page_retries=3,
    empty_page_backoff=(10, 20, 40, 60, 120),
    on_empty_page=None,
    stop_waiting_check=None,
):
    # Nota: o ajuste que corrige o bug de paginação do chembl_webresource_client (limite
    # interno fixo de 20 registros por página, ignorando page_size) precisa ser feito ANTES do
    # primeiro import de chembl_webresource_client.new_client no processo — por isso ele está
    # em get_chembl_client(), não aqui (ver comentário lá para detalhes).

    expected_total = None
    if resource_name:
        expected_total = _chembl_total_count(
            resource_name,
            filter_kwargs,
            max_retries=max_retries,
            backoff=backoff,
        )
        if expected_total == 0:
            return []

    all_records = []
    offset = 0
    empty_page_attempts = 0
    empty_page_prompt_sent = False

    while True:
        page = None
        for attempt in range(max_retries):
            try:
                page = list(
                    resource.filter(**filter_kwargs)
                    .only(fields)
                    [offset : offset + page_size]
                )
                break
            except Exception as exc:
                wait = backoff[min(attempt, len(backoff) - 1)]
                if attempt == max_retries - 1:
                    raise RuntimeError(
                        "The connection to the ChEMBL portal was interrupted while downloading the dataset. "
                        f"Last completed block: {len(all_records)} of {expected_total if expected_total is not None else '?'} records. "
                        "No partial dataset was saved. Please try again later."
                    ) from exc
                time.sleep(wait)

        if not page:
            if expected_total is not None and len(all_records) < expected_total:
                empty_page_attempts += 1
                wait = empty_page_backoff[min(empty_page_attempts - 1, len(empty_page_backoff) - 1)]

                if empty_page_attempts >= empty_page_retries and on_empty_page is not None and not empty_page_prompt_sent:
                    on_empty_page(offset, len(all_records), expected_total, wait)
                    empty_page_prompt_sent = True

                if stop_waiting_check is not None and stop_waiting_check():
                    raise ChemblPartialDownload(all_records, expected_total, offset)

                time.sleep(wait)
                continue
            break

        empty_page_attempts = 0
        empty_page_prompt_sent = False
        all_records.extend(page)
        offset += page_size

        if expected_total is not None and len(all_records) > expected_total:
            raise RuntimeError(
                "The ChEMBL portal returned more records than the announced total for this query. "
                "The download was cancelled to avoid inconsistent data."
            )

    if expected_total is not None and len(all_records) != expected_total:
        raise RuntimeError(
            "The ChEMBL download finished incompletely. "
            f"Expected {expected_total} records, received {len(all_records)}. "
            "No partial dataset was saved. Please try again later."
        )

    return all_records

# ==========================================================================================================================================
# ==================================== WEB SCRAPING DO PORTAL ChEMBL (fluxo "CSV" -> "Download File") ======================================
# ==========================================================================================================================================
# Reproduz, via chamadas HTTP diretas ao mesmo backend usado pelo site, o fluxo manual descrito em
# https://www.ebi.ac.uk/chembl/explore/target/<ID> -> "Activity Types for <ID> (...)" ->
# https://www.ebi.ac.uk/chembl/explore/activities/QUERYSTRING:target_chembl_id%3A<ID> -> botão "CSV" -> "Download File".
# O botão "CSV" do site dispara um job assíncrono (delayed_jobs) que é consultado por polling até
# status "FINISHED"; o resultado é um .zip contendo um único CSV separado por ";".

# Nomes dos campos confirmados em
# https://www.ebi.ac.uk/chembl/interface_api/es_proxy/properties_configuration/facets/chembl_activity/browser_facets
# e .../group/chembl_activity/browser_table
_CHEMBL_ACTIVITY_TARGET_TYPE_FIELD = "_metadata.target_data.target_type"

# Mapeia o rótulo nativo exportado pelo ChEMBL para o nome de campo usado no schema baseado em
# chembl_webresource_client (usado pelo restante do CODRUG), para que ferramentas de etapas
# seguintes consigam localizar a coluna por qualquer um dos dois nomes.
_CHEMBL_SCRAPE_COLUMN_ALIASES = {
    "Molecule ChEMBL ID": "molecule_chembl_id",
    "Smiles": "canonical_smiles",
    "Assay Description": "assay_description",
    "Assay Type": "assay_type",
    "Target ChEMBL ID": "target_chembl_id",
    "Target Organism": "target_organism",
    "Target Name": "target_pref_name",
    "Standard Type": "type",
    "Standard Units": "standard_unit",
    "Standard Value": "standard_value",
    "Value": "value",
}


def _add_chembl_api_schema_aliases(df):
    """Adiciona colunas-apelido no padrão snake_case da API, mantendo as colunas nativas do ChEMBL."""
    for native_label, api_name in _CHEMBL_SCRAPE_COLUMN_ALIASES.items():
        if native_label in df.columns and api_name not in df.columns:
            df[api_name] = df[native_label]
    if "Standard Units" in df.columns and "units" not in df.columns:
        df["units"] = df["Standard Units"]
    return df


# Sinônimos aceitos para cada nome de coluna "canônico" (o padrão snake_case já usado pelo
# restante do CODRUG, vindo do chembl_webresource_client). Cobre tanto os rótulos nativos do
# export por Web Scraping quanto os apelidos já adicionados por _add_chembl_api_schema_aliases,
# de modo que arquivos CSV mais antigos/baixados manualmente (sem os apelidos) também funcionem.
_CHEMBL_CANONICAL_COLUMN_SYNONYMS = {
    "units": ["units", "standard_unit", "Standard Units"],
    "type": ["type", "standard_type", "Standard Type"],
    "value": ["value", "Value"],
    "standard_value": ["standard_value", "Standard Value"],
    "molecule_chembl_id": ["molecule_chembl_id", "Molecule ChEMBL ID"],
    "canonical_smiles": ["canonical_smiles", "Smiles"],
    "target_chembl_id": ["target_chembl_id", "Target ChEMBL ID"],
    "target_organism": ["target_organism", "Target Organism"],
    "target_pref_name": ["target_pref_name", "Target Name"],
    "assay_description": ["assay_description", "Assay Description"],
    "assay_type": ["assay_type", "Assay Type"],
}


def _normalize_chembl_columns(df):
    """
    Garante que os nomes de coluna canônicos (usados por todo o Step 2 em diante) existam no
    DataFrame, preenchendo-os a partir do primeiro sinônimo encontrado (rótulo nativo do Web
    Scraping do ChEMBL, ex.: 'Standard Units', ou apelido já existente, ex.: 'standard_unit').
    Não remove nem sobrescreve nenhuma coluna já presente.
    """
    if df is None:
        return df
    for canonical, candidates in _CHEMBL_CANONICAL_COLUMN_SYNONYMS.items():
        if canonical in df.columns:
            continue
        for candidate in candidates:
            if candidate in df.columns:
                df[canonical] = df[candidate]
                break
    return df


def build_chembl_activity_lucene_query(target_type=None, target_organism=None,
                                        target_pref_name=None, target_chembl_id=None):
    def _quote(value):
        return '"' + str(value).replace('"', '\\"') + '"'

    clauses = []
    if target_chembl_id:
        clauses.append(f"target_chembl_id:{target_chembl_id.strip()}")
    if target_organism:
        clauses.append(f"target_organism:{_quote(target_organism.strip())}")
    if target_pref_name:
        clauses.append(f"target_pref_name:{_quote(target_pref_name.strip())}")
    if target_type:
        clauses.append(f"{_CHEMBL_ACTIVITY_TARGET_TYPE_FIELD}:{_quote(target_type.strip())}")
    return " AND ".join(clauses)


def scrape_chembl_activity_csv(lucene_query, poll_interval=30, max_wait_seconds=1800, on_progress=None):
    """
    Baixa os dados de activity do ChEMBL reproduzindo o mecanismo de 'delayed jobs' que o
    botão CSV do portal usa (submit -> poll status -> download .zip -> extrai o .csv).
    Retorna um DataFrame com as colunas nativas do export do ChEMBL (separador ';').
    """
    if not lucene_query:
        raise RuntimeError("No filter values were provided to build the ChEMBL search query.")

    submit_url = "https://www.ebi.ac.uk/chembl/interface_api/delayed_jobs/submit/download_job"
    inner_query = json.dumps({
        "bool": {
            "must": [{"query_string": {"query": lucene_query}}],
            "filter": [{"query_string": {"analyze_wildcard": True, "query": lucene_query}}],
            "should": [],
            "must_not": [],
        }
    })
    # O backend de delayed_jobs espera o corpo como application/x-www-form-urlencoded
    # (não JSON) — enviar como JSON resulta em "Missing data for required field" (HTTP 400).
    payload = urllib.parse.urlencode({
        "dl__ignore_cache": "false",
        "download_columns_group": "download",
        "format": "CSV",
        "index_name": "chembl_activity",
        "query": inner_query,
    }).encode("utf-8")

    req = urllib.request.Request(
        submit_url, data=payload,
        headers={"Content-Type": "application/x-www-form-urlencoded"},
        method="POST",
    )
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            submit_result = json.load(resp)
    except Exception as exc:
        raise RuntimeError(f"Could not submit the CSV export job to the ChEMBL portal: {exc}") from exc

    job_id = submit_result.get("job_id")
    if not job_id:
        raise RuntimeError("The ChEMBL portal did not return a job id for the CSV export request.")

    status_url = f"https://www.ebi.ac.uk/chembl/interface_api/delayed_jobs/status/{job_id}"
    elapsed = 0
    while True:
        try:
            with urllib.request.urlopen(status_url, timeout=30) as resp:
                status_payload = json.load(resp)
        except Exception as exc:
            raise RuntimeError(f"Could not check the status of the ChEMBL export job: {exc}") from exc

        status = status_payload.get("status")
        progress_raw = status_payload.get("progress")
        if on_progress is not None:
            try:
                percent = int(float(progress_raw)) if progress_raw not in (None, "") else 0
            except Exception:
                percent = 0
            try:
                on_progress(percent, status)
            except Exception:
                pass

        if status == "FINISHED":
            output_files = status_payload.get("output_files_urls") or {}
            if not output_files:
                raise RuntimeError("ChEMBL reported the export job as finished but provided no download URL.")
            file_url = next(iter(output_files.values()))
            if not file_url.startswith("http"):
                file_url = "https://" + file_url
            break

        if status in ("FAILED", "ERROR"):
            raise RuntimeError(f"The ChEMBL export job failed (status: {status}).")

        if elapsed >= max_wait_seconds:
            raise RuntimeError(
                f"The ChEMBL export job did not finish after waiting {max_wait_seconds} seconds. "
                "Please try again later."
            )
        time.sleep(poll_interval)
        elapsed += poll_interval

    try:
        with urllib.request.urlopen(file_url, timeout=120) as resp:
            zip_bytes = resp.read()
    except Exception as exc:
        raise RuntimeError(f"Could not download the generated CSV file from the ChEMBL portal: {exc}") from exc

    try:
        with zipfile.ZipFile(io.BytesIO(zip_bytes)) as zf:
            csv_names = [n for n in zf.namelist() if n.lower().endswith(".csv")]
            if not csv_names:
                raise RuntimeError("The downloaded ChEMBL export did not contain a CSV file.")
            csv_bytes = zf.read(csv_names[0])
    except zipfile.BadZipFile as exc:
        raise RuntimeError("The file downloaded from the ChEMBL portal is not a valid .zip archive.") from exc

    df = pd.read_csv(io.BytesIO(csv_bytes), sep=";", encoding="utf-8-sig")
    return _add_chembl_api_schema_aliases(df)


class ChemblScrapeWorker(QThread): # type: ignore
    result_signal = pyqtSignal(object, bool) # type: ignore
    error_signal = pyqtSignal(str) # type: ignore
    progress_signal = pyqtSignal(int, str) # type: ignore

    def __init__(self, lucene_query, file_path=None, poll_interval=30, parent=None):
        super().__init__(parent)
        self.lucene_query = lucene_query
        self.file_path = file_path
        self.poll_interval = poll_interval

    def run(self):
        try:
            df = scrape_chembl_activity_csv(
                self.lucene_query,
                poll_interval=self.poll_interval,
                on_progress=lambda percent, status: self.progress_signal.emit(percent, status or ""),
            )
            if self.file_path:
                df.to_csv(self.file_path, index=False)
            self.result_signal.emit(df, False)
        except Exception as e:
            self.error_signal.emit(str(e))

