class FeatureSelectionWorker(QThread): # type: ignore
    """
    Executa apply_recommended_selection em *thread separada* (não bloqueia a UI).
    Emite:
      - result_signal(df_out: pd.DataFrame, selected_cols: list[str])
      - error_signal(msg: str)
      - progress_signal(val: int)   # opcional, se quisermos animar um QProgressDialog
      - finished_signal()           # término (com ou sem erro)
    """
    result_signal = pyqtSignal(object, object) # type: ignore
    error_signal = pyqtSignal(str) # type: ignore
    progress_signal = pyqtSignal(int) # type: ignore
    finished_signal = pyqtSignal() # type: ignore

    def __init__(
        self,
        df_in: pd.DataFrame,
        method_name: str,
        first_feature_col: str,
        last_feature_col: str,
        y_series: Optional[pd.Series],
        task_type: str,
        model_type: Optional[str] = None,
        top_k: Union[int, str] = 20,
        corr_threshold: float = 0.95,
        variance_threshold: float = 0.0,
        alpha: float = 1.0,
        parent: Optional[QObject] = None,
    ):
        super().__init__(parent)
        self.df_in = df_in
        self.method_name = method_name
        self.first_feature_col = first_feature_col
        self.last_feature_col = last_feature_col
        self.y_series = y_series
        self.task_type = task_type
        self.model_type = model_type
        self.top_k = top_k
        self.corr_threshold = corr_threshold
        self.variance_threshold = variance_threshold
        self.alpha = alpha

    def run(self):
        try:
            # Se quiser, dá para emitir algum "progresso" fictício aqui
            # (por ex., 5%, 15%, ...), mas é opcional.
            self.progress_signal.emit(5)

            df_out, selected_cols = apply_recommended_selection(
                df_in=self.df_in,
                method_name=self.method_name,
                first_feature_col=self.first_feature_col,
                last_feature_col=self.last_feature_col,
                y_series=self.y_series,
                task_type=self.task_type,
                model_type=self.model_type,
                top_k=self.top_k,
                corr_threshold=self.corr_threshold,
                variance_threshold=self.variance_threshold,
                alpha=self.alpha,
            )

            self.progress_signal.emit(100)
            self.result_signal.emit(df_out, selected_cols)

        except Exception as e:
            self.error_signal.emit(str(e))

        finally:
            self.finished_signal.emit()

class ProjectionWorker(QThread): # type: ignore
    """
    Executa apply_recommended_projection em thread separada para manter a UI responsiva.
    Emite:
      - result_signal(df_out: pd.DataFrame, proj_cols: list[str], eval_info: dict)
      - error_signal(msg: str)
      - progress_signal(val: int)
      - finished_signal()
    """
    result_signal = pyqtSignal(object, object, object) # type: ignore
    error_signal = pyqtSignal(str) # type: ignore
    progress_signal = pyqtSignal(int) # type: ignore
    finished_signal = pyqtSignal() # type: ignore

    def __init__(
        self,
        df_in: pd.DataFrame,
        method_name: str,
        first_feature_col: str,
        last_feature_col: str,
        y_series: Optional[pd.Series],
        task_type: str,
        model_type: Optional[str] = None,
        n_components: Optional[int] = None,
        random_state: int = 123,
        var_thr: float = 0.90,
        extra_params: Optional[dict] = None,
        projection_artifact_path: Optional[str] = None,
        save_projection_artifact: bool = False,
        reuse_saved_projection: bool = False,
        parent: Optional[QObject] = None,
    ):
        super().__init__(parent)
        self.df_in = df_in
        self.method_name = method_name
        self.first_feature_col = first_feature_col
        self.last_feature_col = last_feature_col
        self.y_series = y_series
        self.task_type = task_type
        self.model_type = model_type
        self.n_components = n_components
        self.random_state = random_state
        self.var_thr = var_thr
        self.extra_params = extra_params or {}
        self.projection_artifact_path = projection_artifact_path
        self.save_projection_artifact = save_projection_artifact
        self.reuse_saved_projection = reuse_saved_projection

    def run(self):
        try:
            self.progress_signal.emit(5)

            df_out, proj_cols, eval_info = apply_recommended_projection(
                df_in=self.df_in,
                method_name=self.method_name,
                first_feature_col=self.first_feature_col,
                last_feature_col=self.last_feature_col,
                y_series=self.y_series,
                task_type=self.task_type,
                model_type=self.model_type,
                n_components=self.n_components,
                random_state=self.random_state,
                var_thr=self.var_thr,
                extra_params=self.extra_params,
                projection_artifact_path=self.projection_artifact_path,
                save_projection_artifact=self.save_projection_artifact,
                reuse_saved_projection=self.reuse_saved_projection,
            )

            self.progress_signal.emit(100)
            self.result_signal.emit(df_out, proj_cols, eval_info)

        except Exception as e:
            self.error_signal.emit(str(e))

        finally:
            self.finished_signal.emit()


class SklScreeningWorker(QThread): # type: ignore
    """Executa o screening de modelos scikit-learn (STEP 6) em background, emitindo progresso por modelo avaliado."""
    progress = pyqtSignal(str, dict)
    finished_all = pyqtSignal(object)
    error = pyqtSignal(str)

    def __init__(self, task, model_specs, x, y, random_state, test_size=0.3):
        super().__init__()
        self.task = task
        self.model_specs = model_specs  # lista de (nome, classe, kwargs)
        self.x = x
        self.y = y
        self.random_state = random_state
        self.test_size = test_size
        self.trained_models = {}
        self.x_train = self.x_test = self.y_train = self.y_test = None

    def run(self):
        # Força o joblib a usar threads (não processos via fork) — modelos com n_jobs=-1 (ex.: Bagging)
        # não podem fazer fork() de dentro de uma QThread de uma app Qt multithread: isso é uma causa
        # confirmada de crash (BrokenProcessPool ou, em casos piores, encerramento do processo principal
        # sem exceção Python capturável) ao final da operação.
        backend_ctx = joblib.parallel_backend("threading")
        backend_ctx.__enter__()
        try:
            rows = []
            if self.task == "clustering":
                for name, cls, kwargs in self.model_specs:
                    try:
                        model = _skl_instantiate(cls, kwargs, self.random_state)
                        if hasattr(model, "fit_predict"):
                            labels = model.fit_predict(self.x)
                        else:
                            model.fit(self.x)
                            labels = model.labels_
                        self.trained_models[name] = model
                        unique_labels = set(labels)
                        n_labels = len(unique_labels) - (1 if -1 in unique_labels else 0)
                        row = {"Model": name}
                        if n_labels >= 2:
                            row["Silhouette"] = float(silhouette_score(self.x, labels))
                            row["Davies-Bouldin"] = float(davies_bouldin_score(self.x, labels))
                            row["Calinski-Harabasz"] = float(calinski_harabasz_score(self.x, labels))
                        else:
                            row["Silhouette"] = float("nan")
                            row["Davies-Bouldin"] = float("nan")
                            row["Calinski-Harabasz"] = float("nan")
                        rows.append(row)
                        self.progress.emit(f"Model {name} successfully evaluated.", row)
                    except Exception as e:
                        self.progress.emit(f"Error evaluating model {name}: {e}", {})
            else:
                self.x_train, self.x_test, self.y_train, self.y_test = train_test_split(
                    self.x, self.y, test_size=self.test_size, random_state=self.random_state
                )
                for name, cls, kwargs in self.model_specs:
                    try:
                        kwargs = _skl_force_single_thread_kwargs(cls, kwargs)
                        model = _skl_instantiate(cls, kwargs, self.random_state)
                        model.fit(self.x_train, self.y_train)
                        self.trained_models[name] = model
                        y_train_pred = model.predict(self.x_train)
                        y_test_pred = model.predict(self.x_test)
                        row = {"Model": name}
                        if self.task == "regression":
                            row["R2 Train"] = float(r2_score(self.y_train, y_train_pred))
                            row["R2 Test"] = float(r2_score(self.y_test, y_test_pred))
                            m = float(mse(self.y_test, y_test_pred))
                            row["MSE"] = m
                            row["RMSE"] = m ** 0.5
                            row["MAE"] = float(mae(self.y_test, y_test_pred))
                        else:
                            row["Accuracy Train"] = float(accuracy_score(self.y_train, y_train_pred))
                            row["Accuracy Test"] = float(accuracy_score(self.y_test, y_test_pred))
                            row["F1"] = float(f1_score(self.y_test, y_test_pred, average="weighted"))
                            row["Precision"] = float(precision_score(self.y_test, y_test_pred, average="weighted", zero_division=0))
                            row["Recall"] = float(recall_score(self.y_test, y_test_pred, average="weighted"))
                            try:
                                if hasattr(model, "predict_proba"):
                                    proba = model.predict_proba(self.x_test)
                                    if proba.shape[1] == 2:
                                        row["AUC"] = float(roc_auc_score(self.y_test, proba[:, 1]))
                                    else:
                                        row["AUC"] = float(roc_auc_score(self.y_test, proba, multi_class="ovr", average="weighted"))
                                else:
                                    row["AUC"] = float("nan")
                            except Exception:
                                row["AUC"] = float("nan")
                        rows.append(row)
                        self.progress.emit(f"Model {name} successfully evaluated.", row)
                    except Exception as e:
                        self.progress.emit(f"Error evaluating model {name}: {e}", {})
            self.finished_all.emit(pd.DataFrame(rows))
        except Exception as e:
            self.error.emit(str(e))
        finally:
            backend_ctx.__exit__(None, None, None)


def _skl_grid_cv_results_to_df(cv_results_dict):
    cv_results = pd.DataFrame(cv_results_dict)
    keep_cols = [c for c in cv_results.columns if c.startswith("param_") or c in ("mean_test_score", "std_test_score", "rank_test_score")]
    return cv_results[keep_cols].sort_values("rank_test_score").reset_index(drop=True)


class SklTuneWorker(QThread): # type: ignore
    """Executa o Hyperparameter Tuning da STEP 6 (Grid/Randomized/Halving/Optuna) em background,
    liberando a thread principal (e o monitor de CPU/GPU) durante o ajuste."""
    finished_ok = pyqtSignal(object, object, object)  # best_model, best_params, cv_results_df
    error = pyqtSignal(str)

    def __init__(self, cls, base_kwargs, param_grid, method, folds, n_iter, random_state, x_train, y_train):
        super().__init__()
        self.cls = cls
        self.base_kwargs = base_kwargs
        self.param_grid = param_grid
        self.method = method
        self.folds = folds
        self.n_iter = n_iter
        self.random_state = random_state
        self.x_train = x_train
        self.y_train = y_train

    def run(self):
        # Força threads em vez de processos (fork) para o joblib — ver comentário em SklScreeningWorker.run().
        backend_ctx = joblib.parallel_backend("threading")
        backend_ctx.__enter__()
        try:
            cls, base_kwargs, param_grid = self.cls, self.base_kwargs, self.param_grid
            random_state, folds, method = self.random_state, self.folds, self.method
            # XGBoost/LightGBM usam threading nativo (OpenMP) fora do controle do joblib — força
            # single-thread no estimador para não competir com o paralelismo de nível superior do
            # GridSearchCV/RandomizedSearchCV (n_jobs=-1) nem causar instabilidade rodando em QThread.
            base_kwargs_st = _skl_force_single_thread_kwargs(cls, base_kwargs)
            base_model = _skl_instantiate(cls, base_kwargs_st, random_state)

            if method == "RandomizedSearchCV":
                search = RandomizedSearchCV(base_model, param_grid, n_iter=self.n_iter,
                                              cv=folds, random_state=random_state, n_jobs=-1)
                search.fit(self.x_train, self.y_train)
                best_model, best_params = search.best_estimator_, search.best_params_
                cv_results = _skl_grid_cv_results_to_df(search.cv_results_)
            elif method == "HalvingGridSearchCV":
                search = HalvingGridSearchCV(base_model, param_grid, cv=folds, random_state=random_state, n_jobs=-1)
                search.fit(self.x_train, self.y_train)
                best_model, best_params = search.best_estimator_, search.best_params_
                cv_results = _skl_grid_cv_results_to_df(search.cv_results_)
            elif method == "HalvingRandomSearchCV":
                search = HalvingRandomSearchCV(base_model, param_grid, cv=folds, random_state=random_state, n_jobs=-1)
                search.fit(self.x_train, self.y_train)
                best_model, best_params = search.best_estimator_, search.best_params_
                cv_results = _skl_grid_cv_results_to_df(search.cv_results_)
            elif method == "Bayesian Optimization (Optuna)":
                import optuna
                optuna.logging.set_verbosity(optuna.logging.WARNING)

                def objective(trial):
                    trial_params = {name: trial.suggest_categorical(name, values) for name, values in param_grid.items()}
                    trial_kwargs = _skl_force_single_thread_kwargs(cls, {**base_kwargs, **trial_params})
                    trial_model = _skl_instantiate(cls, trial_kwargs, random_state)
                    scores = cross_val_score(trial_model, self.x_train, self.y_train, cv=folds)
                    return float(scores.mean())

                study = optuna.create_study(direction="maximize")
                study.optimize(objective, n_trials=self.n_iter)
                best_params = study.best_params
                best_kwargs = _skl_force_single_thread_kwargs(cls, {**base_kwargs, **best_params})
                best_model = _skl_instantiate(cls, best_kwargs, random_state)
                best_model.fit(self.x_train, self.y_train)
                cv_results = study.trials_dataframe().sort_values("value", ascending=False).reset_index(drop=True)
            else:
                search = GridSearchCV(base_model, param_grid, cv=folds, n_jobs=-1)
                search.fit(self.x_train, self.y_train)
                best_model, best_params = search.best_estimator_, search.best_params_
                cv_results = _skl_grid_cv_results_to_df(search.cv_results_)

            self.finished_ok.emit(best_model, best_params, cv_results)
        except Exception as e:
            self.error.emit(str(e))
        finally:
            backend_ctx.__exit__(None, None, None)


def _skl_curve_compute_metric(metric, y_true, y_pred, model=None, x=None):
    """Calcula o valor de uma métrica (a mesma listada em 'Sort metric') para um par (y_true, y_pred),
    usado tanto no treino quanto no teste ao construir as curvas de Parameter/n_features."""
    if metric in ("R2 Test", "R2 Train", "R2"):
        return float(r2_score(y_true, y_pred))
    if metric == "RMSE":
        return float(mse(y_true, y_pred) ** 0.5)
    if metric == "MAE":
        return float(mae(y_true, y_pred))
    if metric == "MSE":
        return float(mse(y_true, y_pred))
    if metric in ("Accuracy Test", "Accuracy Train", "Accuracy"):
        return float(accuracy_score(y_true, y_pred))
    if metric == "F1":
        return float(f1_score(y_true, y_pred, average="weighted"))
    if metric == "Precision":
        return float(precision_score(y_true, y_pred, average="weighted", zero_division=0))
    if metric == "Recall":
        return float(recall_score(y_true, y_pred, average="weighted"))
    if metric == "AUC":
        if model is None or x is None or not hasattr(model, "predict_proba"):
            return float("nan")
        try:
            proba = model.predict_proba(x)
            if proba.shape[1] == 2:
                return float(roc_auc_score(y_true, proba[:, 1]))
            return float(roc_auc_score(y_true, proba, multi_class="ovr", average="weighted"))
        except Exception:
            return float("nan")
    return float("nan")


class SklTuneCurveWorker(QThread): # type: ignore
    """Gera a curva 'Sort metric' (Train/Test) vs. Parameter — ou vs. número de features (n_features,
    reproduzindo o gráfico do notebook original) — treinando/testando o modelo repetidamente em background."""
    finished_ok = pyqtSignal(dict)
    error = pyqtSignal(str)

    def __init__(self, cls, base_kwargs, parameter, metric, random_state, x_train, y_train, x_test, y_test, values=None):
        super().__init__()
        self.cls = cls
        self.base_kwargs = base_kwargs
        self.parameter = parameter
        self.metric = metric
        self.random_state = random_state
        self.x_train = x_train
        self.y_train = y_train
        self.x_test = x_test
        self.y_test = y_test
        self.values = values  # None quando parameter == "n_features"

    def run(self):
        # Força threads em vez de processos (fork) para o joblib — ver comentário em SklScreeningWorker.run().
        backend_ctx = joblib.parallel_backend("threading")
        backend_ctx.__enter__()
        try:
            if self.parameter == "n_features":
                result = self._run_n_features()
            else:
                result = self._run_param_range()
            self.finished_ok.emit(result)
        except Exception as e:
            self.error.emit(str(e))
        finally:
            backend_ctx.__exit__(None, None, None)

    # Número máximo de pontos calculados para a curva de n_features. Um dataset com centenas de
    # features (ex.: 881 bits de fingerprint) faria um fit por n=1..881 se avaliado exaustivamente —
    # centenas de fits sequenciais dentro de uma QThread de background, o que expõe instabilidades de
    # threading nativo (XGBoost/LightGBM usam OpenMP próprio, fora do controle do joblib) e é
    # desnecessariamente lento. Amostramos a curva em no máximo esse número de pontos, sempre incluindo
    # n=1 e n=total, preservando a forma da curva.
    MAX_N_FEATURES_POINTS = 40

    def _fit_and_score(self, x_tr, y_tr, x_te, y_te, kwargs_override=None):
        kwargs = dict(self.base_kwargs)
        if kwargs_override:
            kwargs.update(kwargs_override)
        kwargs = _skl_force_single_thread_kwargs(self.cls, kwargs)
        model = _skl_instantiate(self.cls, kwargs, self.random_state)
        model.fit(x_tr, y_tr)
        y_tr_pred = model.predict(x_tr)
        y_te_pred = model.predict(x_te)
        train_val = _skl_curve_compute_metric(self.metric, y_tr, y_tr_pred, model, x_tr)
        test_val = _skl_curve_compute_metric(self.metric, y_te, y_te_pred, model, x_te)
        return train_val, test_val

    def _run_n_features(self):
        base_kwargs = _skl_force_single_thread_kwargs(self.cls, self.base_kwargs)
        base_model = _skl_instantiate(self.cls, base_kwargs, self.random_state)
        base_model.fit(self.x_train, self.y_train)
        importances = getattr(base_model, "feature_importances_", None)
        if importances is None:
            coefs = getattr(base_model, "coef_", None)
            importances = np.abs(coefs).flatten() if coefs is not None else self.x_train.var().values

        feat_names = list(self.x_train.columns)
        order = np.argsort(importances)[::-1]
        ranked_features = [feat_names[i] for i in order]
        n_total = len(ranked_features)

        step = max(1, n_total // self.MAX_N_FEATURES_POINTS)
        n_steps = sorted(set(list(range(1, n_total + 1, step)) + [n_total]))

        x_values, train_values, test_values = [], [], []
        for n in n_steps:
            top_features = ranked_features[:n]
            train_val, test_val = self._fit_and_score(
                self.x_train[top_features], self.y_train, self.x_test[top_features], self.y_test
            )
            x_values.append(n)
            train_values.append(train_val)
            test_values.append(test_val)

        return {"x_values": x_values, "train_values": train_values, "test_values": test_values, "x_label": "Number of features"}

    def _run_param_range(self):
        x_values, train_values, test_values = [], [], []
        for v in self.values:
            train_val, test_val = self._fit_and_score(
                self.x_train, self.y_train, self.x_test, self.y_test, kwargs_override={self.parameter: v}
            )
            x_values.append(v)
            train_values.append(train_val)
            test_values.append(test_val)

        return {"x_values": x_values, "train_values": train_values, "test_values": test_values, "x_label": self.parameter}


class SklEvaluateWorker(QThread): # type: ignore
    """Executa a Validação (Cross-Validation) da STEP 6 em background, liberando a thread principal
    (e o monitor de CPU/GPU) durante o cálculo. mode: 'standard' (KFold/StratifiedKFold/LOOCV/
    Leave-P-Out/Time Series Split), 'nested' (Nested CV) ou 'bootstrap' (Bootstrap/OOB)."""
    finished_ok = pyqtSignal(object)  # cv_df
    error = pyqtSignal(str)

    def __init__(self, mode, task, current_model, x_reset, y_reset, **kwargs):
        super().__init__()
        self.mode = mode
        self.task = task
        self.current_model = current_model
        self.x_reset = x_reset
        self.y_reset = y_reset
        self.kwargs = kwargs

    def run(self):
        # Força threads em vez de processos (fork) para o joblib — ver comentário em SklScreeningWorker.run().
        backend_ctx = joblib.parallel_backend("threading")
        backend_ctx.__enter__()
        try:
            if self.mode == "nested":
                cv_df = self._run_nested()
            elif self.mode == "bootstrap":
                cv_df = self._run_bootstrap()
            else:
                cv_df = self._run_standard()
            self.finished_ok.emit(cv_df)
        except Exception as e:
            self.error.emit(str(e))
        finally:
            backend_ctx.__exit__(None, None, None)

    def _run_standard(self):
        x_reset, y_reset, task = self.x_reset, self.y_reset, self.task
        method = self.kwargs["method"]
        folds = self.kwargs["folds"]
        shuffle = self.kwargs["shuffle"]
        random_state = self.kwargs["random_state"]

        small_test_folds = False
        if method == "Leave-One-Out (LOOCV)":
            splitter = LeaveOneOut()
            split_iter = splitter.split(x_reset)
            small_test_folds = True
        elif method == "Leave-P-Out":
            p = self.kwargs["p"]
            splitter = LeavePOut(p=p)
            split_iter = splitter.split(x_reset)
            small_test_folds = (p == 1)
        elif method == "Time Series Split (Walk-Forward Validation)":
            splitter = TimeSeriesSplit(n_splits=folds)
            split_iter = splitter.split(x_reset)
        elif method == "StratifiedKFold" and task == "classification":
            splitter = StratifiedKFold(n_splits=folds, shuffle=shuffle, random_state=random_state if shuffle else None)
            split_iter = splitter.split(x_reset, y_reset)
        else:
            splitter = KFold(n_splits=folds, shuffle=shuffle, random_state=random_state if shuffle else None)
            split_iter = splitter.split(x_reset)

        rows = []
        all_y_true, all_y_pred = [], []
        for fold_num, (train_idx, test_idx) in enumerate(split_iter, start=1):
            x_tr, x_te = x_reset.iloc[train_idx], x_reset.iloc[test_idx]
            y_tr, y_te = y_reset.iloc[train_idx], y_reset.iloc[test_idx]
            fold_model = clone(self.current_model)
            fold_model.fit(x_tr, y_tr)
            y_pred = fold_model.predict(x_te)
            all_y_true.extend(list(y_te)); all_y_pred.extend(list(y_pred))

            row = {"Fold": fold_num, "Test Size": len(y_te)}
            if task == "regression":
                if not small_test_folds:
                    row["R2 Train"] = float(fold_model.score(x_tr, y_tr))
                    row["R2 Test"] = float(r2_score(y_te, y_pred))
                    m = float(mse(y_te, y_pred))
                    row["MSE"] = m
                    row["RMSE"] = m ** 0.5
                    row["MAE"] = float(mae(y_te, y_pred))
                else:
                    row["Abs Error"] = float(np.mean(np.abs(np.asarray(y_te) - np.asarray(y_pred))))
            else:
                if not small_test_folds:
                    row["Accuracy Train"] = float(fold_model.score(x_tr, y_tr))
                    row["Accuracy Test"] = float(accuracy_score(y_te, y_pred))
                    row["F1"] = float(f1_score(y_te, y_pred, average="weighted"))
                else:
                    row["Correct"] = bool(np.mean(np.asarray(y_te) == np.asarray(y_pred)) >= 0.5)
            rows.append(row)

        cv_df = pd.DataFrame(rows)
        summary = {"Fold": "OVERALL", "Test Size": len(all_y_true)}
        if task == "regression":
            if not small_test_folds:
                summary["R2 Train"] = float(cv_df["R2 Train"].mean())
            summary["R2 Test"] = float(r2_score(all_y_true, all_y_pred))
            m = float(mse(all_y_true, all_y_pred))
            summary["MSE"] = m
            summary["RMSE"] = m ** 0.5
            summary["MAE"] = float(mae(all_y_true, all_y_pred))
        else:
            if not small_test_folds:
                summary["Accuracy Train"] = float(cv_df["Accuracy Train"].mean())
            summary["Accuracy Test"] = float(accuracy_score(all_y_true, all_y_pred))
            summary["F1"] = float(f1_score(all_y_true, all_y_pred, average="weighted"))
        return pd.concat([cv_df, pd.DataFrame([summary])], ignore_index=True)

    def _run_nested(self):
        x_reset, y_reset, task = self.x_reset, self.y_reset, self.task
        cls = self.kwargs["cls"]
        base_kwargs = self.kwargs["base_kwargs"]
        param_grid = self.kwargs["param_grid"]
        folds = self.kwargs["folds"]
        shuffle = self.kwargs["shuffle"]
        random_state = self.kwargs["random_state"]
        inner_folds = self.kwargs["inner_folds"]

        if task == "classification":
            outer_splitter = StratifiedKFold(n_splits=folds, shuffle=shuffle, random_state=random_state if shuffle else None)
            outer_split_iter = outer_splitter.split(x_reset, y_reset)
        else:
            outer_splitter = KFold(n_splits=folds, shuffle=shuffle, random_state=random_state if shuffle else None)
            outer_split_iter = outer_splitter.split(x_reset)

        rows = []
        for fold_num, (train_idx, test_idx) in enumerate(outer_split_iter, start=1):
            x_tr, x_te = x_reset.iloc[train_idx], x_reset.iloc[test_idx]
            y_tr, y_te = y_reset.iloc[train_idx], y_reset.iloc[test_idx]
            inner_model = _skl_instantiate(cls, _skl_force_single_thread_kwargs(cls, base_kwargs), random_state)
            inner_search = GridSearchCV(inner_model, param_grid, cv=inner_folds, n_jobs=-1)
            inner_search.fit(x_tr, y_tr)
            y_pred = inner_search.predict(x_te)
            row = {"Outer Fold": fold_num, "Best Params": str(inner_search.best_params_)}
            if task == "regression":
                row["R2 Test"] = float(r2_score(y_te, y_pred))
                m = float(mse(y_te, y_pred))
                row["MSE"] = m
                row["RMSE"] = m ** 0.5
                row["MAE"] = float(mae(y_te, y_pred))
            else:
                row["Accuracy Test"] = float(accuracy_score(y_te, y_pred))
                row["F1"] = float(f1_score(y_te, y_pred, average="weighted"))
            rows.append(row)
        return pd.DataFrame(rows)

    def _run_bootstrap(self):
        x_reset, y_reset, task = self.x_reset, self.y_reset, self.task
        n_iterations = self.kwargs["n_iterations"]
        random_state = self.kwargs["random_state"]
        n_samples = len(x_reset)
        rng = np.random.RandomState(random_state)

        rows = []
        for it in range(1, n_iterations + 1):
            boot_idx = rng.randint(0, n_samples, n_samples)
            oob_idx = np.setdiff1d(np.arange(n_samples), boot_idx)
            if len(oob_idx) == 0:
                continue
            x_tr, y_tr = x_reset.iloc[boot_idx], y_reset.iloc[boot_idx]
            x_te, y_te = x_reset.iloc[oob_idx], y_reset.iloc[oob_idx]
            fold_model = clone(self.current_model)
            fold_model.fit(x_tr, y_tr)
            y_pred = fold_model.predict(x_te)
            row = {"Iteration": it, "OOB Size": len(oob_idx)}
            if task == "regression":
                row["R2 Test"] = float(r2_score(y_te, y_pred))
                m = float(mse(y_te, y_pred))
                row["MSE"] = m
                row["RMSE"] = m ** 0.5
                row["MAE"] = float(mae(y_te, y_pred))
            else:
                row["Accuracy Test"] = float(accuracy_score(y_te, y_pred))
                row["F1"] = float(f1_score(y_te, y_pred, average="weighted"))
            rows.append(row)

        if not rows:
            raise ValueError("No out-of-bag samples were produced — dataset may be too small for Bootstrap.")
        return pd.DataFrame(rows)


class _WaitMessageProcessHandle:
    """Referência ao processo separado da janela de espera (MODULES/wait_message_window.py), com um
    método close() no mesmo formato do QDialog que ela substituiu, para não exigir mudanças nos
    pontos que chamam show_wait_message_dialog()."""

    def __init__(self, proc):
        self._proc = proc

    def close(self):
        if self._proc is None:
            return
        try:
            if self._proc.poll() is None:
                self._proc.terminate()
        except Exception:
            pass
        finally:
            self._proc = None


