        # bandeiras ao lado do CPU/GPU Monitor). self._i18n_registry guarda (chave, apply_fn,
        # kwargs) para cada texto traduzido, permitindo reaplicar tudo instantaneamente ao trocar
        # de idioma sem precisar reconstruir nenhum widget.
        self._idioma = QSettings("CODRUG", "CODRUG").value("idioma", i18n.IDIOMA_PADRAO)
        if self._idioma not in ("en", "pt"):
            self._idioma = i18n.IDIOMA_PADRAO
        self._i18n_registry = []

        self._tr("app_titulo", self.setWindowTitle)
        app = QApplication.instance()
        if app is not None:
            app.setStyleSheet(_SS_MAIN)
        else:
            self.setStyleSheet(_SS_MAIN)
        screen = QGuiApplication.primaryScreen()
        size = screen.availableGeometry()
        self.resize(size.width() // 3, size.height() // 2)
        self.move((size.width() - self.width()) // 3, (size.height() - self.height()) // 2)
        
        # PASTA DE TRABALHO
        self.dp_dir = os.path.abspath(os.path.dirname(__file__))
        self.data_str = datetime.now().strftime("%Y-%m-%d_%H-%M")
        
        # Atribuir df_selecionado como None inicialmente:
