    def ensure_chembl_available(self):
        status_result = {"available": False}
        progress = QProgressDialog(i18n.t("msg_checking_chembl", self._idioma), None, 0, 0, self)
        progress.setWindowTitle(i18n.t("msg_wait", self._idioma))
        progress.setWindowModality(Qt.ApplicationModal)
        progress.setMinimumDuration(0)
        progress.setCancelButton(None)
        progress.setAutoClose(False)
        progress.setAutoReset(False)
        progress.setValue(0)

        worker = ChemblStatusWorker(self)
        worker.status_checked.connect(lambda is_available: status_result.__setitem__("available", is_available))
        worker.finished.connect(progress.close)

        self._chembl_status_worker = worker
        worker.start()
        progress.exec_()
        worker.wait()
        self._chembl_status_worker = None

        if status_result["available"]:
            return True

        QMessageBox.warning(
            self, i18n.t("msg_chembl_unavailable_title", self._idioma),
            i18n.t("msg_chembl_unavailable_body", self._idioma)
        )
        return False

