    def run_method_rep(self):
        target_chembl_id = self.ed_target_chembl_id.text().strip()
        target_organism = self.ed_organism_name.text().strip()
        job_dir = self.job_dir  
        if getattr(self, "df_selecionado", None) is None:
            QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), "No filtered DataFrame available.")
            return

        col_rep = self.list_columns_rep.currentText()
        col_type = self.list_types.currentText()
        method = self.list_methods_rep.currentText()

        if not col_rep or not col_type or not method:
            QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), "Select column, type, and method.")
            return

        df = self.df_selecionado.copy()

        def remove_outliers(values):
            # Usando IQR para remover outliers
            q1 = values.quantile(0.25)
            q3 = values.quantile(0.75)
            iqr = q3 - q1
            mask = (values >= (q1 - 1.5 * iqr)) & (values <= (q3 + 1.5 * iqr))
            return values[mask]

        agg_func = None

        if method == "Median":
            agg_func = lambda x: pd.Series({
                col_type: x[col_type].median(),
                **{k: x.iloc[0][k] for k in x.columns if k != col_type}
            })
        elif method == "Mean":
            agg_func = lambda x: pd.Series({
                col_type: x[col_type].mean(),
                **{k: x.iloc[0][k] for k in x.columns if k != col_type}
            })
        elif method == "Mode":
            agg_func = lambda x: pd.Series({
                col_type: int(round(x[col_type].mode().iloc[0])) if not x[col_type].mode().empty else int(round(x[col_type].iloc[0])),
                **{k: x.iloc[0][k] for k in x.columns if k != col_type}
            })
        elif method == "Median(Log10)":
            agg_func = lambda x: pd.Series({
                col_type: 10 ** (np.log10(x[col_type].replace(0, np.nan)).median()),
                **{k: x.iloc[0][k] for k in x.columns if k != col_type}
            })
        elif method == "Median(without outliers)":
            agg_func = lambda x: pd.Series({
                col_type: remove_outliers(x[col_type]).median(),
                **{k: x.iloc[0][k] for k in x.columns if k != col_type}
            })
        else:
            QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), "Unknown method selected.")
            return

        # Agrupa e aplica a função de agregação
        df_result = df.groupby(col_rep, as_index=False).apply(agg_func)
        df_result.reset_index(drop=True, inplace=True)
        
        # Move col_type para última posição
        cols = [c for c in df_result.columns if c != col_type] + [col_type]
        df_result = df_result[cols]
        
        # Salva o dataframe e exibe:
        file_path = os.path.join(job_dir, "DATA_BASES", "INTERNAL_DATA", f'df2_TratRepetitions_{target_chembl_id}_{target_organism}.csv')
        df_result.to_csv(file_path, index=False)
        self.df_selecionado = df_result
        self.show_dataframe(df_result)
        self.df_name_view.setText(os.path.basename(file_path))
        self._refresh_step2_dataframe_widgets()
        self._save_step2_state()

