    def run_del_nulls(self):
        import os
        import numpy as np
        import pandas as pd
        from pandas.api.types import is_numeric_dtype

        if getattr(self, "df_selecionado", None) is None:
            QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), "No filtered DataFrame available.")
            return

        df = self.df_selecionado

        # --- Helpers -------------------------------------------------------------
        def infer_col_type(s: pd.Series) -> str:
            """Infer column intended type: 'numeric' or 'string'."""
            # If dtype already numeric, accept numeric
            if is_numeric_dtype(s):
                return "numeric"
            # Consider non-null and non-empty values
            non_null = s.dropna()
            if non_null.empty:
                # default to string when undecidable
                return "string"
            # Remove pure empties for the heuristic
            def _is_empty(x):
                return isinstance(x, str) and (x.strip() == "")
            non_empty = non_null[~non_null.apply(_is_empty)]
            if non_empty.empty:
                return "string"
            # Try numeric coercion on what's left; if all coerce, treat as numeric
            coerced = pd.to_numeric(non_empty, errors="coerce")
            if coerced.notna().all():
                return "numeric"
            return "string"

        def empty_mask(s: pd.Series) -> pd.Series:
            """Empty = string com somente espaços (ou string vazia)."""
            return s.apply(lambda v: isinstance(v, str) and (v.strip() == ""))

        def type_mismatch_mask(s: pd.Series, col_type: str, empties: pd.Series) -> pd.Series:
            """Valores não nulos, não vazios, mas incompatíveis com o tipo inferido."""
            not_null_not_empty = (~s.isna()) & (~empties)
            if col_type == "numeric":
                ok_num = pd.to_numeric(s.where(not_null_not_empty), errors="coerce").notna()
                return (~ok_num) & not_null_not_empty
            else:  # string
                is_str = s.apply(lambda v: isinstance(v, str))
                return (~is_str) & not_null_not_empty

        # --- Coleta de contagens e máscaras por coluna --------------------------
        summary_rows = []
        invalid_masks = []

        for col in df.columns:
            s = df[col]
            ctype = infer_col_type(s)
            nulls = s.isna()
            empties = empty_mask(s)
            mismatches = type_mismatch_mask(s, ctype, empties)

            summary_rows.append({
                "Column": col,
                "Type": ctype,
                "Null": int(nulls.sum()),
                "Empty": int(empties.sum()),
                "OutOfType": int(mismatches.sum())
            })

            invalid_masks.append(nulls | empties | mismatches)

        # --- DataFrame de resumo -------------------------------------------------
        df_summary = pd.DataFrame(summary_rows, columns=["Column", "Type", "Null", "Empty", "OutOfType"])
        # Ordena pelas maiores ocorrências (apenas para facilitar leitura)
        df_summary = df_summary.sort_values(by=["Null", "Empty", "OutOfType"], ascending=False).reset_index(drop=True)

        # Mostra o resumo
        self.show_dataframe(df_summary)

        # --- Eliminação das linhas inválidas ------------------------------------
        if invalid_masks:
            invalid_any = np.column_stack([m.values for m in invalid_masks]).any(axis=1)
        else:
            invalid_any = np.zeros(len(df), dtype=bool)

        df_clean = df.loc[~invalid_any].copy()

        # --- Salva o dataframe limpo --------------------------------------------
        try:
            base_dir = getattr(self, "job_dir", os.getcwd())
            out_dir = os.path.join(base_dir, "DATA_BASES", "INTERNAL_DATA")
            os.makedirs(out_dir, exist_ok=True)
            target_chembl_id = self.ed_target_chembl_id.text().strip() if hasattr(self, "ed_target_chembl_id") else ""
            target_organism = self.ed_organism_name.text().strip() if hasattr(self, "ed_organism_name") else ""
            out_path = os.path.join(out_dir, f"df2_NullEmptyFiltered_{target_chembl_id}_{target_organism}.csv")
            df_clean.to_csv(out_path, index=False)
        except Exception as e:
            print(f"[run_del_nulls] Warning when saving a clean dataframe: {e}")
            out_path = None

        # --- Atualiza estado e exibe --------------------------------------------
        self.df_selecionado = df_clean
        if out_path:
            self._next_dataframe_save_path = out_path
        self.show_dataframe(self.df_selecionado)
        if out_path:
            self.df_name_view.setText(os.path.basename(out_path))
        self._refresh_step2_dataframe_widgets()

        # Mensagem opcional (silenciosa se preferir)
        if out_path:
            print(f"[run_del_nulls] Clean DataFrame saved at: {out_path}")
        self._save_step2_state()

    def run_convert_types(self):

        def _norm_type(x: str) -> str:
            # normaliza rótulos do tipo ('pIC50', '-logIC50', 'MIC', etc.)
            t = str(x).strip().lower()
            t = t.replace(' ', '').replace('_', '').replace('(', '').replace(')', '')
            # converte variantes logarítmicas em 'p'
            t = t.replace('-log10', 'p').replace('log10', 'p').replace('-log', 'p').replace('log', 'p')
            t = t.replace('-', '')
            return t  # esperado: 'ic50', 'pic50', 'mic', 'pmic', etc.

        type_name = str(self.list_types.currentText()).strip()

        df = self.df_selecionado
        if df is None:
            QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), "No filtered DataFrame available.")
            return

        target_chembl_id = self.ed_target_chembl_id.text().strip() if hasattr(self, "ed_target_chembl_id") else ""
        target_organism = self.ed_organism_name.text().strip() if hasattr(self, "ed_organism_name") else ""
        out_dir = os.path.join(self.job_dir, "DATA_BASES", "INTERNAL_DATA")
        os.makedirs(out_dir, exist_ok=True)
        file_path = os.path.join(out_dir, f"df2_Type_{target_chembl_id}_{target_organism}.csv")

        df = df.copy()

        # Garantir colunas esperadas
        if 'value' not in df.columns or 'type' not in df.columns:
            QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), "DataFrame must have 'value' and 'type' columns.")
            return

        # Normaliza rótulos
        norm = df['type'].map(_norm_type)

        # Vetores numéricos
        vals = pd.to_numeric(df['value'], errors='coerce')

        # Conjuntos de máscaras
        is_ic50  = norm.eq('ic50')
        is_pic50 = norm.eq('pic50')
        is_mic   = norm.eq('mic')
        is_pmic  = norm.eq('pmic')

        # Conversões solicitadas
        tn = type_name.strip().lower()

        if tn == 'ic50':
            # converter somente onde o dado atual está em pIC50
            df.loc[is_pic50, 'value'] = np.power(10.0, -vals[is_pic50])
            df['type'] = 'IC50'

        elif tn == 'pic50':
            # converter somente onde o dado atual está em IC50
            # proteger contra valores <= 0
            safe = is_ic50 & (vals > 0)
            df.loc[safe, 'value'] = -np.log10(vals[safe])
            # onde inválido, manter original
            df['type'] = 'pIC50'

        elif tn == 'mic':
            # converter somente onde o dado atual está em pMIC
            df.loc[is_pmic, 'value'] = np.power(10.0, -vals[is_pmic])
            df['type'] = 'MIC'

        elif tn == 'pmic':
            # converter somente onde o dado atual está em MIC
            safe = is_mic & (vals > 0)
            df.loc[safe, 'value'] = -np.log10(vals[safe])
            df['type'] = 'pMIC'

        else:
            QMessageBox.information(self, i18n.t("msg_title_info", self._idioma), f"Target type '{type_name}' does not require conversion.")
            # ainda assim renomeia a coluna para manter consistência
            df = df.rename(columns={'value': type_name})
            df.to_csv(file_path, index=False)
            self._next_dataframe_save_path = file_path
            self.show_dataframe(df)
            self.df_selecionado = df
            self.df_name_view.setText(os.path.basename(file_path))
            self._refresh_step2_dataframe_widgets()
            self._save_step2_state()
            return

        # Renomeia a coluna 'value' para o tipo de destino
        df = df.rename(columns={'value': type_name})

        # Feedback sobre conversões inválidas:
        # ex.: quantos valores ficaram NaN após conversão
        invalid_count = df[type_name].isna().sum()

        df.to_csv(file_path, index=False)
        self._next_dataframe_save_path = file_path
        self.show_dataframe(df)
        self.df_selecionado = df
        self.df_name_view.setText(os.path.basename(file_path))
        self._refresh_step2_dataframe_widgets()
        self._save_step2_state()

    def run_convert_units(self):
        """
        Converte a coluna de bioatividade (self.type_name) para a unidade-alvo escolhida
        em self.list_units. Suporta:
        • Molaridade: M, mM, uM/μM/µM, nM (e variantes: mol/L, mmol/L, umol l-1, etc.)
        • Massa/volume (solução): ng/uL, ug/mL, mg/L, g/L, etc. (para M usando MW)
        • Dose por massa corporal: ng/g, ug/g, mg/g, g/g, ng/kg, ug/kg, mg/kg, g/kg
            (conversões apenas entre estas, SEM envolver MW e SEM misturar com molaridade).
        A unidade de destino pode ser molar OU dose por massa. O comportamento é:
        • Se destino é molar: só converte se a origem for molar ou massa/volume (requer MW).
            Se origem for dose por massa (ex.: mg/kg), não converte → NaN + aviso.
        • Se destino é dose por massa: só converte se origem também for dose por massa.
            Se origem for molar ou massa/volume, não converte → NaN + aviso.
        """
        # ---------------- Pré-checagens ----------------
        if getattr(self, "df_selecionado", None) is None or self.df_selecionado.empty:
            QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), "No DataFrame loaded.")
            return
        if "units" not in self.df_selecionado.columns:
            QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), "Column 'units' not found in the DataFrame.")
            return

        # coluna de valor a converter
        self.type_name = self.list_types.currentText()
        if self.type_name not in self.df_selecionado.columns:
            QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), f"Column '{self.type_name}' not found in the DataFrame.")
            return

        # ---------------- 1) (Opcional) MW por SMILES para rota massa/volume→molar ----------------
        # Só calculamos MW se ele for necessário (origem massa/volume OU destino molar).
        need_mw = False  # definido mais adiante, após normalizar unidades
        if "canonical_smiles" in self.df_selecionado.columns:
            smis = self.df_selecionado["canonical_smiles"].astype(str).str.strip()
        else:
            smis = pd.Series([None] * len(self.df_selecionado), index=self.df_selecionado.index)

        # ---------------- 2) Normalizador de unidades ----------------
        # Aceita:
        #   - molaridades: M, mM, uM/μM/µM, nM, mol/L, mmol/L, umol l-1, etc.
        #   - massa/volume (solução): ng/ug/mg/g × uL/mL/L (+ variações com L-1, ".", espaços)
        #   - dose por massa corporal: ng/g, ug/g, mg/g, g/g, ng/kg, ug/kg, mg/kg, g/kg
        def _canon_unit(u: str) -> str:
            if u is None:
                return ""
            s = str(u)

            # micro, traço, espaços e underscores
            s = s.replace("μ", "u").replace("µ", "u")
            s = s.replace("−", "-")
            s = s.strip()
            s = re.sub(r"[\s_]+", "", s)
            s = s.lower()

            # "per" -> "/"
            s = s.replace("per", "/")

            # expoentes de volume: ul-1, ml-1, l-1 -> "/ul", "/ml", "/l"
            s = re.sub(r"(ul|ml|l)[\.\s]*-?1\b", r"/\1", s)
            # expoentes de massa corporal: g-1, kg-1 -> "/g", "/kg"
            s = re.sub(r"(g|kg)[\.\s]*-?1\b", r"/\1", s)

            # sem separador explícito em massa/volume: "ugml" -> "ug/ml"
            s = re.sub(r"^(ng|ug|mg|g)(ul|ml|l)$", r"\1/\2", s)
            # sem separador explícito em dose/massa: "mgkg" -> "mg/kg", "ugg" -> "ug/g"
            s = re.sub(r"^(ng|ug|mg|g)(kg)$", r"\1/\2", s)
            s = re.sub(r"^(ng|ug|mg|g)(g)$", r"\1/\2", s)

            # normaliza separadores ocasionais
            if "/" not in s:
                s = s.replace("\\", "/").replace(".", "/")

            # molaridades mapeadas
            mol_alias = {
                "m": "M", "mol/l": "M", "moll-1": "M",
                "mm": "mM", "mmol/l": "mM", "mmoll-1": "mM",
                # Micromolar: aceita umol, µmol, μmol
                "um": "uM", "umol": "uM", "umol/l": "uM", "umoll-1": "uM",
                "µmol": "uM", "µmol/l": "uM", "μmol": "uM", "μmol/l": "uM",
                "nm": "nM", "nmol": "nM", "nmol/l": "nM", "nmoll-1": "nM",
            }
            if s in mol_alias:
                return mol_alias[s]
            if s.endswith("/l"):
                if s == "mol/l":   return "M"
                if s == "mmol/l":  return "mM"
                if s == "umol/l":  return "uM"
                if s == "nmol/l":  return "nM"

            # massa/volume canônico
            def _vol_fix(tok: str) -> str:
                tok = tok.lower()
                if tok == "ul":  return "uL"
                if tok == "ml":  return "mL"
                if tok == "l":   return "L"
                return tok

            def _mass_fix(tok: str) -> str:
                tok = tok.lower()
                if tok in {"ng", "ug", "mg", "g"}:
                    return tok
                return tok

            # massa/volume
            if "/" in s:
                parts = s.split("/", 1)
                if len(parts) == 2:
                    left, right = parts
                    # Caso 1: massa/volume (ex.: mg/mL)
                    if right in {"ul", "ml", "l"}:
                        m = _mass_fix(left)
                        v = _vol_fix(right)
                        if m in {"ng", "ug", "mg", "g"} and v in {"uL", "mL", "L"}:
                            return f"{m}/{v}"
                    # Caso 2: dose/massa corporal (ex.: mg/kg, ug/g)
                    if right in {"kg", "g"}:
                        m = _mass_fix(left)
                        d = right.lower()
                        if m in {"ng", "ug", "mg", "g"} and d in {"kg", "g"}:
                            return f"{m}/{d}"

            # variantes tipo "ugml-1", "mg l-1", "ngul-1"
            s2 = re.sub(r"(ng|ug|mg|g)[\.\s]*(ul|ml|l)-?1\b", r"\1/\2", s)
            if s2 != s:
                return _canon_unit(s2)
            # variantes tipo "mgkg-1", "ugg-1"
            s3 = re.sub(r"(ng|ug|mg|g)[\.\s]*(kg|g)-?1\b", r"\1/\2", s)
            if s3 != s:
                return _canon_unit(s3)

            return s.upper()  # deixa visível se incomum

        # fatores
        MASS_TO_G = {"ng": 1e-9, "ug": 1e-6, "mg": 1e-3, "g": 1.0}
        VOL_TO_L  = {"uL": 1e-6, "mL": 1e-3, "L": 1.0}
        BODYMASS_TO_G = {"g": 1.0, "kg": 1000.0}

        # Classificação rápida de unidade normalizada
        def _class_unit(u_norm: str) -> str:
            if u_norm in {"M", "mM", "uM", "nM"}:
                return "MOLAR"
            if "/" in u_norm:
                left, right = u_norm.split("/", 1)
                if right in {"uL", "mL", "L"} and left in MASS_TO_G:
                    return "MASS_PER_VOLUME"
                if right in {"g", "kg"} and left in MASS_TO_G:
                    return "MASS_PER_BODY"
            return "UNKNOWN"

        # Conversões auxiliares
        def _to_M_from_unit(value, unit_norm, mw):
            """Converte valor na unidade unit_norm para M (mol/L). Suporta molar e massa/volume."""
            if unit_norm == "M":   return value
            if unit_norm == "mM":  return value * 1e-3
            if unit_norm == "uM":  return value * 1e-6
            if unit_norm == "nM":  return value * 1e-9
            if "/" in unit_norm:
                left, right = unit_norm.split("/", 1)
                # massa/volume -> M: (g/L)/MW
                if right in VOL_TO_L and left in MASS_TO_G and mw and mw > 0:
                    g_per_L = value * (MASS_TO_G[left] / VOL_TO_L[right])
                    return g_per_L / mw
            return float("nan")

        def _from_M_to_mass_per_volume(value_M, unit_dst, mw):
            """Converte molaridade (M) para massa/volume alvo usando MW."""
            if pd.isna(value_M) or pd.isna(mw) or mw <= 0 or "/" not in unit_dst:
                return float("nan")
            left, right = unit_dst.split("/", 1)
            if left not in MASS_TO_G or right not in VOL_TO_L:
                return float("nan")
            g_per_L = value_M * mw
            return g_per_L * (VOL_TO_L[right] / MASS_TO_G[left])

        def _per_body_convert(value, unit_src, unit_dst):
            """
            Converte dose por massa corporal entre:
                ng/g, ug/g, mg/g, g/g,  ng/kg, ug/kg, mg/kg, g/kg
            Sem uso de MW (apenas fatores).
            Fórmula: val * (num_src * den_dst) / (den_src * num_dst),
            onde num_* em g; den_* em g (kg = 1000 g).
            """
            num_s, den_s = unit_src.split("/", 1)
            num_d, den_d = unit_dst.split("/", 1)
            num_s_g = MASS_TO_G[num_s]
            num_d_g = MASS_TO_G[num_d]
            den_s_g = BODYMASS_TO_G[den_s]  # g ou kg → g
            den_d_g = BODYMASS_TO_G[den_d]
            return value * (num_s_g * den_d_g) / (den_s_g * num_d_g)

        # ---------------- 3) Normaliza origem e destino ----------------
        self.df_selecionado["units_norm"] = self.df_selecionado["units"].map(_canon_unit)
        self.unit_name = self.list_units.currentText()
        target_norm = _canon_unit(self.unit_name)

        src_kind = _class_unit(self.df_selecionado["units_norm"].iloc[0]) if len(self.df_selecionado) else "UNKNOWN"
        dst_kind = _class_unit(target_norm)

        # Decidimos se MW será preciso
        if dst_kind in {"MOLAR", "MASS_PER_VOLUME"} or src_kind == "MASS_PER_VOLUME":
            need_mw = True

        # calcular MW se necessário
        if need_mw:
            if "canonical_smiles" not in self.df_selecionado.columns:
                QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma),
                                    "Canonical SMILES required to compute MW for mass/volume ↔ molar conversions.")
                return
            mw_map = {}
            for s in pd.unique(smis):
                mol = Chem.MolFromSmiles(s) if s else None
                mw_map[s] = np.nan if mol is None else Descriptors.MolWt(mol)
            self.df_selecionado["MW"] = smis.map(mw_map).round(2)
        else:
            # se já existir MW, mantemos; se não, tudo bem (não usado)
            if "MW" not in self.df_selecionado.columns:
                self.df_selecionado["MW"] = np.nan

        # ---------------- 4) Aplicar conversão conforme o destino ----------------
        val = self.df_selecionado[self.type_name].astype(float)
        unit_src = self.df_selecionado["units_norm"]

        # (A) destino molar → usa sua lógica (4 conversores)
        if dst_kind == "MOLAR":
            # Se origem for dose por massa corporal, não converter (avisar uma vez)
            if (unit_src.str.contains(r"/(g|kg)$")).any():
                if not hasattr(self, "_warned_bodymass_to_molar"):
                    try:
                        QMessageBox.information(
                            self, "Units: dose per body mass",
                            "The source is in dose per body mass (e.g., mg/kg). "
                            "As requested, it will not be converted to molarity."
                        )
                    except Exception:
                        pass
                    self._warned_bodymass_to_molar = True

            def converter_para_nM(row):
                return _to_M_from_unit(row[self.type_name], row["units_norm"], row["MW"]) * 1e9

            def converter_para_uM(row):
                return _to_M_from_unit(row[self.type_name], row["units_norm"], row["MW"]) * 1e6

            def converter_para_mM(row):
                return _to_M_from_unit(row[self.type_name], row["units_norm"], row["MW"]) * 1e3

            def converter_para_M(row):
                return _to_M_from_unit(row[self.type_name], row["units_norm"], row["MW"])

            conv = {
                "nM": converter_para_nM,
                "uM": converter_para_uM,
                "mM": converter_para_mM,
                "M":  converter_para_M,
            }.get(target_norm)

            if conv is None:
                QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma),
                                    f"No conversion function for unit '{self.unit_name}' (normalized: '{target_norm}').")
                return

            try:
                self.df_selecionado[self.type_name] = self.df_selecionado.apply(conv, axis=1)
            except Exception as e:
                QMessageBox.critical(self, i18n.t("msg_title_error_during_unit_conversion", self._idioma), str(e))
                return

            pretty = {"M": "mol/L", "mM": "mmol/L", "uM": "μmol/L", "nM": "nmol/L"}
            self.df_selecionado["units"] = pretty.get(target_norm, target_norm)

        # (B) destino dose por massa corporal → converter apenas se origem também for dose por massa
        elif dst_kind == "MASS_PER_BODY":
            # Verifica se TODAS as linhas estão em dose por massa corporal; se não, NaN+aviso
            mask_src_body = unit_src.str.contains(r"/(g|kg)$")
            if not mask_src_body.all():
                if not hasattr(self, "_warned_mismatch_bodymass"):
                    try:
                        QMessageBox.information(self, i18n.t("msg_title_units_incompatible_source", self._idioma),
                            "To convert to dose per body mass (e.g., mg/kg),"
                            "the source must also be in dose per body mass."
                            "Lines in other units will be marked as NaN."
                        )
                    except Exception:
                        pass
                    self._warned_mismatch_bodymass = True

            # Converte linha a linha quando possível
            tgt = target_norm  # ex.: "mg/kg" ou "ug/g"
            out = []
            for i, row in self.df_selecionado.iterrows():
                u_src = row["units_norm"]
                x = float(row[self.type_name])
                if _class_unit(u_src) == "MASS_PER_BODY":
                    out.append(_per_body_convert(x, u_src, tgt))
                else:
                    out.append(np.nan)  # incompatível, conforme regra definida
            self.df_selecionado[self.type_name] = pd.to_numeric(out, errors="coerce")
            self.df_selecionado["units"] = target_norm

        # (C) destino MASS_PER_VOLUME -> converte via M usando MW
        elif dst_kind == "MASS_PER_VOLUME":
            if (unit_src.str.contains(r"/(g|kg)$")).any():
                if not hasattr(self, "_warned_bodymass_to_massvol"):
                    try:
                        QMessageBox.information(self, i18n.t("msg_title_units_incompatible_source", self._idioma),
                            "Dose per body mass units (e.g., mg/kg) cannot be converted to mass/volume units "
                            "(e.g., ug/mL) in this workflow. Incompatible rows will be marked as NaN."
                        )
                    except Exception:
                        pass
                    self._warned_bodymass_to_massvol = True

            def converter_para_mass_per_volume(row):
                value_M = _to_M_from_unit(row[self.type_name], row["units_norm"], row["MW"])
                return _from_M_to_mass_per_volume(value_M, target_norm, row["MW"])

            try:
                self.df_selecionado[self.type_name] = self.df_selecionado.apply(converter_para_mass_per_volume, axis=1)
            except Exception as e:
                QMessageBox.critical(self, i18n.t("msg_title_error_during_unit_conversion", self._idioma), str(e))
                return

            self.df_selecionado["units"] = target_norm

        else:
            QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma),
                                f"Unrecognized target unit: '{self.unit_name}' (normalized: '{target_norm}').")
            return

        # Remove auxiliar
        self.df_selecionado.drop(columns=["units_norm"], errors="ignore", inplace=True)

        # ---------------- 5) Persistência + UI ----------------
        target_chembl_id = self.ed_target_chembl_id.text().strip() if hasattr(self, "ed_target_chembl_id") else ""
        target_organism  = self.ed_organism_name.text().strip() if hasattr(self, "ed_organism_name") else ""
        job_dir = getattr(self, "job_dir", os.getcwd())

        out_dir = os.path.join(job_dir, "DATA_BASES", "INTERNAL_DATA")
        os.makedirs(out_dir, exist_ok=True)
        file_path = os.path.join(out_dir, f"df2_unit_{target_chembl_id}_{target_organism}.csv")

        self.df_selecionado.to_csv(file_path, index=False)
        self._next_dataframe_save_path = file_path
        self.show_dataframe(self.df_selecionado)
        self.df_name_view.setText(os.path.basename(file_path))
        self._refresh_step2_dataframe_widgets()
        self._save_step2_state()

    def select_dataframe_stats(self):
        """"Select DataFrame" handler for the STATISTICS tab - independent of the pipeline's
        shared self.df_selecionado (own attribute: self.stats_df), so statistical tests can
        run on any file at any time without depending on where the main pipeline is."""
        try:
            job_dir = getattr(self, "job_dir", None)
            if job_dir:
                initial_dir = os.path.join(job_dir, "DATA_BASES", "INTERNAL_DATA")
            else:
                initial_dir = os.path.join(self.dp_dir, "JOBS")
            os.makedirs(initial_dir, exist_ok=True)

            file_path, _ = QFileDialog.getOpenFileName(
                self,
                "Select DataFrame",
                initial_dir,
                "Data Files (*.csv *.xlsx);;CSV Files (*.csv);;Excel Files (*.xlsx)"
            )
            if not file_path:
                return

            df = self._read_selected_table_file(file_path)
            if df.empty:
                QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), "The selected DataFrame is empty.")
                return

            self.stats_df = df.copy()
            self.df_name_view_stats.setText(os.path.basename(file_path))
            self.show_dataframe(df)
        except Exception as e:
            QMessageBox.critical(self, i18n.t("msg_title_error", self._idioma), f"An error occurred while loading the DataFrame:\n{e}")

        self._refresh_statistics_dataframe_widgets()

    def _refresh_statistics_dataframe_widgets(self):
        """Repopulate every STATISTICS combo/list that depends on self.stats_df.

        Runs the same widget refresh as clicking "Select DataFrame" on the STATISTICS tab -
        must be called any time self.stats_df changes, so its dropdowns never go stale
        relative to the "Select DataFrame" description at the top of the tab.
        """
        if getattr(self, "stats_df", None) is None:
            self.list_columns_stat.clear()
            # "Tamanho da População (N)" não é resetado aqui: é editável mesmo sem
            # dataframe carregado, e um valor digitado manualmente antes de selecionar
            # (ou depois de uma seleção cancelada) não deve ser apagado.
            return
        if hasattr(self, "ed_stats_population_size"):
            self.ed_stats_population_size.setText(str(len(self.stats_df)))
        try:
            self.list_columns_stat.clear()
            self.list_columns_stat.addItems(self.stats_df.columns.astype(str))
            self.list_columns_var.clear()
            self.list_columns_var.addItems(self.stats_df.columns.astype(str))
            self.list_columns_var1.clear()
            self.list_columns_var1.addItems(self.stats_df.columns.astype(str))
            self.list_columns_var2.clear()
            self.list_columns_var2.addItems(self.stats_df.columns.astype(str))
            self.list_columns_var3.clear()
            self.list_columns_var3.addItems(self.stats_df.columns.astype(str))

            # Pré-seleciona a coluna de bioatividade (mesma heurística usada nas demais
            # abas) em "Select column" (Descriptive Statistics) e "Select Variable"
            # (Compare Classes).
            bio_col = self._find_bioactivity_column(self.stats_df.columns)
            if bio_col:
                self._set_combo_text(self.list_columns_stat, bio_col)
                self._set_combo_text(self.list_columns_var, bio_col)

        except Exception as e:
            self.list_columns_stat.clear()
            QMessageBox.critical(self, i18n.t("msg_title_error_list_columns_csv", self._idioma), str(e))

        # Popular list_class_column_stats com todas as colunas do DataFrame
        df = self.stats_df.copy()
        if hasattr(self, "list_class_column_stats"):
            try:
                self.list_class_column_stats.currentIndexChanged.disconnect()
            except Exception:
                pass
            self.list_class_column_stats.clear()
            self.list_class_column_stats.addItems(df.columns.astype(str).tolist())
            # Pré-seleciona "Class" se existir
            idx_class = self.list_class_column_stats.findText("Class")
            if idx_class >= 0:
                self.list_class_column_stats.setCurrentIndex(idx_class)
            # Conecta o slot de atualização dos grupos
            self.list_class_column_stats.currentIndexChanged.connect(self._update_list_groups_from_comp)

        # Preenche list_groups com os grupos da coluna atualmente selecionada
        self._update_list_groups_from_comp()

    def _update_list_groups_from_comp(self):
        """Updates list_groups with unique values from the column selected in list_class_column_stats."""
        df = getattr(self, "stats_df", None)
        if df is None:
            return
        if not hasattr(self, "list_class_column_stats"):
            return
        col = self.list_class_column_stats.currentText().strip()
        if not col or col not in df.columns:
            return
        self.list_groups.clear()
        classes = pd.unique(df[col].astype(str))
        self.list_groups.addItems(list(map(str, classes)))

    # ------------------------------------------------------------------
    # STATISTICS - "Cálculo Amostral e Poder Estatístico": conversões dinâmicas
    # entre Nível de Confiança (%/Z) e entre Poder Estatístico/Erro Tipo II (β).
    # Um guard evita loop de sinais entre os dois campos de cada par.
    # ------------------------------------------------------------------
    def _sync_stats_confidence_from_pct(self):
        if getattr(self, "_stats_power_sync_guard", False):
            return
        self._stats_power_sync_guard = True
        try:
            pct = float(self.ed_stats_confidence_pct.text().strip().replace(",", "."))
            alpha = 1 - pct / 100.0
            z = stats.norm.ppf(1 - alpha / 2)
            self.ed_stats_confidence_z.setText(f"{z:.4f}")
            if hasattr(self, "lbl_stats_alpha_value"):
                self.lbl_stats_alpha_value.setText(f"{alpha:.4f}")
        except (ValueError, AttributeError, ZeroDivisionError):
            pass
        finally:
            self._stats_power_sync_guard = False

    def _sync_stats_confidence_from_z(self):
        if getattr(self, "_stats_power_sync_guard", False):
            return
        self._stats_power_sync_guard = True
        try:
            z = float(self.ed_stats_confidence_z.text().strip().replace(",", "."))
            alpha = 2 * (1 - stats.norm.cdf(z))
            pct = (1 - alpha) * 100
            self.ed_stats_confidence_pct.setText(f"{pct:.2f}")
            if hasattr(self, "lbl_stats_alpha_value"):
                self.lbl_stats_alpha_value.setText(f"{alpha:.4f}")
        except (ValueError, AttributeError):
            pass
        finally:
            self._stats_power_sync_guard = False

    def _sync_stats_power_from_power(self):
        if getattr(self, "_stats_power_sync_guard", False):
            return
        self._stats_power_sync_guard = True
        try:
            power = float(self.ed_stats_power.text().strip().replace(",", "."))
            self.ed_stats_beta.setText(f"{1 - power:.4f}")
        except (ValueError, AttributeError):
            pass
        finally:
            self._stats_power_sync_guard = False

    def _sync_stats_power_from_beta(self):
        if getattr(self, "_stats_power_sync_guard", False):
            return
        self._stats_power_sync_guard = True
        try:
            beta = float(self.ed_stats_beta.text().strip().replace(",", "."))
            self.ed_stats_power.setText(f"{1 - beta:.4f}")
        except (ValueError, AttributeError):
            pass
        finally:
            self._stats_power_sync_guard = False

    def run_sample_size_calc(self):
        """Botão "Calcular Tamanho Amostral" da aba STATISTICS.

        - Se "Proporção do Grupo 2 (p2)" estiver vazia: calcula o tamanho de amostra
          representativo de UMA proporção populacional (fórmula de Cochran), a partir de
          Z (Nível de Confiança), p1, Margem de Erro e, se disponível, Tamanho da
          População (aplica a correção para população finita).
        - Se p2 estiver preenchida: calcula o tamanho de amostra POR GRUPO necessário
          para comparar 2 proporções com o Poder/α informados (Cohen's h via statsmodels).
        """
        try:
            z = float(self.ed_stats_confidence_z.text().strip().replace(",", "."))
            p1 = float(self.ed_stats_p1.text().strip().replace(",", "."))
        except (ValueError, AttributeError):
            QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), "Preencha Nível de Confiança (Z) e Proporção do Grupo 1 (p1) com valores numéricos válidos.")
            return

        if not (0 < p1 < 1):
            QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), "Proporção do Grupo 1 (p1) deve estar entre 0 e 1.")
            return

        p2_text = self.ed_stats_p2.text().strip().replace(",", ".") if hasattr(self, "ed_stats_p2") else ""
        lines = []

        if p2_text:
            try:
                p2 = float(p2_text)
                alpha = float(self.lbl_stats_alpha_value.text().strip().replace(",", "."))
                power = float(self.ed_stats_power.text().strip().replace(",", "."))
            except (ValueError, AttributeError):
                QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), "Valores inválidos em Proporção do Grupo 2 (p2), Poder Estatístico ou Erro Tipo I.")
                return
            if not (0 < p2 < 1):
                QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), "Proporção do Grupo 2 (p2) deve estar entre 0 e 1.")
                return

            try:
                from statsmodels.stats.proportion import proportion_effectsize
                from statsmodels.stats.power import NormalIndPower
                effect = abs(proportion_effectsize(p1, p2))
                if effect == 0:
                    QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), "p1 e p2 são iguais - não há diferença a detectar.")
                    return
                n_per_group = int(np.ceil(NormalIndPower().solve_power(
                    effect_size=effect, alpha=alpha, power=power, ratio=1.0, alternative="two-sided"
                )))
            except Exception as e:
                QMessageBox.critical(self, i18n.t("msg_title_error", self._idioma), f"Erro no cálculo de tamanho amostral (comparação entre 2 grupos): {e}\n(statsmodels instalado?)")
                return

            lines.append("Sample size - Two-proportion comparison")
            lines.append(f"p1 = {p1}, p2 = {p2}")
            lines.append(f"Effect size (Cohen's h) = {effect:.4f}")
            lines.append(f"Alpha (Type I) = {alpha:.4f}, Power = {power:.4f} (Beta/Type II = {1 - power:.4f})")
            lines.append(f"Required sample size per group: {n_per_group}")
            lines.append(f"Required total sample size (2 groups): {n_per_group * 2}")
        else:
            try:
                e = float(self.ed_stats_margin_error.text().strip().replace(",", ".")) / 100.0
            except (ValueError, AttributeError):
                QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), "Preencha a Margem de Erro com um valor numérico válido.")
                return
            if e <= 0:
                QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), "Margem de Erro deve ser maior que zero.")
                return

            n0 = (z ** 2) * p1 * (1 - p1) / (e ** 2)

            N = self._get_stats_population_size()
            n_final = n0 / (1 + (n0 - 1) / N) if N else n0
            n_final = int(np.ceil(n_final))

            lines.append("Sample size - Single proportion (Cochran's formula)")
            lines.append(f"Z = {z}, p = {p1}, margin of error = {e * 100:.2f}%")
            if N:
                lines.append(f"Population size (N) = {N} (finite population correction applied)")
            else:
                lines.append("Population size not available - infinite/unknown population assumed. Fill in 'Population Size (N)' to enable the finite-population correction.")
            lines.append(f"n0 (uncorrected) = {n0:.2f}")
            lines.append(f"Required representative sample size: {n_final}")

        self.show_output(lines, "Sample Size Calculation")
        self._save_statistics_state()

    def _get_stats_population_size(self):
        """Lê "Tamanho da População (N)" da aba STATISTICS. O campo é preenchido
        automaticamente com o nº de linhas ao carregar um dataframe, mas é editável
        livremente (inclusive sem nenhum dataframe carregado). Retorna um int > 0, ou
        None se estiver vazio/inválido/<=0."""
        widget = getattr(self, "ed_stats_population_size", None)
        if widget is None:
            return None
        text = widget.text().strip().replace(",", ".")
        if not text:
            return None
        try:
            n = int(float(text))
        except ValueError:
            return None
        return n if n > 0 else None

    def run_power_calc(self):
        """Botão "Calcular Poder Estatístico" da aba STATISTICS.

        Calcula o poder alcançado ao comparar as proporções dos Grupos 1 e 2 (p1/p2)
        usando "Tamanho da População (N)" / 2 por grupo (assumindo grupos de tamanho
        igual) e o α (Erro Tipo I) informado. N é preenchido automaticamente ao carregar
        um dataframe, mas pode ser editado manualmente - não depende de haver um
        dataframe selecionado no momento do cálculo.
        """
        p2_text = self.ed_stats_p2.text().strip().replace(",", ".") if hasattr(self, "ed_stats_p2") else ""
        if not p2_text:
            QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), "Preencha a Proporção do Grupo 2 (p2) para calcular o poder estatístico de um teste de comparação entre 2 grupos.")
            return

        try:
            p1 = float(self.ed_stats_p1.text().strip().replace(",", "."))
            p2 = float(p2_text)
            alpha = float(self.lbl_stats_alpha_value.text().strip().replace(",", "."))
        except (ValueError, AttributeError):
            QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), "Valores inválidos em Proporção do Grupo 1 (p1), Proporção do Grupo 2 (p2) ou Erro Tipo I.")
            return

        if not (0 < p1 < 1) or not (0 < p2 < 1):
            QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), "Proporção do Grupo 1 (p1) e Proporção do Grupo 2 (p2) devem estar entre 0 e 1.")
            return

        N = self._get_stats_population_size()
        if N is None or N < 4:
            QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), "Preencha 'Tamanho da População (N)' com um valor válido (>= 4) para calcular o poder de um teste de comparação entre 2 grupos.")
            return

        n_per_group = N // 2

        try:
            from statsmodels.stats.proportion import proportion_effectsize
            from statsmodels.stats.power import NormalIndPower
            effect = abs(proportion_effectsize(p1, p2))
            power = NormalIndPower().power(effect_size=effect, nobs1=n_per_group, alpha=alpha, ratio=1.0, alternative="two-sided")
        except Exception as e:
            QMessageBox.critical(self, i18n.t("msg_title_error", self._idioma), f"Erro no cálculo de poder estatístico: {e}\n(statsmodels instalado?)")
            return

        lines = []
        lines.append("Statistical Power - Two-proportion comparison")
        lines.append(f"p1 = {p1}, p2 = {p2}")
        lines.append(f"Effect size (Cohen's h) = {effect:.4f}")
        lines.append(f"Alpha (Type I) = {alpha:.4f}")
        lines.append(f"Assumed sample size per group (N/2, N = Population Size field): {n_per_group}")
        lines.append(f"Achieved statistical power: {power:.4f} ({power * 100:.2f}%)")
        if power < 0.8:
            lines.append("Note: achieved power is below the conventional 0.8 (80%) threshold.")

        self.show_output(lines, "Statistical Power Calculation")
        self._save_statistics_state()

    def run_set_class(self):
        # 1) Pré-checagens
        if getattr(self, "df_selecionado", None) is None:
            QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), "No DataFrame loaded.")
            return

        col = self.list_columns_cat.currentText().strip()  # coluna escolhida no combo
        if not col or col not in self.df_selecionado.columns:
            QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), "Select a valid value column for classification.")
            return

        # 2) Coleta as 3 classes editáveis - cada uma é opcional; se algum campo obrigatório
        # dela estiver vazio, essa classe simplesmente não é aplicada (não gera erro).
        def _parse_num(s):
            s = (s or "").strip().replace(",", ".")
            if not s:
                return None
            try:
                return float(s)
            except ValueError:
                return None

        ops = {
            ">": lambda v, r: v > r,
            "<": lambda v, r: v < r,
            ">=": lambda v, r: v >= r,
            "<=": lambda v, r: v <= r,
        }

        class1_name = self.ed_class1_name.text().strip()
        class1_op = self.cb_class1_op.currentText().strip()
        class1_ref = _parse_num(self.ed_class1_ref.text())
        class1_active = bool(class1_name) and class1_ref is not None and class1_op in ops

        class2_name = self.ed_class2_name.text().strip()
        class2_min = _parse_num(self.ed_class2_min.text())
        class2_max = _parse_num(self.ed_class2_max.text())
        class2_active = bool(class2_name) and class2_min is not None and class2_max is not None

        class3_name = self.ed_class3_name.text().strip()
        class3_op = self.cb_class3_op.currentText().strip()
        class3_ref = _parse_num(self.ed_class3_ref.text())
        class3_active = bool(class3_name) and class3_ref is not None and class3_op in ops

        if not (class1_active or class2_active or class3_active):
            QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma),
                "Configure at least one class (Class 1/3 reference value, or Class 2 range) before running."
            )
            return

        # 3) Cria a coluna 'Class' - instâncias que não se enquadram em nenhuma classe
        # configurada (ou cujo valor é nulo) recebem NaN, não mais um rótulo fixo.
        df = self.df_selecionado.copy()
        serie_num = pd.to_numeric(df[col], errors="coerce")

        def _classify(x):
            if pd.isna(x):
                return np.nan
            if class1_active and ops[class1_op](x, class1_ref):
                return class1_name
            if class2_active and (class2_min <= x <= class2_max):
                return class2_name
            if class3_active and ops[class3_op](x, class3_ref):
                return class3_name
            return np.nan

        df["Class"] = serie_num.apply(_classify)

        # 4) Salva e exibe
        try:
            target_chembl_id = self.ed_target_chembl_id.text().strip()
            target_organism = self.ed_organism_name.text().strip()
            output_dir = os.path.join(self.job_dir, "DATA_BASES", "INTERNAL_DATA")
            os.makedirs(output_dir, exist_ok=True)
            out_path = os.path.join(output_dir, f"df2_Classes_{target_chembl_id}_{target_organism}.csv")
            df.to_csv(out_path, index=False)
        except Exception as e:
            QMessageBox.critical(self, f"Error saving df2_Classes_{target_chembl_id}_{target_organism}.csv", str(e))

        self.df_selecionado = df
        self.show_dataframe(df)
        self.df_name_view.setText(os.path.basename(out_path))
        self._refresh_step2_dataframe_widgets()
        self._save_step2_state()

    def run_view_class(self):
        # 1) Pré-checagens
        if getattr(self, "df_selecionado", None) is None:
            QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), "No DataFrame loaded.")
            return

        # Coluna que contém a classe (ex.: "Class")
        col_class = self.list_class_column.currentText().strip()
        if not col_class or col_class not in self.df_selecionado.columns:
            QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), "Select a valid class column.")
            return

        # Campo com o ID (cb_molecule_chembl_id_cat)
        mol_id = self.cb_molecule_chembl_id_cat.currentText().strip()
        if not mol_id:
            QMessageBox.information(self, i18n.t("msg_title_info", self._idioma), "Informe/Selecione um molecule_chembl_id.")
            return

        df = self.df_selecionado

        # 2) Verifica a existência da coluna-chave com os IDs
        key_col = "molecule_chembl_id"
        if key_col not in df.columns:
            QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), f"Column '{key_col}' not found in the DataFrame.")
            return

        # 3) Busca o ID e obtém a classe
        try:
            mask = df[key_col].astype(str).str.strip() == mol_id
            if not mask.any():
                if hasattr(self, "ed_class") and hasattr(self.ed_class, "setText"):
                    self.ed_class.setText("")
                QMessageBox.information(self, i18n.t("msg_title_info", self._idioma), f"ID '{mol_id}' not found in the DataFrame.")
                return

            value = df.loc[mask, col_class].iloc[0]
            value_str = "" if pd.isna(value) else str(value)

            # 4) Exibe no campo de saída
            if hasattr(self, "ed_class") and hasattr(self.ed_class, "setText"):
                self.ed_class.setText(value_str)
            else:
                # Fallback: mostra em caixa de diálogo se não houver ed_class
                QMessageBox.information(self, "Classe", f"{col_class}: {value_str}")

        except Exception as e:
            QMessageBox.critical(self, i18n.t("msg_title_error", self._idioma), f"Error retrieving class: {e}")

    def run_view_class_frequency(self):
        # Pré-checagens
        if getattr(self, "df_selecionado", None) is None:
            QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), "No DataFrame loaded.")
            return

        if not hasattr(self, "list_class_column"):
            QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), "Class column selector (list_class_column) not found.")
            return

        col_class = self.list_class_column.currentText().strip()
        if not col_class or col_class not in self.df_selecionado.columns:
            QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), "Select a valid class column.")
            return

        import os
        import pandas as pd

        df = self.df_selecionado

        # -------- Frequências para TODAS as classes presentes (sem NaN) --------
        s = df[col_class].dropna().astype(str).str.strip()
        if s.empty:
            QMessageBox.information(self, i18n.t("msg_title_attention", self._idioma), f"Column '{col_class}' has no valid categories.")
            return

        # Ordenação estável: alfabética case-insensitive
        cats_sorted = sorted(s.unique().tolist(), key=str.lower)
        freq_all = s.value_counts()
        freq_ordered = freq_all.reindex(cats_sorted, fill_value=0)

        # -------- Métricas para exibir --------
        total_rows = len(df)
        shown_count = int((freq_ordered > 0).sum())
        total_categorias = df[col_class].dropna().nunique()

        # -------- Paleta EDITÁVEL (até 6 cores; repete se exceder) --------
        base_colors = [
            "#357fb4",  # Azul
            "#bd793d",  # Laranja
            "#59af59",  # Verde
            "#bd5e5e",  # Vermelho
            "#9467bd",  # Roxo
            "#8c564b",  # Marrom
        ]
        bar_colors = [base_colors[i % len(base_colors)] for i in range(len(freq_ordered))]

        # -------- Figura e barras --------
        fig, ax = plt.subplots(figsize=(8, 4))
        bars = ax.bar(freq_ordered.index, freq_ordered.values, color=bar_colors)

        # Estética do eixo
        ax.spines[['top', 'right']].set_visible(False)
        ax.grid(False)

        # Rótulos dos eixos (em inglês, como no seu código)
        ax.set_xlabel("Class", fontsize=10, fontweight="bold")
        ax.set_ylabel("Count", fontsize=10, fontweight="bold")

        # Rótulos de valor acima das barras
        max_val = int(freq_ordered.values.max()) if len(freq_ordered) else 0
        y_offset = 0.05 * max_val if max_val > 0 else 0.1
        for bar, val, color in zip(bars, freq_ordered.values, bar_colors):
            ax.text(
                bar.get_x() + bar.get_width() / 2,
                val + y_offset,
                f"{int(val)}",
                va="bottom",
                ha="center",
                color=color,
                weight="bold"
            )
        ax.set_xticklabels(ax.get_xticklabels(), rotation=0)

        # Título e layout
        fig.suptitle(f"Frequency by {col_class}", fontweight="bold", y=0.98)
        fig.tight_layout(rect=[0, 0, 1, 0.92])

        # -------- Janela de exibição --------
        dialog = QDialog(self)
        dialog.setWindowTitle(f"Frequency chart: {col_class}")
        layout = QVBoxLayout(dialog)
        canvas = FigureCanvas(fig)
        layout.addWidget(canvas)

        # Barra inferior com botões e infos
        btn_layout = QHBoxLayout()

        btn_save = QPushButton("Save chart")
        btn_save.setFixedSize(200, 30)

        btn_close = QPushButton("Close")
        btn_close.setFixedSize(200, 30)
        _style_dialog_buttons(btn_save, btn_close)

        row_count_label = QLabel(f"Rows: {total_rows}")
        row_count_label.setStyleSheet("font-size: 12pt; font-weight: bold; color: #6E8CA8; margin-left: 20px;")
        row_count_label.setFixedSize(200, 30)

        shown_label = QLabel(f"Shown categories: {shown_count} / {total_categorias}")
        shown_label.setStyleSheet("font-size: 10pt; color: #555; margin-left: 10px;")
        shown_label.setFixedSize(220, 30)

        btn_layout.addWidget(btn_save, alignment=Qt.AlignCenter)
        btn_layout.addStretch(1)
        btn_layout.addWidget(btn_close, alignment=Qt.AlignCenter)
        btn_layout.addStretch(1)
        btn_layout.addWidget(row_count_label, alignment=Qt.AlignCenter)
        btn_layout.addWidget(shown_label, alignment=Qt.AlignCenter)
        layout.addLayout(btn_layout)

        # Ações
        def _save_chart():
            default_name = f"freq_{col_class}.png"
            start_dir = os.path.join(getattr(self, "job_dir", os.getcwd()), "RESULTS")
            os.makedirs(start_dir, exist_ok=True)
            path, _ = QFileDialog.getSaveFileName(
                dialog,
                "Save chart",
                os.path.join(start_dir, default_name),
                "PNG (*.png);;SVG (*.svg);;PDF (*.pdf)"
            )
            if path:
                try:
                    fig.savefig(path, dpi=300, bbox_inches="tight")
                    QMessageBox.information(dialog, "Saved", f"Chart saved to:\n{path}")
                except Exception as e:
                    QMessageBox.critical(dialog, "Save error", str(e))

        btn_save.clicked.connect(_save_chart)
        btn_close.clicked.connect(dialog.close)

        dialog.resize(900, 520)
        dialog.exec_()
        
    def run_set_lip(self):
        # Pre-checks
        if not hasattr(self, "df_selecionado") or self.df_selecionado is None or self.df_selecionado.empty:
            QMessageBox.warning(self, i18n.t("msg_title_attention_bang", self._idioma), "No DataFrame selected (df_selecionado is empty).")
            return
        if "canonical_smiles" not in self.df_selecionado.columns:
            QMessageBox.warning(self, i18n.t("msg_title_attention_bang", self._idioma), "Column 'canonical_smiles' was not found in df_selecionado.")
            return

        # Compose output file name
        target_chembl_id = self.ed_target_chembl_id.text().strip() if hasattr(self, "ed_target_chembl_id") else ""
        target_organism  = self.ed_organism_name.text().strip()     if hasattr(self, "ed_organism_name")   else ""

        output_dir = os.path.join(self.job_dir, "DATA_BASES", "INTERNAL_DATA")
        out_path = os.path.join(output_dir, f"df2_Druggability_{target_chembl_id}_{target_organism}.csv")

        # Worker thread
        class LipinskiWorker(QThread):
            result_signal = pyqtSignal(object)  # DataFrame
            error_signal = pyqtSignal(str)

            def __init__(self, df_in):
                super().__init__()
                self.df_in = df_in

            def run(self):
                try:
                    
                    
                    try:
                        from rdkit import Chem
                        from rdkit.Chem import Descriptors, Lipinski
                    except Exception:
                        raise RuntimeError(
                            "RDKit is not available. Please install it (e.g., pip install rdkit)."
                        )

                    df_in = self.df_in.copy()
                    smiles = df_in["canonical_smiles"].astype(str)

                    logp_list, hbd_list, hba_list, tpsa_list, rotb_list, mw_calc_list = [], [], [], [], [], []

                    for s in smiles:
                        mol = Chem.MolFromSmiles(s) if s else None
                        if mol is None:
                            logp_list.append(np.nan)
                            hbd_list.append(np.nan)
                            hba_list.append(np.nan)
                            tpsa_list.append(np.nan)
                            rotb_list.append(np.nan)
                            mw_calc_list.append(np.nan)
                            continue

                        logp_list.append(Descriptors.MolLogP(mol))
                        hbd_list.append(Lipinski.NumHDonors(mol))
                        hba_list.append(Lipinski.NumHAcceptors(mol))
                        tpsa_list.append(Descriptors.TPSA(mol))
                        rotb_list.append(Descriptors.NumRotatableBonds(mol))
                        mw_calc_list.append(Descriptors.MolWt(mol))  # MW if needed

                    df_out = df_in.copy()
                    df_out["LogP"]           = logp_list
                    df_out["NumHDonors"]     = hbd_list
                    df_out["NumHAcceptors"]  = hba_list
                    df_out["TPSA"]           = tpsa_list
                    df_out["RotatableBonds"] = rotb_list

                    # MW handling: reuse/rename/fill/calc
                    
                    existing_mw = None
                    if "MW" in df_out.columns:
                        existing_mw = pd.to_numeric(df_out["MW"], errors="coerce")
                    elif "MolWt" in df_out.columns:
                        existing_mw = pd.to_numeric(df_out["MolWt"], errors="coerce")
                        df_out.drop(columns=["MolWt"], inplace=True)  # normalize to MW

                    mw_calc_series = pd.Series(mw_calc_list, index=df_out.index, name="MW")
                    if existing_mw is not None:
                        mw_series = existing_mw.fillna(mw_calc_series)
                    else:
                        mw_series = mw_calc_series

                    df_out["MW"] = mw_series

                    # RO5 violations: LogP>5, HBD>5, HBA>10, MW>500
                    def _count_ro5(row):
                        
                        
                        vals = (row["LogP"], row["NumHDonors"], row["NumHAcceptors"], row["MW"])
                        if any(pd.isna(v) for v in vals):
                            return np.nan
                        return int((row["LogP"] > 5) + (row["NumHDonors"] > 5) +
                                (row["NumHAcceptors"] > 10) + (row["MW"] > 500))

                    df_out["RO5_Violations"] = df_out.apply(_count_ro5, axis=1)

                    # Reorder to keep parameters grouped
                    param_cols = ["LogP", "NumHDonors", "NumHAcceptors", "TPSA", "RotatableBonds", "MW", "RO5_Violations"]
                    others = [c for c in df_out.columns if c not in param_cols]
                    ordered_cols = others + [c for c in param_cols if c in df_out.columns]
                    df_out = df_out.reindex(columns=ordered_cols)

                    self.result_signal.emit(df_out)

                except Exception as e:
                    self.error_signal.emit(str(e))

        # Progress dialog (animated)
        progress = QProgressDialog("Calculating Lipinski parameters...", None, 0, 100, self)
        progress.setWindowTitle("Please wait")
        progress.setWindowModality(Qt.ApplicationModal)
        progress.setMinimumDuration(0)
        progress.setCancelButton(None)
        progress.setAutoClose(False)
        progress.setAutoReset(False)
        progress.setValue(0)
        progress.show()
        QApplication.processEvents()

        self._progress_value = 0
        def animate_progress():
            self._progress_value = (self._progress_value + 5) % 101
            progress.setValue(self._progress_value)

        timer = QTimer(progress)
        timer.timeout.connect(animate_progress)
        timer.start(100)

        def on_result(df_out):
            timer.stop()
            progress.close()
            # Save CSV
            try:
                df_out.to_csv(out_path, index=False)
            except Exception as e:
                QMessageBox.warning(self, i18n.t("msg_title_warning", self._idioma), f"Could not save the file:\n{out_path}\n\n{e}")

            # Update reference and show
            self.df_selecionado = df_out
            self.show_dataframe(df_out)
            self.df_name_view.setText(os.path.basename(out_path))
            self._refresh_step2_dataframe_widgets()
            self._save_step2_state()

            QMessageBox.information(self, i18n.t("msg_title_done", self._idioma),
                                    f"Lipinski parameters computed.\nFile saved at:\n{out_path}")

        def on_error(msg):
            timer.stop()
            progress.close()
            QMessageBox.critical(self, i18n.t("msg_title_error", self._idioma), msg)

        # Launch worker
        self._lip_worker = LipinskiWorker(self.df_selecionado.copy())
        self._lip_worker.result_signal.connect(on_result)
        self._lip_worker.error_signal.connect(on_error)
        self._lip_worker.start()

    def run_filter_lip(self):
        if self.df_selecionado is None:
            QMessageBox.warning(self, i18n.t("msg_title_warning", self._idioma), "No dataframe loaded to filter.")
            return

        df_filtered = self.df_selecionado.copy()

        try:
            # ====== MW ======
            if self.chk_MW.isChecked() and "MW" in df_filtered.columns:
                min_val = float(self.ed_min_MW.text().strip())
                max_val = float(self.ed_max_MW.text().strip())
                df_filtered = df_filtered[(df_filtered["MW"] >= min_val) & (df_filtered["MW"] <= max_val)]

            # ====== LogP ======
            if self.chk_logP.isChecked() and "LogP" in df_filtered.columns:
                min_val = float(self.ed_min_logP.text().strip())
                max_val = float(self.ed_max_logP.text().strip())
                df_filtered = df_filtered[(df_filtered["LogP"] >= min_val) & (df_filtered["LogP"] <= max_val)]

            # ====== H-Donor ======
            if self.chk_Hdonor.isChecked() and "Hdonor" in df_filtered.columns:
                min_val = float(self.ed_min_Hdonor.text().strip())
                max_val = float(self.ed_max_Hdonor.text().strip())
                df_filtered = df_filtered[(df_filtered["Hdonor"] >= min_val) & (df_filtered["Hdonor"] <= max_val)]

            # ====== H-Aceptor ======
            if self.chk_Haceptor.isChecked() and "Haceptor" in df_filtered.columns:
                min_val = float(self.ed_min_Haceptor.text().strip())
                max_val = float(self.ed_max_Haceptor.text().strip())
                df_filtered = df_filtered[(df_filtered["Haceptor"] >= min_val) & (df_filtered["Haceptor"] <= max_val)]

            # ====== TPSA ======
            if self.chk_TPSA.isChecked() and "TPSA" in df_filtered.columns:
                min_val = float(self.ed_min_TPSA.text().strip())
                max_val = float(self.ed_max_TPSA.text().strip())
                df_filtered = df_filtered[(df_filtered["TPSA"] >= min_val) & (df_filtered["TPSA"] <= max_val)]

            # ====== Rotatable Bonds ======
            if self.chk_RBonds.isChecked() and "RBonds" in df_filtered.columns:
                min_val = float(self.ed_min_RBonds.text().strip())
                max_val = float(self.ed_max_RBonds.text().strip())
                df_filtered = df_filtered[(df_filtered["RBonds"] >= min_val) & (df_filtered["RBonds"] <= max_val)]

            # ====== Nº Violations ======
            if self.chk_Vo5.isChecked() and "RO5_Violations" in df_filtered.columns:
                min_val = float(self.ed_min_Vo5.text().strip())
                max_val = float(self.ed_max_Vo5.text().strip())
                df_filtered = df_filtered[(df_filtered["RO5_Violations"] >= min_val) & (df_filtered["RO5_Violations"] <= max_val)]

        except ValueError:
            QMessageBox.critical(self, i18n.t("msg_title_error", self._idioma), "Invalid numeric value in range fields.")
            return

        if df_filtered.empty:
            QMessageBox.information(self, i18n.t("msg_title_info", self._idioma), "No compounds matched the selected Lipinski filters.")
            return

        # Atualiza e exibe o novo dataframe
        self.df_selecionado = df_filtered
        self.show_dataframe(self.df_selecionado)

        # Compose output file name
        target_chembl_id = self.ed_target_chembl_id.text().strip() if hasattr(self, "ed_target_chembl_id") else ""
        target_organism  = self.ed_organism_name.text().strip() if hasattr(self, "ed_organism_name") else ""
        output_dir = os.path.join(self.job_dir, "DATA_BASES", "INTERNAL_DATA")
        out_path = os.path.join(output_dir, f"df2_Druggability_filter_{target_chembl_id}_{target_organism}.csv")
        df_filtered.to_csv(out_path, index=False)
        self.df_name_view.setText(os.path.basename(out_path))
        self._refresh_step2_dataframe_widgets()
        self._save_step2_state()

    def _on_compare_groups_selection_changed(self):
        """STEP 3 'Compare Classes': the 5 test buttons start disabled/gray and only light up
        (green, clickable) once enough groups are selected in 'Select groups' - Verify
        Assumptions needs >=1 group, t-Student/Mann-Whitney need exactly 2 (they're 2-group
        tests), ANOVA/Kruskal-Wallis need >=3 (k-group tests). Re-selecting resets this; running
        Verify Assumptions then further narrows down to just the parametric or non-parametric
        pick within whichever tier is active (see run_verify_assumptions)."""
        n_selected = len(self.list_groups.selectedItems()) if hasattr(self, "list_groups") else 0
        self._set_test_button_active(getattr(self, "btn_verify_assumptions", None), n_selected >= 1)
        self._set_test_button_active(getattr(self, "btn_t_student", None), n_selected == 2)
        self._set_test_button_active(getattr(self, "btn_mann_whitney", None), n_selected == 2)
        self._set_test_button_active(getattr(self, "btn_anova_one_way", None), n_selected >= 3)
        self._set_test_button_active(getattr(self, "btn_kruskal_wallis", None), n_selected >= 3)

    def run_verify_assumptions(self):
        # ------- checagens básicas -------
        if getattr(self, "stats_df", None) is None or self.stats_df.empty:
            QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), "No DataFrame loaded.")
            return

        value_col = self.list_columns_var.currentText().strip() if hasattr(self, "list_columns_var") else ""
        class_col = self.list_class_column_stats.currentText().strip() if hasattr(self, "list_class_column_stats") else ""

        if not value_col or value_col not in self.stats_df.columns:
            QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), "Select a valid numeric column in 'Select Variables'.")
            return
        if not class_col or class_col not in self.stats_df.columns:
            QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), "Select a valid class column in 'Select class column'.")
            return

        df = self.stats_df.copy()
        df[value_col] = pd.to_numeric(df[value_col], errors="coerce")
        df[class_col] = df[class_col].astype(str)

        # ------- grupos selecionados em list_groups (fallback: todos) -------
        selected_groups = []
        lg = getattr(self, "list_groups", None)
        if lg is not None and hasattr(lg, "selectedItems"):
            selected_groups = [it.text().strip() for it in lg.selectedItems()]
        elif lg is not None and hasattr(lg, "currentText"):
            txt = lg.currentText().strip()
            if txt:
                selected_groups = [txt]
        if not selected_groups:
            selected_groups = [g for g in df[class_col].dropna().unique().tolist()]

        # monta vetores (exige >=3 obs/ grupo para testes estáveis)
        group_vectors, group_names = [], []
        for g in selected_groups:
            v = df.loc[df[class_col] == str(g), value_col].dropna()
            if len(v) >= 3:
                group_vectors.append(v)
                group_names.append(str(g))

        if len(group_vectors) < 2:
            QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), "Need at least two groups with ≥3 valid values each.")
            return

        # ------- flags de execução a partir das checkboxes -------
        run_normality = bool(getattr(self, "chk_normality", None) and self.chk_normality.isChecked())
        run_homog     = bool(getattr(self, "chk_homogeneity", None) and self.chk_homogeneity.isChecked())

        # ------- testes -------
        normal_ok = True
        homogeneity_ok = True
        report = []
        report.append(f"Variable: {value_col}")
        report.append(f"Class column: {class_col}")
        report.append(f"Groups (n≥3): {', '.join(group_names)}")
        report.append("")

        # Normalidade por grupo (Shapiro prioritário; fallback: normaltest)
        if run_normality:
            report.append("Normality (Shapiro–Wilk, α=0.05):")
            normal_flags = []
            for name, vec in zip(group_names, group_vectors):
                try:
                    stat, p = stats.shapiro(vec)
                except Exception:
                    stat, p = stats.normaltest(vec, nan_policy='omit')
                ok = (p >= 0.05)
                normal_flags.append(ok)
                report.append(f"  - {name}: p={p:.3e} -> {'Normal' if ok else 'Non-normal'}")
            normal_ok = all(normal_flags)
            report.append(f"All groups normal? {'YES' if normal_ok else 'NO'}")
            report.append("")

        # Homocedasticidade entre grupos (Levene com mediana)
        if run_homog:
            try:
                lev_stat, lev_p = stats.levene(*group_vectors, center='median')
                homogeneity_ok = (lev_p >= 0.05)
                report.append("Homogeneity of variances (Levene, median, α=0.05):")
                report.append(f"  Levene p={lev_p:.3e} -> {'Homogeneous' if homogeneity_ok else 'Heteroscedastic'}")
                report.append("")
            except Exception as e:
                homogeneity_ok = False
                report.append(f"Levene test failed: {e}")
                report.append("")

        # ------- controlar botões -------
        # Regra: dentro do par válido para o número de grupos testados (t-Student/Mann-Whitney
        # para k==2, ANOVA/Kruskal-Wallis para k>=3), fica habilitado (verde) apenas o teste
        # paramétrico OU o não-paramétrico, conforme os pressupostos - o outro do par, e o par
        # que não se aplica ao k atual, ficam desabilitados (cinza). Verify Assumptions
        # permanece habilitado (acabou de rodar com sucesso).
        tested_any = (run_normality or run_homog)
        assumptions_passed = ((not run_normality or normal_ok) and (not run_homog or homogeneity_ok))
        parametric_ok = tested_any and assumptions_passed

        k = len(group_names)
        anova_btn = getattr(self, "btn_anova_one_way", None)
        ttest_btn = getattr(self, "btn_t_student", None)
        kruskal_btn = getattr(self, "btn_kruskal_wallis", None)
        mwu_btn = getattr(self, "btn_mann_whitney", None)

        self._set_test_button_active(getattr(self, "btn_verify_assumptions", None), True)
        if k == 2:
            self._set_test_button_active(anova_btn, False)
            self._set_test_button_active(kruskal_btn, False)
            self._set_test_button_active(ttest_btn, parametric_ok)
            self._set_test_button_active(mwu_btn, not parametric_ok)
            report.append(
                "Detected 2 groups -> "
                + ("t-Student enabled (assumptions satisfied)." if parametric_ok
                   else "Mann-Whitney enabled (assumption failed or not checked).")
            )
        elif k >= 3:
            self._set_test_button_active(ttest_btn, False)
            self._set_test_button_active(mwu_btn, False)
            self._set_test_button_active(anova_btn, parametric_ok)
            self._set_test_button_active(kruskal_btn, not parametric_ok)
            report.append(
                "Detected >=3 groups -> "
                + ("ANOVA One-Way enabled (assumptions satisfied)." if parametric_ok
                   else "Kruskal-Wallis enabled (assumption failed or not checked).")
            )

        # Saída
        self.show_output(report, f"Assumption checks {value_col}" if value_col else "Assumption checks")

    def _get_selected_groups_data(self, min_n_per_group=3):
        """
        Coleta:
        - coluna numérica (list_columns_var)
        - coluna de classe (list_class_column)
        - grupos selecionados (list_groups) -> fallback: todos
        Retorna (value_col, class_col, group_names, group_vectors) ou None em caso de erro.
        Também define self._group_color_map para uso pelos gráficos.
        """
        import pandas as pd  # garante o import local

        if getattr(self, "stats_df", None) is None or self.stats_df.empty:
            QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), "No DataFrame loaded.")
            return None

        value_col = self.list_columns_var.currentText().strip() if hasattr(self, "list_columns_var") else ""
        class_col = self.list_class_column_stats.currentText().strip() if hasattr(self, "list_class_column_stats") else ""

        if not value_col or value_col not in self.stats_df.columns:
            QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), "Select a valid numeric column in 'Select Variables'.")
            return None
        if not class_col or class_col not in self.stats_df.columns:
            QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), "Select a valid class column in 'Select class column'.")
            return None

        df = self.stats_df.copy()
        df[value_col] = pd.to_numeric(df[value_col], errors="coerce")
        df[class_col] = df[class_col].astype(str)

        # Grupos escolhidos na lista (fallback: todos)
        selected_groups = []
        if hasattr(self, "list_groups") and self.list_groups is not None:
            selected_groups = [it.text().strip() for it in self.list_groups.selectedItems()]
        if not selected_groups:
            selected_groups = df[class_col].dropna().astype(str).unique().tolist()

        # Monta vetores (exige pelo menos min_n_per_group observações por grupo)
        group_names, group_vectors = [], []
        for g in selected_groups:
            vec = df.loc[df[class_col] == str(g), value_col].dropna()
            if len(vec) >= min_n_per_group:
                group_names.append(str(g))
                group_vectors.append(vec)

        if len(group_names) == 0:
            QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), f"No group has ≥{min_n_per_group} valid values.")
            return None

        # ---------- PALETA EDITÁVEL (até 6 classes; repete se exceder) ----------
        base_colors = [
            "#1f77b4",  # Azul
            "#ff7f0e",  # Laranja
            "#2ca02c",  # Verde
            "#d62728",  # Vermelho
            "#9467bd",  # Roxo
            "#8c564b",  # Marrom
        ]
        # ordem estável por nome (case-insensitive) para mapeamento determinístico
        ordered = sorted(group_names, key=str.lower)
        self._group_color_map = {g: base_colors[i % len(base_colors)] for i, g in enumerate(ordered)}
        # -----------------------------------------------------------------------

        return value_col, class_col, group_names, group_vectors

    def _color_for_class(self, name: str):
        """
        Retorna a cor da classe baseada no mapeamento construído em _get_selected_groups_data.
        Fallback determinístico usa a mesma paleta base.
        """
        key = (name or "").strip()
        cmap = getattr(self, "_group_color_map", None)
        if isinstance(cmap, dict) and key in cmap:
            return cmap[key]

        # Fallback: determinístico por hash (caso _group_color_map não exista)
        base_colors = [
            "#1f77b4", "#ff7f0e", "#2ca02c",
            "#d62728", "#9467bd", "#8c564b",
        ]
        if key:
            return base_colors[hash(key) % len(base_colors)]
        return "#000000"

    def _plot_density_per_group(self, value_col, class_col, group_names, group_vectors, title_suffix=""):
        """Cria o KDE overlay de densidades por grupo e abre o diálogo com Save/Close e barra interativa."""
        import matplotlib.pyplot as plt
        import seaborn as sns
        
        import os
        from PyQt5.QtWidgets import QDialog, QVBoxLayout, QHBoxLayout, QPushButton, QMessageBox, QFileDialog

        # Monta figura
        fig, ax = plt.subplots(figsize=(10, 6))
        ax.set_title(f"Density plot: {value_col}" + (f" [{title_suffix}]" if title_suffix else ""))
        ax.set_xlabel(value_col)
        ax.set_ylabel("Density")

        # Faixa comum do eixo x (evita cortes ruins entre curvas)
        try:
            x_min = min(float(np.nanmin(v)) for v in group_vectors if len(v) > 1)
            x_max = max(float(np.nanmax(v)) for v in group_vectors if len(v) > 1)
        except ValueError:
            x_min, x_max = None, None

        for name, vec in zip(group_names, group_vectors):
            vec = pd.Series(vec).dropna()
            if len(vec) < 2:
                continue
            sns.kdeplot(vec, ax=ax, label=f"{name} (n={len(vec)})",
                        color=self._color_for_class(name), fill=True, linewidth=2)

        if x_min is not None and x_max is not None and x_min < x_max:
            ax.set_xlim(x_min, x_max)

        ax.legend(frameon=False)
        ax.grid(False)
        plt.tight_layout()

        # Diálogo com canvas interativo
        dialog = QDialog(self)
        dialog.setWindowTitle(f"Density: {value_col}")
        layout = QVBoxLayout(dialog)
        canvas = FigureCanvas(fig)
        toolbar = NavigationToolbar(canvas, dialog)
        layout.addWidget(toolbar)
        layout.addWidget(canvas)

        # Botões Salvar e Fechar
        btn_save = QPushButton("Save Chart")
        btn_save.setFixedWidth(200)
        btn_close = QPushButton("Close")
        btn_close.setFixedWidth(200)
        _style_dialog_buttons(btn_save, btn_close)

        # Layout dos botões
        layout_btn = QHBoxLayout()
        layout_btn.addWidget(btn_save)
        layout_btn.addWidget(btn_close)
        layout.addLayout(layout_btn)

        def save_figure():
            default_dir = os.path.join(self.job_dir, "RESULTS", "STATISTICS")
            os.makedirs(default_dir, exist_ok=True)
            file_path, _ = QFileDialog.getSaveFileName(
                dialog,
                "Save chart",
                os.path.join(default_dir, f"density_{value_col}.png"),
                "PNG Files (*.png);;SVG Files (*.svg);;All Files (*)"
            )
            if file_path:
                fig.savefig(file_path, dpi=500)
                QMessageBox.information(dialog, "Saved", f"Chart saved to:\n{file_path}")

        # Conecta sinais
        btn_save.clicked.connect(save_figure)
        btn_close.clicked.connect(dialog.close)

        dialog.resize(950, 700)
        dialog.exec_()

    def _show_test_report(self, title, lines):
        """Mostra a interpretação em uma janela de texto (reuso do padrão do app)."""
        self.show_output(lines, title)

    def _get_selected_column_series(self, df, column_name):
        """Return a 1D Series even when the DataFrame has duplicate column names."""
        if df is None or column_name not in df.columns:
            raise KeyError(column_name)

        selected = df.loc[:, column_name]
        if isinstance(selected, pd.DataFrame):
            if selected.shape[1] == 0:
                raise KeyError(column_name)
            selected = selected.iloc[:, 0]

        return selected.copy()

    def _build_selected_columns_dataframe(self, specs):
        """Build a temporary DataFrame with unique aliases from selected UI columns."""
        if getattr(self, "df_selecionado", None) is None:
            raise ValueError("No DataFrame loaded.")

        data = {}
        for alias, (column_name, cast_mode) in specs.items():
            series = self._get_selected_column_series(self.df_selecionado, column_name)
            if cast_mode == "numeric":
                data[alias] = pd.to_numeric(series, errors="coerce")
            elif cast_mode == "string":
                data[alias] = series.astype(str)
            else:
                data[alias] = series

        return pd.DataFrame(data)

    def run_anova_test(self):
        """
        One-Way ANOVA (paramétrico) entre ≥3 grupos.
        H0: as médias populacionais são iguais entre os grupos.
        """
        out = self._get_selected_groups_data(min_n_per_group=3)
        if out is None:
            return
        value_col, class_col, group_names, group_vectors = out

        if len(group_vectors) < 3:
            QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), "ANOVA needs ≥3 groups (each with ≥3 values).")
            return

        # teste global
        try:
            stat, p = stats.f_oneway(*group_vectors)
        except Exception as e:
            QMessageBox.critical(self, "ANOVA error", str(e))
            return

        alpha = 0.05
        lines = []
        lines.append("Test: One-Way ANOVA")
        lines.append(f"Variable: {value_col}")
        lines.append(f"Groups: {', '.join([f'{n}(n={len(v)})' for n, v in zip(group_names, group_vectors)])}")
        lines.append("H0: All group means are equal.")
        lines.append(f"F-statistic = {stat:.4f}")
        lines.append(f"p-value = {p:.4e}")
        if p < alpha:
            lines.append(f"Conclusion: Reject H0 at α={alpha:.2f} (at least one mean differs).")
        else:
            lines.append(f"Conclusion: Fail to reject H0 at α={alpha:.2f} (no evidence of mean differences).")

        # ====================== POST-HOC (se solicitado) =======================
        # Executa post-hoc apenas se ANOVA significativa (boa prática)
        if p < alpha:
            # Vetores empilhados para métodos que precisam de "y" e "groups"
            y = np.concatenate([np.asarray(v) for v in group_vectors])
            grp_labels = np.concatenate([[g] * len(v) for g, v in zip(group_names, group_vectors)])

            # ---- Tukey HSD ----
            if getattr(self, "chk_tukey", None) and self.chk_tukey.isChecked():
                try:
                    from statsmodels.stats.multicomp import pairwise_tukeyhsd
                    tuk = pairwise_tukeyhsd(endog=y, groups=grp_labels, alpha=alpha)
                    lines.append("")
                    lines.append("Post-hoc: Tukey HSD")
                    lines.extend(str(tuk.summary()).splitlines())

                    # Interpretação resumida
                    try:
                        # Extrai pares significativos de tukey.result_table
                        tbl = tuk.summary()
                        # tbl é uma SimpleTable; interpretar linhas como string:
                        sig_pairs = []
                        for row in tbl.data[1:]:
                            g1, g2, meandiff, p_adj, lower, upper, reject = row
                            if str(reject).strip().lower() in ("true", "1"):
                                sig_pairs.append(f"{g1} vs {g2}")
                        if sig_pairs:
                            lines.append(f"Significant pair(s) (Tukey): {', '.join(sig_pairs)}.")
                        else:
                            lines.append("No significant pairs by Tukey at the selected α.")
                    except Exception:
                        pass
                except Exception as e:
                    lines.append("")
                    lines.append(f"Tukey HSD failed: {e} (install statsmodels?).")

            # ---- Bonferroni (pares t de Welch com correção) ----
            if getattr(self, "chk_bonferroni", None) and self.chk_bonferroni.isChecked():
                try:
                    import itertools
                    pairs = list(itertools.combinations(range(len(group_names)), 2))
                    m = len(pairs)
                    lines.append("")
                    lines.append("Post-hoc: Pairwise t-tests (Welch) with Bonferroni correction")
                    sig_pairs = []
                    for i, j in pairs:
                        tstat, p_pair = stats.ttest_ind(group_vectors[i], group_vectors[j],
                                                    equal_var=False, nan_policy='omit')
                        p_adj = min(p_pair * m, 1.0)
                        sig = "significant" if p_adj < alpha else "ns"
                        lines.append(f"{group_names[i]} vs {group_names[j]}: "
                                    f"t={tstat:.3f}, p={p_pair:.2e}, p_adj={p_adj:.2e} -> {sig}")
                        if p_adj < alpha:
                            sig_pairs.append(f"{group_names[i]} vs {group_names[j]}")
                    if sig_pairs:
                        lines.append(f"Significant pair(s) (Bonferroni): {', '.join(sig_pairs)}.")
                    else:
                        lines.append("No significant pairs by Bonferroni at the selected α.")
                except Exception as e:
                    lines.append("")
                    lines.append(f"Pairwise Bonferroni failed: {e}")

        self._show_test_report(f"{value_col} ANOVA Result", lines)
        self._plot_density_per_group(value_col, class_col, group_names, group_vectors, title_suffix="ANOVA")

    def run_kruskal_wallis_test(self):
        """
        Kruskal–Wallis (não-paramétrico) entre ≥3 grupos.
        H0: as distribuições (ou medianas) são iguais entre os grupos.
        """
        out = self._get_selected_groups_data(min_n_per_group=3)
        if out is None:
            return
        value_col, class_col, group_names, group_vectors = out

        if len(group_vectors) < 3:
            QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), "Kruskal–Wallis needs ≥3 groups (each with ≥3 values).")
            return

        # teste global
        try:
            stat, p = stats.kruskal(*group_vectors)
        except Exception as e:
            QMessageBox.critical(self, "Kruskal–Wallis error", str(e))
            return

        alpha = 0.05
        lines = []
        lines.append("Test: Kruskal–Wallis (nonparametric)")
        lines.append(f"Variable: {value_col}")
        lines.append(f"Groups: {', '.join([f'{n}(n={len(v)})' for n, v in zip(group_names, group_vectors)])}")
        lines.append("H0: All group distributions (medians) are equal.")
        lines.append(f"H-statistic = {stat:.4f}")
        lines.append(f"p-value = {p:.4e}")
        if p < alpha:
            lines.append(f"Conclusion: Reject H0 at α={alpha:.2f} (at least one group differs).")
        else:
            lines.append(f"Conclusion: Fail to reject H0 at α={alpha:.2f} (no evidence of differences).")

        # ====================== POST-HOC (se solicitado) =======================
        if p < alpha:
            # Dados empilhados para funções que usam data frame "long"
            y = np.concatenate([np.asarray(v) for v in group_vectors])
            grp_labels = np.concatenate([[g] * len(v) for g, v in zip(group_names, group_vectors)])
            long_df = pd.DataFrame({"y": y, "g": grp_labels})

            # ---- Dunn (via scikit-posthocs) ----
            if getattr(self, "chk_dunn", None) and self.chk_dunn.isChecked():
                try:
                    import scikit_posthocs as sp
                    dunn = sp.posthoc_dunn(long_df, val_col="y", group_col="g", p_adjust="bonferroni")
                    lines.append("")
                    lines.append("Post-hoc: Dunn (Bonferroni-adjusted p-values)")
                    lines.append(dunn.to_string())

                    # Pairs significativos
                    try:
                        sig_pairs = []
                        # varre triângulo superior
                        for i, gi in enumerate(dunn.index):
                            for j, gj in enumerate(dunn.columns):
                                if j <= i:
                                    continue
                                p_ij = dunn.iloc[i, j]
                                if pd.notna(p_ij) and float(p_ij) < alpha:
                                    sig_pairs.append(f"{gi} vs {gj}")
                        if sig_pairs:
                            lines.append(f"Significant pair(s) (Dunn): {', '.join(sig_pairs)}.")
                        else:
                            lines.append("No significant pairs by Dunn at the selected α.")
                    except Exception:
                        pass
                except Exception as e:
                    lines.append("")
                    lines.append(f"Dunn post-hoc failed: {e} (install scikit-posthocs).")

            # # ---- Wilcoxon pairwise (rank-sum / Mann–Whitney U) com Bonferroni ----
            # if getattr(self, "chk_wilcoxon", None) and self.chk_wilcoxon.isChecked():
            #     try:
            #         import itertools
            #         pairs = list(itertools.combinations(range(len(group_names)), 2))
            #         m = len(pairs)
            #         lines.append("")
            #         lines.append("Post-hoc: Wilcoxon rank-sum (pairwise Mann–Whitney U) with Bonferroni correction")
            #         sig_pairs = []
            #         for i, j in pairs:
            #             try:
            #                 res = stats.mannwhitneyu(group_vectors[i], group_vectors[j], alternative="two-sided")
            #                 U, p_pair = res.statistic, res.pvalue
            #             except TypeError:
            #                 U, p_pair = stats.mannwhitneyu(group_vectors[i], group_vectors[j])
            #             p_adj = min(p_pair * m, 1.0)
            #             sig = "significant" if p_adj < alpha else "ns"
            #             lines.append(f"{group_names[i]} vs {group_names[j]}: "
            #                         f"U={U:.3f}, p={p_pair:.2e}, p_adj={p_adj:.2e} -> {sig}")
            #             if p_adj < alpha:
            #                 sig_pairs.append(f"{group_names[i]} vs {group_names[j]}")
            #         if sig_pairs:
            #             lines.append(f"Significant pair(s) (Wilcoxon pairwise): {', '.join(sig_pairs)}.")
            #         else:
            #             lines.append("No significant pairs by Wilcoxon pairwise at the selected α.")
            #     except Exception as e:
            #         lines.append("")
            #         lines.append(f"Wilcoxon pairwise failed: {e}")
            
            # ---- Conover–Iman (recomendável: Holm) ----
            if getattr(self, "chk_conover", None) and self.chk_conover.isChecked():
                try:
                    import scikit_posthocs as sp
                    y = np.concatenate([np.asarray(v) for v in group_vectors])
                    grp_labels = np.concatenate([[g] * len(v) for g, v in zip(group_names, group_vectors)])
                    long_df = pd.DataFrame({"y": y, "g": grp_labels})

                    con = sp.posthoc_conover(long_df, val_col="y", group_col="g", p_adjust="holm")  # ou "bonferroni"
                    lines.append("")
                    lines.append("Post-hoc: Conover–Iman (Holm-adjusted p-values)")
                    lines.append(con.to_string())

                    # Pares significativos
                    sig_pairs = []
                    for i, gi in enumerate(con.index):
                        for j, gj in enumerate(con.columns):
                            if j <= i: 
                                continue
                            p_ij = float(con.iloc[i, j])
                            if p_ij < 0.05:
                                sig_pairs.append(f"{gi} vs {gj}")
                    lines.append("Significant pair(s): " + (", ".join(sig_pairs) if sig_pairs else "none"))
                except Exception as e:
                    lines.append("")
                    lines.append(f"Conover–Iman failed: {e} (install scikit-posthocs).")

        self._show_test_report(f"{value_col} Kruskal–Wallis Result", lines)
        self._plot_density_per_group(value_col, class_col, group_names, group_vectors, title_suffix="Kruskal–Wallis")

    def run_mann_whitney_test(self):
        """
        Mann–Whitney U (não-paramétrico) entre exatamente 2 grupos independentes.
        H0: as distribuições (ou medianas) são iguais entre os 2 grupos.
        """
        out = self._get_selected_groups_data(min_n_per_group=3)
        if out is None:
            return
        value_col, class_col, group_names, group_vectors = out

        if len(group_vectors) != 2:
            QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), "Mann–Whitney requires exactly 2 groups (each with ≥3 values).")
            return

        a, b = group_vectors[0], group_vectors[1]
        try:
            # Usa alternativa bicaudal se disponível (SciPy ≥1.7)
            res = stats.mannwhitneyu(a, b, alternative="two-sided")
            stat, p = res.statistic, res.pvalue
        except TypeError:
            # Fallback para versões antigas
            stat, p = stats.mannwhitneyu(a, b)  # padrão bicaudal em versões novas; antigas eram unilateral
        except Exception as e:
            QMessageBox.critical(self, "Mann–Whitney error", str(e))
            return

        lines = []
        lines.append("Test: Mann–Whitney U (nonparametric, 2 groups)")
        lines.append(f"Variable: {value_col}")
        lines.append(f"Groups: {group_names[0]} (n={len(a)}) vs {group_names[1]} (n={len(b)})")
        lines.append("H0: Both group distributions (medians) are equal.")
        lines.append(f"U-statistic = {stat:.4f}")
        lines.append(f"p-value = {p:.4e}")
        if p < 0.05:
            lines.append("Conclusion: Reject H0 at α=0.05 (groups differ).")
        else:
            lines.append("Conclusion: Fail to reject H0 at α=0.05 (no evidence of difference).")

        self._show_test_report(f"{value_col} Mann–Whitney Result", lines)
        self._plot_density_per_group(value_col, class_col, group_names, group_vectors, title_suffix="Mann–Whitney")

    def run_tstudent_test(self, equal_var: bool = False):
        # 1) Obter dados no MESMO formato do Mann–Whitney (4 itens)
        out = self._get_selected_groups_data(min_n_per_group=2)
        if out is None:
            return
        try:
            value_col, class_col, group_names, group_vectors = out
        except ValueError:
            QMessageBox.critical(self, "t-Student", "Unexpected return from _get_selected_groups_data().")
            return

        # 2) Exigir exatamente 2 grupos (como no Mann–Whitney)
        if len(group_vectors) != 2:
            QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), "Student's t-test requires exactly 2 groups (each with ≥2 values).")
            return

        a, b = group_vectors[0], group_vectors[1]

        # 3) Teste t (Welch por padrão)
        try:
            res = stats.ttest_ind(a, b, equal_var=equal_var, nan_policy="omit")
            tstat, p = res.statistic, res.pvalue
        except Exception as e:
            QMessageBox.critical(self, "t-Student error", str(e))
            return

        # 4) Graus de liberdade (df) de Welch-Satterthwaite (informativo)
        try:
            na, nb = len(a), len(b)
            va, vb = np.var(a, ddof=1), np.var(b, ddof=1)
            num = (va/na + vb/nb) ** 2
            den = (va**2) / (na**2 * (na - 1)) + (vb**2) / (nb**2 * (nb - 1))
            df = num / den if den != 0 else np.nan
        except Exception:
            df = np.nan

        # 5) Tamanho de efeito (Cohen's d, pooled) – informativo
        try:
            sa, sb = np.std(a, ddof=1), np.std(b, ddof=1)
            sp_den = (na + nb - 2)
            sp = np.sqrt(((na - 1) * sa**2 + (nb - 1) * sb**2) / sp_den) if sp_den > 0 else np.nan
            d = (np.mean(a) - np.mean(b)) / sp if (sp not in (0, np.nan)) else np.nan
        except Exception:
            d = np.nan

        # 6) Saída no mesmo estilo do Mann–Whitney
        lines = []
        lines.append("Test: Student's t-test" + (" (Welch)" if not equal_var else " (pooled variances)"))
        lines.append(f"Variable: {value_col}")
        lines.append(f"Groups: {group_names[0]} (n={na}) vs {group_names[1]} (n={nb})")
        lines.append("H0: Both group means are equal.")
        lines.append(f"t({df:.1f}) = {tstat:.4f}")
        lines.append(f"p-value = {p:.4e}")
        lines.append(f"Cohen's d = {d:.3f}")
        if p < 0.05:
            lines.append(f"Conclusion: Reject H0 p-value < 0.05 (means differ).")
        else:
            lines.append(f"Conclusion: Fail to reject H0 p-value > 0.05 (no evidence of difference).")

        # 7) Mesmo fluxo de exibição/plot que você já usa
        self._show_test_report(f"{value_col} t-Student Result", lines)
        self._plot_density_per_group(
            value_col, class_col, group_names, group_vectors,
            title_suffix="t-Student (Welch)" if not equal_var else "t-Student (pooled)"
    )

    def _corr_strength_label(self, abs_stat):
        if abs_stat is None or (isinstance(abs_stat, float) and np.isnan(abs_stat)):
            return "Undefined"
        if abs_stat < 0.1:
            return "Negligible"
        if abs_stat < 0.4:
            return "Weak"
        if abs_stat < 0.7:
            return "Moderate"
        if abs_stat < 0.9:
            return "Strong"
        return "Very Strong"

    def _compute_correlation_stat(self, method, X, Y):
        """Computes the correlation statistic for one of 'pearson'/'spearman'/'kendall'.
        Returns (test_title, stat_label, stat_value, p_value, strength, extra_line_or_None)."""
        if method == "pearson":
            r, pval = stats.pearsonr(X, Y)
            test_title, stat_label, stat_val = "Pearson correlation", "r", r
            extra_prefix = "OLS line"
        elif method == "spearman":
            rho, pval = stats.spearmanr(X, Y, nan_policy="omit")
            test_title, stat_label, stat_val = "Spearman rank correlation", "rho", rho
            extra_prefix = "OLS line (for visualization)"
        elif method == "kendall":
            try:
                tau_b, pval = stats.kendalltau(X, Y, variant='b')
            except TypeError:
                tau_b, pval = stats.kendalltau(X, Y)
            test_title, stat_label, stat_val = "Kendall rank correlation (Tau-b)", "tau-b", tau_b
            extra_prefix = "OLS line (for visualization)"
        else:
            raise ValueError(f"Unknown correlation method: {method}")

        abs_stat = abs(float(stat_val)) if stat_val is not None else float("nan")
        strength = self._corr_strength_label(abs_stat)

        try:
            slope, intercept = np.polyfit(X, Y, deg=1)
            extra = f"{extra_prefix}: Y = {slope:.6g} * X + {intercept:.6g}"
        except Exception:
            extra = None

        return test_title, stat_label, stat_val, pval, strength, extra

    def _build_correlation_report_lines(self, method, x_name, y_name, X, Y):
        test_title, stat_label, stat_val, pval, strength, extra = self._compute_correlation_stat(method, X, Y)
        lines = [
            f"Test: {test_title}",
            f"Variables: {x_name} (X) vs {y_name} (Y)",
            f"N = {len(X)}",
            f"{stat_label} = {stat_val:.4f}",
            f"p-value = {pval:.4e}",
            f"Correlation significance: {strength}",
        ]
        if extra:
            lines.append(extra)
        return lines

    def _get_trend_num_samples(self) -> int:
        """Number of points used to draw each trend curve (linspace resolution), same convention
        as the 'Num Samples' field already used by STEP 2's histogram trend line."""
        try:
            val = int(float(self.ed_trend_num_samples.text().strip())) if hasattr(self, "ed_trend_num_samples") else 1000
        except Exception:
            val = 1000
        return max(10, min(val, 100000))

    def _get_selected_trend_curve_types(self) -> list:
        if not hasattr(self, "list_trend_curve_types"):
            return []
        return [it.text() for it in self.list_trend_curve_types.selectedItems()]

    def _r_squared(self, y_true, y_pred):
        y_true = np.asarray(y_true, dtype=float)
        y_pred = np.asarray(y_pred, dtype=float)
        ss_res = np.sum((y_true - y_pred) ** 2)
        ss_tot = np.sum((y_true - y_true.mean()) ** 2)
        if ss_tot <= 0:
            return float("nan")
        return 1.0 - ss_res / ss_tot

    def _equation_suffix(self, equation: str, r2: float) -> str:
        """Builds the ': y = ... (R²=...)' suffix appended to a trend curve's legend label
        when 'Plot Equation' is checked. Skips R² if it couldn't be computed."""
        if not (getattr(self, "chk_plot_equation", None) and self.chk_plot_equation.isChecked()):
            return ""
        suffix = f": {equation}"
        if r2 is not None and not (isinstance(r2, float) and np.isnan(r2)):
            suffix += f" (R²={r2:.3f})"
        return suffix

    def _draw_correlation_trend_curves(self, ax, X, Y):
        """Draws the curve types selected in the multi-select list (Linear, Moving Average,
        Exponential, Logarithmic, Polynomial, LOESS/LOWESS, Splines, GAMs) while 'Trend Line' is
        checked. Used by the Pearson/Spearman/Kendall correlation plots (2D only)."""
        if not (getattr(self, "chk_linear_trend_line", None) and self.chk_linear_trend_line.isChecked()):
            return

        X = np.asarray(X, dtype=float)
        Y = np.asarray(Y, dtype=float)
        if len(X) < 2 or len(np.unique(X)) < 2:
            return

        selected = set(self._get_selected_trend_curve_types())
        if not selected:
            return

        samples = self._get_trend_num_samples()
        x_line = np.linspace(np.nanmin(X), np.nanmax(X), samples)

        # ---- Linear trend + CI ----
        if "Linear" in selected:
            try:
                coef = np.polyfit(X, Y, deg=1)
                a, b = coef[0], coef[1]
                y_line = a * x_line + b
                r2 = self._r_squared(Y, a * X + b)
                eq = f"y = {a:.4g}x {'+' if b >= 0 else '-'} {abs(b):.4g}"
                label = "Linear trend" + self._equation_suffix(eq, r2)
                ax.plot(x_line, y_line, lw=2.2, ls="-", color="black", alpha=0.9, label=label)

                try:
                    ci_val = float(self.ed_conf_int.text().strip().replace(",", ".")) if hasattr(self, "ed_conf_int") else 95.0
                except Exception:
                    ci_val = 95.0
                ci_val = float(np.clip(ci_val, 50.0, 99.9))
                alpha_ci = 1.0 - (ci_val / 100.0)

                n = X.size
                mean_x = X.mean()
                tcrit = stats.t.ppf(1.0 - alpha_ci / 2.0, df=max(n - 2, 1))
                y_hat_all = a * X + b
                s_err = np.sqrt(np.sum((Y - y_hat_all) ** 2) / max(n - 2, 1))
                Sxx = np.sum((X - mean_x) ** 2)
                se_mean = s_err * np.sqrt((1.0 / n) + ((x_line - mean_x) ** 2) / max(Sxx, np.finfo(float).eps))
                y_upper = y_line + tcrit * se_mean
                y_lower = y_line - tcrit * se_mean

                ax.fill_between(x_line, y_lower, y_upper, color="lightgray", alpha=0.5,
                                label=f"{int(round(ci_val))}% CI (mean)")
            except Exception as e:
                QMessageBox.information(self, "Linear trend", f"Failed to compute linear trend/CI: {e}")

        # Moving Average
        if "Moving Average" in selected:
            try:
                order = np.argsort(X)
                xs = X[order]; ys = Y[order]
                win = max(3, int(round(0.05 * len(xs))))
                s = pd.Series(ys).rolling(window=win, center=True, min_periods=max(2, win // 2)).mean().values
                mask = ~np.isnan(s)
                if mask.sum() >= 2:
                    ax.plot(xs[mask], s[mask], lw=2, ls="--", alpha=0.9, color="#FF5757", label=f"Moving Avg (win={win})")
            except Exception as e:
                QMessageBox.information(self, "Moving Average", f"Failed to compute moving average: {e}")

        # Exponential: y = a * exp(b*(x - x_mean)) + c
        # X is centered on its mean before fitting: a*exp(b*x)+c on raw X (e.g. molecular weight
        # ~150-500) is numerically ill-conditioned — b*x barely varies across the data range, so
        # least-squares finds a near-degenerate near-linear solution using huge/tiny compensating
        # a/b/c (e.g. a=1258, b=-1.9e-06) that fits fine but reads as nonsense. Centering keeps
        # b*(x-x_mean) in a well-scaled range and a bound on b keeps exp() from blowing up.
        if "Exponential" in selected:
            try:
                from scipy.optimize import curve_fit
                x_mean = X.mean()
                Xc = X - x_mean
                span = (Xc.max() - Xc.min()) or 1.0
                def _exp_f(x, a, b, c):
                    return a * np.exp(b * x) + c
                p0 = [(Y.max() - Y.min()) or 1.0, 0.0, Y.mean()]
                b_bound = 10.0 / span
                popt, _ = curve_fit(
                    _exp_f, Xc, Y, p0=p0, maxfev=20000,
                    bounds=([-np.inf, -b_bound, -np.inf], [np.inf, b_bound, np.inf]),
                )
                y_exp = _exp_f(x_line - x_mean, *popt)
                r2 = self._r_squared(Y, _exp_f(Xc, *popt))
                eq = f"y = {popt[0]:.4g}*e^({popt[1]:.4g}*(x-{x_mean:.4g})) {'+' if popt[2] >= 0 else '-'} {abs(popt[2]):.4g}"
                label = "Exponential" + self._equation_suffix(eq, r2)
                ax.plot(x_line, y_exp, lw=2, ls="-.", alpha=0.9, color="#e8590c", label=label)
            except Exception as e:
                QMessageBox.information(self, "Exponential", f"Failed to fit exponential curve: {e}")

        # Logarithmic: y = a + b*ln(x) (requires X > 0)
        if "Logarithmic" in selected:
            try:
                mask = X > 0
                if mask.sum() < 2:
                    raise ValueError("Logarithmic fit requires X > 0.")
                b, a = np.polyfit(np.log(X[mask]), Y[mask], deg=1)
                x_line_pos = x_line[x_line > 0]
                if len(x_line_pos) < 2:
                    raise ValueError("No positive X range to draw the logarithmic curve.")
                y_log = a + b * np.log(x_line_pos)
                r2 = self._r_squared(Y[mask], a + b * np.log(X[mask]))
                eq = f"y = {a:.4g} {'+' if b >= 0 else '-'} {abs(b):.4g}*ln(x)"
                label = "Logarithmic" + self._equation_suffix(eq, r2)
                ax.plot(x_line_pos, y_log, lw=2, ls="-.", alpha=0.9, color="#087f5b", label=label)
            except Exception as e:
                QMessageBox.information(self, "Logarithmic", f"Failed to fit logarithmic curve: {e}")

        # Polynomial (degree 2)
        if "Polynomial" in selected:
            try:
                deg = 2
                pcoef = np.polyfit(X, Y, deg=deg)
                y_poly = np.polyval(pcoef, x_line)
                r2 = self._r_squared(Y, np.polyval(pcoef, X))
                eq = "y = " + " ".join(
                    f"{'+' if c >= 0 else '-'} {abs(c):.4g}{'x' + (f'^{deg - i}' if (deg - i) > 1 else '') if (deg - i) > 0 else ''}"
                    for i, c in enumerate(pcoef)
                ).lstrip("+ ")
                label = f"Polynomial (deg={deg})" + self._equation_suffix(eq, r2)
                ax.plot(x_line, y_poly, lw=2, ls=":", alpha=0.9, color="#2b8a3e", label=label)
            except Exception as e:
                QMessageBox.information(self, "Polynomial", f"Failed to fit polynomial: {e}")

        # LOESS/LOWESS
        if "LOESS/LOWESS" in selected:
            try:
                from statsmodels.nonparametric.smoothers_lowess import lowess
                order = np.argsort(X)
                xs = X[order]; ys = Y[order]
                lo = lowess(ys, xs, frac=0.3, return_sorted=True)
                ax.plot(lo[:, 0], lo[:, 1], lw=2, ls="-.", alpha=0.9, color="#1c7ed6", label="LOESS (frac=0.30)")
            except Exception as e:
                QMessageBox.information(self, "LOESS", f"Failed to compute LOESS: {e}")

        # Splines
        if "Splines" in selected:
            try:
                from scipy.interpolate import UnivariateSpline
                # Tied X values make UnivariateSpline place a knot at every duplicate, which can
                # silently degenerate to an all-NaN fit. Collapse duplicates by averaging Y per
                # unique X before fitting to keep the spline well-posed.
                xu, inv = np.unique(X, return_inverse=True)
                yu = np.array([Y[inv == i].mean() for i in range(len(xu))])
                if len(xu) < 4:
                    raise ValueError("Not enough unique X values for a cubic spline (need >= 4).")
                spl = UnivariateSpline(xu, yu, s=None, k=3)
                y_spline = spl(x_line)
                if not np.all(np.isfinite(y_spline)):
                    raise ValueError("Spline fit produced non-finite values.")
                ax.plot(x_line, y_spline, lw=2, alpha=0.9, color="#ae3ec9", label="Cubic spline")
            except Exception as e:
                try:
                    xu, idx = np.unique(X, return_index=True)
                    yu = Y[idx]
                    yu_sorted = yu[np.argsort(xu)]
                    xu_sorted = np.sort(xu)
                    y_lin = np.interp(x_line, xu_sorted, yu_sorted)
                    ax.plot(x_line, y_lin, lw=2, alpha=0.9, color="#ae3ec9", ls="--", label="Spline (fallback interp.)")
                except Exception as e2:
                    QMessageBox.information(self, "Splines", f"Spline failed: {e}\nFallback failed: {e2}")

        # GAMs
        if "GAMs" in selected:
            try:
                from pygam import LinearGAM, s as pg_s
                gam = LinearGAM(pg_s(0, n_splines=20)).fit(X.reshape(-1, 1), Y)
                y_gam = gam.predict(x_line.reshape(-1, 1))
                ax.plot(x_line, y_gam, lw=2, alpha=0.95, color="#d9480f", label="GAM (spline term)")
            except Exception as e:
                try:
                    import statsmodels.api as sm
                    from patsy import dmatrix
                    x_spline = dmatrix("bs(x, df=6, degree=3, include_intercept=False)",
                                    {"x": X}, return_type='dataframe')
                    gam_sm = sm.GLM(Y, x_spline, family=sm.families.Gaussian()).fit()
                    xline_spline = dmatrix("bs(x, df=6, degree=3, include_intercept=False)",
                                        {"x": x_line}, return_type='dataframe')
                    y_gam = gam_sm.predict(xline_spline)
                    ax.plot(x_line, y_gam, lw=2, alpha=0.95, color="#d9480f", ls="--", label="GAM (statsmodels)")
                except Exception as e2:
                    QMessageBox.information(self, "GAMs", f"GAM unavailable: {e}\nAlternative failed: {e2}")

    def _run_correlation_test(self, method: str, title_prefix: str, file_prefix: str):
        """
        Shared implementation for Pearson/Spearman/Kendall (STEP 3, 'Correlate Variables').

        2D (default, chk_3D_plot unchecked): single X vs Y pair — scatter colored by class plus
        the optional trend curve(s) (see _draw_correlation_trend_curves).

        3D (chk_3D_plot checked + a valid Select Variable 3): runs the same test for all 3 pairwise
        combinations among X, Y, Z, shows all 3 results in a single report window (savable via
        Save .txt), and renders one 3D scatter colored by class (no curve overlays in 3D).
        """
        if getattr(self, "stats_df", None) is None or self.stats_df.empty:
            QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), "No DataFrame loaded.")
            return

        x_col = self.list_columns_var1.currentText().strip() if hasattr(self, "list_columns_var1") else ""
        y_col = self.list_columns_var2.currentText().strip() if hasattr(self, "list_columns_var2") else ""
        class_col = self.list_class_column_stats.currentText().strip() if hasattr(self, "list_class_column_stats") else ""
        is_3d = bool(getattr(self, "chk_3D_plot", None) and self.chk_3D_plot.isChecked())
        z_col = self.list_columns_var3.currentText().strip() if (is_3d and hasattr(self, "list_columns_var3")) else ""

        if not x_col or x_col not in self.stats_df.columns:
            QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), "Select a valid X variable in 'Select Variables 1'.")
            return
        if not y_col or y_col not in self.stats_df.columns:
            QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), "Select a valid Y variable in 'Select Variables 2'.")
            return
        if not class_col or class_col not in self.stats_df.columns:
            QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), "Select a valid class column in 'Select class column'.")
            return
        if is_3d and (not z_col or z_col not in self.stats_df.columns):
            QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), "For 3D plot, select a valid Z variable in 'Select Variables 3'.")
            return

        numeric_cols = [x_col, y_col] + ([z_col] if is_3d else [])
        df = self.stats_df[numeric_cols + [class_col]].copy()
        for c in numeric_cols:
            df[c] = pd.to_numeric(df[c], errors="coerce")
        df[class_col] = df[class_col].astype(str)
        df = df.dropna(subset=numeric_cols)

        if hasattr(self, "list_groups") and self.list_groups is not None:
            sel = [it.text().strip() for it in self.list_groups.selectedItems()]
            if sel:
                df = df[df[class_col].isin(sel)]

        if len(df) < 3:
            QMessageBox.information(self, i18n.t("msg_title_attention", self._idioma), "Need at least 3 valid paired observations.")
            return

        pairs = [(x_col, y_col), (x_col, z_col), (y_col, z_col)] if is_3d else [(x_col, y_col)]

        all_lines = []
        for i, (a_col, b_col) in enumerate(pairs):
            Xp = df[a_col].to_numpy(dtype=float)
            Yp = df[b_col].to_numpy(dtype=float)
            try:
                pair_lines = self._build_correlation_report_lines(method, a_col, b_col, Xp, Yp)
            except Exception as e:
                QMessageBox.critical(self, f"{title_prefix} error", str(e))
                return
            if i > 0:
                all_lines.append("")
            all_lines.extend(pair_lines)

        title_suffix = f"{x_col} vs {y_col} vs {z_col}" if is_3d else f"{x_col} vs {y_col}"
        self._show_test_report(f"{title_prefix} Correlation Result {title_suffix}", all_lines)

        # -------- Plot: scatter by class (+ trend curves in 2D; 3D scatter otherwise)
        from matplotlib.backends.backend_qt5agg import FigureCanvasQTAgg as FigureCanvas

        def _ord(g):
            gl = g.lower()
            if "active" in gl or "ativo" in gl: return 0
            if "intermediate" in gl or "intermedi" in gl: return 1
            if "inactive" in gl or "inativo" in gl: return 2
            return 3

        palette = {g: self._color_for_class(g) for g in sorted(df[class_col].unique(), key=_ord)}

        if is_3d:
            from mpl_toolkits.mplot3d import Axes3D  # noqa: F401
            fig = plt.figure(figsize=(10, 7))
            ax = fig.add_subplot(111, projection='3d')
            ax.set_title(f"{title_prefix} (3D): {x_col} vs {y_col} vs {z_col}")
            ax.set_xlabel(x_col); ax.set_ylabel(y_col); ax.set_zlabel(z_col)
            for g, sub in df.groupby(class_col):
                ax.scatter(sub[x_col], sub[y_col], sub[z_col], s=30, alpha=0.75,
                          color=palette.get(g, "#499b35"), depthshade=True, label=f"{g} (n={len(sub)})")
            ax.legend(frameon=False)
        else:
            fig, ax = plt.subplots(figsize=(10, 7))
            ax.set_title(f"{title_prefix} correlation: {x_col} vs {y_col}")
            ax.set_xlabel(x_col); ax.set_ylabel(y_col); ax.grid(False)
            try:
                sns.scatterplot(data=df, x=x_col, y=y_col, hue=class_col,
                                palette=palette, s=36, alpha=0.7, edgecolor="none", ax=ax)
            except Exception:
                for g, sub in df.groupby(class_col):
                    ax.scatter(sub[x_col], sub[y_col], s=36, alpha=0.7,
                              color=palette.get(g, "#499b35"), edgecolor="none", label=str(g))
            self._draw_correlation_trend_curves(ax, df[x_col].to_numpy(dtype=float), df[y_col].to_numpy(dtype=float))
            ax.legend(frameon=False)

        fig.tight_layout()

        # -------- Dialog with Save / Close
        dialog = QDialog(self)
        dialog.setWindowTitle(f"{title_prefix} (3D): {title_suffix}" if is_3d else f"Scatter ({title_prefix}): {x_col} vs {y_col}")
        layout = QVBoxLayout(dialog)
        canvas = FigureCanvas(fig)
        layout.addWidget(canvas)

        btn_save = QPushButton("Save Chart"); btn_save.setFixedWidth(200)
        btn_close = QPushButton("Close"); btn_close.setFixedWidth(200)
        _style_dialog_buttons(btn_save, btn_close)

        hl = QHBoxLayout()
        hl.addWidget(btn_save)
        hl.addWidget(btn_close)
        layout.addLayout(hl)

        def save_figure():
            default_dir = os.path.join(self.job_dir, "RESULTS", "STATISTICS")
            os.makedirs(default_dir, exist_ok=True)
            base = f"{file_prefix}_{x_col}_vs_{y_col}" + (f"_vs_{z_col}" if is_3d else "")
            file_path, _ = QFileDialog.getSaveFileName(
                dialog, "Save chart",
                os.path.join(default_dir, f"{base}.png"),
                "PNG Files (*.png);;SVG Files (*.svg);;PDF Files (*.pdf);;All Files (*)"
            )
            if file_path:
                fig.savefig(file_path, dpi=500)
                QMessageBox.information(dialog, "Saved", f"Chart saved to:\n{file_path}")

        btn_save.clicked.connect(save_figure)
        btn_close.clicked.connect(dialog.close)
        dialog.resize(950, 720)
        dialog.exec_()

