    def _detect_feature_column_range(self, df=None):
        """Heuristic for identifying the descriptors column range in a dataframe: ignore Name,
        SMILES, Class and bioactivity-metric columns (IC50, pIC50, MIC, pMIC...), then prefer the
        span of columns whose name contains "FP" - fingerprint descriptors are the most commonly
        used kind here. Falls back to the span of every other remaining column when there are no
        "FP" columns. Returns (first_idx, last_idx), or None if it can't be determined (e.g. no
        dataframe yet).

        Originally built for STEP 4's "Feature Columns Range" (applied to self.df_selecionado,
        the default when 'df' is omitted); also reused for STEP 6's "Select X range" (Model
        Screening, over the Internal DataFrame) and "Descriptors Columns Range" (Remove Model and
        Predict, over the External DataFrame) by passing the relevant dataframe explicitly."""
        if df is None:
            df = getattr(self, "df_selecionado", None)
        if df is None or df.empty:
            return None
        cols = list(df.columns.astype(str))

        excluded = {"Name", "name", "SMILES", "smiles", "canonical_smiles", "Class", "class"}
        for attr in ("cb_select_name_column", "cb_select_structure", "cb_class_column", "cb_bioactivity_column"):
            widget = getattr(self, attr, None)
            if widget is not None:
                text = widget.currentText().strip()
                if text:
                    excluded.add(text)

        # Também ignora qualquer coluna cujo nome bata com o vocabulário de bioatividade
        # (IC50, pIC50, MIC, pMIC...), mesmo que nenhum combobox tenha reconhecido/
        # pré-selecionado uma coluna de bioatividade para este dataframe.
        bio_terms_upper = {t.upper() for t in self._bioactivity_candidate_terms()}
        excluded.update(c for c in cols if c.strip().upper() in bio_terms_upper)

        fp_indices = [i for i, c in enumerate(cols) if c not in excluded and "fp" in c.lower()]
        if fp_indices:
            return min(fp_indices), max(fp_indices)

        remaining_indices = [i for i, c in enumerate(cols) if c not in excluded]
        if remaining_indices:
            return min(remaining_indices), max(remaining_indices)
        return None

    def _apply_detected_feature_range(self, df, first_widget_attr, last_widget_attr):
        """Runs _detect_feature_column_range(df) and, if a range is found, fills the given pair of
        First/Last Column Index QLineEdit widgets (identified by attribute name) with it. No-op if
        either widget doesn't exist yet or no range could be detected."""
        first_widget = getattr(self, first_widget_attr, None)
        last_widget = getattr(self, last_widget_attr, None)
        if first_widget is None or last_widget is None:
            return
        detected = self._detect_feature_column_range(df)
        if detected is None:
            return
        first_idx, last_idx = detected
        first_widget.setText(str(first_idx))
        last_widget.setText(str(last_idx))

    def _refresh_step4_dataframe_widgets(self):
        """Repopulate every STEP4 combo/list that depends on self.df_selecionado.

        Runs the same widget refresh as clicking "Select DataFrame" - must be called
        any time self.df_selecionado changes (e.g. a processing button generates a new
        dataframe), so STEP4's dropdowns never go stale relative to the "Select
        DataFrame" description at the top of the tab.
        """
        try:
            self.cb_select_structure.clear()
            self.cb_select_structure.addItems(self.df_selecionado.columns.astype(str))
            self.cb_select_bioactivity.clear()
            self.cb_select_bioactivity.addItems([""] + list(self.df_selecionado.columns.astype(str)))
            self.cb_bioactivity_column.clear()
            self.cb_bioactivity_column.addItems(self.df_selecionado.columns.astype(str))
            self.cb_select_name_column.clear()
            self.cb_select_name_column.addItems(self.df_selecionado.columns.astype(str))
            self.cb_class_column.clear()
            self.cb_class_column.addItems(self.df_selecionado.columns.astype(str))

            cb_tb_label_col = getattr(self, "cb_tb_label_col", None)
            if cb_tb_label_col is not None:
                cb_tb_label_col.clear()
                cb_tb_label_col.addItems(self.df_selecionado.columns.astype(str))

            cb_tb_weight_col = getattr(self, "cb_tb_weight_col", None)
            if cb_tb_weight_col is not None:
                cb_tb_weight_col.clear()

            cb_tb_col_for_weight = getattr(self, "cb_tb_col_for_weight", None)
            if cb_tb_col_for_weight is not None:
                cb_tb_col_for_weight.clear()

            # Cria lista de colunas como strings e insere uma opção vazia no início
            columns = [""] + list(self.df_selecionado.columns.astype(str))

            # Adiciona as opções aos combos
            if cb_tb_weight_col is not None:
                cb_tb_weight_col.addItems(columns)
            if cb_tb_col_for_weight is not None:
                cb_tb_col_for_weight.addItems(columns)

            # Define a opção vazia como selecionada (índice 0)
            if cb_tb_weight_col is not None:
                cb_tb_weight_col.setCurrentIndex(0)
            if cb_tb_col_for_weight is not None:
                cb_tb_col_for_weight.setCurrentIndex(0)

            # Ajusta o valor da penúltima coluna para last e os valores máximos que podem receber:
            ncols = len(self.df_selecionado.columns)

            # Define o valor inicial como texto
            self.ed_feature_last_column.setText(str(ncols - 3))

            # Ajusta os limites do validador
            self.ed_feature_last_column.setValidator(QIntValidator(0, ncols - 1))
            self.ed_feature_first_column.setValidator(QIntValidator(0, ncols))

            ed_tb_feat_from = getattr(self, "ed_tb_feat_from", None)
            if ed_tb_feat_from is not None:
                ed_tb_feat_from.setValidator(QIntValidator(0, ncols - 1))

            ed_tb_feat_to = getattr(self, "ed_tb_feat_to", None)
            if ed_tb_feat_to is not None:
                ed_tb_feat_to.setValidator(QIntValidator(0, ncols))
                ed_tb_feat_to.setText(str(ncols - 3))

            # Pré-preenche "Number of Components" (tabela "Parameters:") via método do
            # cotovelo, só se o usuário ainda não tiver digitado nada ali - uma vez
            # editado manualmente, o valor "gruda" e não é mais sobrescrito por este
            # refresh (Run Projection continua atualizando-o com o valor efetivamente
            # usado, incondicionalmente, ao final da execução).
            if hasattr(self, "tbl_proj_params") and not self._proj_table_value(self.PROJ_ROW_N_COMPONENTS):
                elbow_k = self._compute_pca_elbow_components()
                if elbow_k:
                    self._proj_table_set_value(self.PROJ_ROW_N_COMPONENTS, str(elbow_k))

            # Deixa "Class" já selecionada, se existir:
            idx = self.cb_class_column.findText("Class") if hasattr(self, "cb_class_column") else -1
            if idx >= 0:
                self.cb_class_column.setCurrentIndex(idx)
            # Tenta definir automaticamente a coluna de estrutura
            if hasattr(self, "cb_select_structure"):
                preferred_cols = ["canonical_smiles", "smiles", "smile", "structure", "structures"]
                idx = -1
                for col in preferred_cols:
                    idx = self.cb_select_structure.findText(col, Qt.MatchFixedString | Qt.MatchCaseSensitive)
                    if idx < 0:  # tenta também sem diferenciar maiúsculas/minúsculas
                        idx = self.cb_select_structure.findText(col, Qt.MatchFixedString)
                    if idx >= 0:
                        break
                if idx >= 0:
                    self.cb_select_structure.setCurrentIndex(idx)
            # Deixa "canonical_smiles" já selecionada, se existir:
            if hasattr(self, "cb_select_name_column"):
                preferred_cols = ["Name", "Names", "Compound", "Compounds", "Drugs", "zinc_id", "molecule_chembl_id", "chembl_id", "Molecule_ChEMBL_ID"]
                idx = -1
                for col in preferred_cols:
                    idx = self.cb_select_name_column.findText(col, Qt.MatchFixedString | Qt.MatchCaseSensitive)
                    if idx < 0:  # tenta também sem diferenciar maiúsculas/minúsculas
                        idx = self.cb_select_name_column.findText(col, Qt.MatchFixedString)
                    if idx >= 0:
                        break
                if idx >= 0:
                    self.cb_select_name_column.setCurrentIndex(idx)           
            # Deixa "Bioactivity" já selecionada, se existir:
            terms_bioactivity = self._bioactivity_candidate_terms()
            if hasattr(self, "cb_select_bioactivity"):
                for term in terms_bioactivity:
                    i = self.cb_select_bioactivity.findText(term, Qt.MatchFixedString | Qt.MatchCaseSensitive)
                    if i != -1:
                        # Define o termo encontrado
                        text_found = self.cb_select_bioactivity.itemText(i)

                        # Atualiza todas as comboboxes com o mesmo texto (mesmo que o índice difira)
                        self.cb_select_bioactivity.setCurrentText(text_found)
                        self.cb_bioactivity_column.setCurrentText(text_found)
                        if cb_tb_label_col is not None:
                            cb_tb_label_col.setCurrentText(text_found)
                        break

            # Ajusta "Feature Columns Range" com base nas colunas de Name/SMILES/Class/
            # bioatividade já identificadas acima: ignora essas e, como descritores de
            # fingerprint são os mais usados, prefere o intervalo de colunas cujo nome
            # contém "FP"; sem colunas "FP", usa o intervalo de tudo que sobrar. Mantém o
            # fallback anterior (ncols-3) se a heurística não conseguir determinar nada.
            detected_range = self._detect_feature_column_range()
            if detected_range is not None:
                first_idx, last_idx = detected_range
                self.ed_feature_first_column.setText(str(first_idx))
                self.ed_feature_last_column.setText(str(last_idx))
                if ed_tb_feat_from is not None:
                    ed_tb_feat_from.setText(str(first_idx))
                if ed_tb_feat_to is not None:
                    ed_tb_feat_to.setText(str(last_idx))

        except Exception as e:
            self.cb_select_structure.clear()
            self.cb_select_bioactivity.clear()
            self.cb_bioactivity_column.clear()
            self.cb_select_name_column.clear()
            self.cb_class_column.clear()

            cb_tb_label_col = getattr(self, "cb_tb_label_col", None)
            if cb_tb_label_col is not None:
                cb_tb_label_col.clear()
            QMessageBox.critical(self, i18n.t("msg_title_error_list_columns_csv", self._idioma), str(e))
        
        col = self.cb_class_column.currentText().strip()
        if col and col in self.df_selecionado.columns:
            classes = pd.unique(self.df_selecionado[col].astype(str))
        elif "Class" in self.df_selecionado.columns:
            classes = pd.unique(self.df_selecionado["Class"].astype(str))
        else:
            QMessageBox.information(
                self,
                "Select class column",
                "Please choose a class column above in 'Select class column'."
            )
            return

    def _init_descriptor_checkbox_logic(self):
        """
        Descobre o caminho de descriptors.xml no Python em execução (base, venv),
        lê os grupos <Group name="2D">, <Group name="3D">, <Group name="Fingerprint">,
        e conecta os checkboxes para preencher/retirar as opções em self.list_descriptors.
        """
        from PyQt5.QtWidgets import QMessageBox, QAbstractItemView

        # 1) Localiza descriptors.xml no ambiente Python atual
        xml_path = self._find_descriptors_xml()

        # 2) Extrai listas (ou listas vazias se não encontrado)
        if xml_path:
            try:
                one_two_d, three_d, fps = self._parse_descriptors_xml(xml_path)
            except Exception as e:
                QMessageBox.warning(
                    self, "PaDEL descriptors.xml",
                    f"Failed to parse descriptors.xml at:\n{xml_path}\n\nError: {e}\nUsing empty lists."
                )
                one_two_d, three_d, fps = [], [], []
        else:
            from PyQt5.QtWidgets import QMessageBox
            QMessageBox.warning(
                self, "PaDEL descriptors.xml",
                "Could not find 'padelpy/PaDEL-Descriptor/descriptors.xml' in the current Python environment.\n\n"
                "Tip: install padelpy in the same environment running CODRUG."
            )
            one_two_d, three_d, fps = [], [], []

        # 3) Catálogo no formato usado pelos handlers
        self._padel_catalog = {"1D2D": one_two_d, "3D": three_d, "FP": fps}

        # após construir `fps` a partir do descriptors.xml (PaDEL)
        rdkit_fp_items = [
            "ECFP4 (RDkit classic)",
            "FCFP6 (RDkit)",
            "ECFP4 counting (without 1D2D)",
        ]

        # guarda para referência (opcional)
        self._rdkit_fp_items = rdkit_fp_items

        # mescla com os FPs do PaDEL para exibir juntos
        self._padel_catalog["FP"] = list(dict.fromkeys(list(self._padel_catalog.get("FP", [])) + rdkit_fp_items))


        # 4) Controle do que está visível por tipo (para remoção ao desmarcar)
        self._shown_by_type = {"1D2D": set(), "3D": set(), "FP": set()}

        # 5) Conexões dos checkboxes
        self.chk_1D_2D.stateChanged.connect(lambda _: self._on_descriptor_checkbox_toggled("1D2D"))
        self.chk_3D.stateChanged.connect(lambda _: self._on_descriptor_checkbox_toggled("3D"))
        self.chk_Fingerprint.stateChanged.connect(lambda _: self._on_descriptor_checkbox_toggled("FP"))

        # 6) Seleção múltipla na lista
        try:
            self.list_descriptors.setSelectionMode(QAbstractItemView.MultiSelection)
        except Exception:
            pass

    def _find_descriptors_xml(self):
        """
        Procura por padelpy/PaDEL-Descriptor/descriptors.xml no ambiente do Python atual.
        Estratégia:
        (a) import padelpy → <pkg>/PaDEL-Descriptor/descriptors.xml
        (b) varre caminhos de site-packages do ambiente atual (base/venv)
        Retorna Path (existente) ou None.
        """
        from pathlib import Path
        import sys, sysconfig, site

        # (a) Melhor caso: localizar via import do pacote
        try:
            import padelpy  # type: ignore
            xml_a = Path(padelpy.__file__).parent / "PaDEL-Descriptor" / "descriptors.xml"
            if xml_a.is_file():
                return xml_a
        except Exception:
            pass

        # (b) Caminhos candidatos de site-packages para o Python atual
        candidates_dirs = set()

        # sysconfig (purelib é o mais confiável)
        try:
            purelib = sysconfig.get_paths().get("purelib")
            if purelib:
                candidates_dirs.add(Path(purelib))
        except Exception:
            pass

        # site.getsitepackages() e getusersitepackages()
        try:
            for p in site.getsitepackages():
                candidates_dirs.add(Path(p))
        except Exception:
            pass
        try:
            usp = site.getusersitepackages()
            if usp:
                candidates_dirs.add(Path(usp))
        except Exception:
            pass

        # sys.prefix / sys.base_prefix / sys.exec_prefix (conda/venv costumam cair aqui)
        for base in (sys.prefix, sys.base_prefix, sys.exec_prefix):
            if not base:
                continue
            base = Path(base)
            # padrões comuns: .../lib/pythonX.Y/site-packages
            pyver = f"python{sys.version_info.major}.{sys.version_info.minor}"
            candidates_dirs.add(base / "lib" / pyver / "site-packages")
            # Windows (se for o caso no futuro): .../Lib/site-packages
            candidates_dirs.add(base / "Lib" / "site-packages")

        # Monta candidatos finais para o XML
        xml_candidates = []
        for sp in candidates_dirs:
            xml_candidates.append(sp / "padelpy" / "PaDEL-Descriptor" / "descriptors.xml")

        # Retorna o primeiro que existir
        for x in xml_candidates:
            if x.is_file():
                return x

        return None

    def _parse_descriptors_xml(self, xml_path):
        """
        Lê descriptors.xml e retorna tupla de listas:
        (one_two_d, three_d, fps)
        Baseado em <Group name="2D">, <Group name="3D">, <Group name="Fingerprint">.
        """
        import xml.etree.ElementTree as ET

        def parse_group_names(root, group_name):
            lst = []
            for grp in root.findall(".//Group"):
                if grp.get("name", "").strip().lower() == group_name.lower():
                    for desc in grp.findall("./Descriptor"):
                        nm = (desc.get("name") or "").strip()
                        if nm:
                            lst.append(nm)
            # Remove duplicatas preservando ordem
            return list(dict.fromkeys(lst))

        tree = ET.parse(str(xml_path))
        root = tree.getroot()
        one_two_d = parse_group_names(root, "2D")           # para chk_1D_2D
        three_d   = parse_group_names(root, "3D")           # para chk_3D
        fps       = parse_group_names(root, "Fingerprint")  # para chk_Fingerprint
        return one_two_d, three_d, fps

    def _on_descriptor_checkbox_toggled(self, dtype: str) -> None:
        checked = {
            "1D2D": self.chk_1D_2D.isChecked(),
            "3D": self.chk_3D.isChecked(),
            "FP": self.chk_Fingerprint.isChecked(),
        }[dtype]

        if checked:
            # lista alvo para esse tipo
            pool = self._padel_catalog.get(dtype, [])
            if not pool:
                return
            # evita duplicatas tanto do que já foi exibido quanto do que já existe na lista
            existing = set(self._qListWidget_items(self.list_descriptors))
            to_add = [x for x in pool if x not in self._shown_by_type[dtype] and x not in existing]
            if to_add:
                self.list_descriptors.addItems(to_add)
                self._shown_by_type[dtype].update(to_add)
        else:
            # remove apenas o que pertence a esse tipo
            self._remove_items_from_qListWidget(self.list_descriptors, self._shown_by_type[dtype])
            self._shown_by_type[dtype].clear()

        # mantém ordenado
        try:
            self.list_descriptors.sortItems()
        except Exception:
            pass

    def _qListWidget_items(self, lw) -> list[str]:
        return [lw.item(i).text() for i in range(lw.count())]

    def _remove_items_from_qListWidget(self, lw, items_to_remove: set[str]) -> None:
        """Remove do QListWidget apenas os itens cujos textos estão em items_to_remove."""
        if not items_to_remove:
            return
        # percorre de baixo para cima para não bagunçar os índices
        for i in range(lw.count() - 1, -1, -1):
            it = lw.item(i)
            if it and it.text() in items_to_remove:
                lw.takeItem(i)

    def run_select_structures(self):
        """
        Lê uma pasta com estruturas (.smi ou .sdf), faz split (multiligante),
        detecta 2D/3D (amostrando uma mol válida no caso de SDF),
        converte para 3D se chk_3dconvert estiver marcado, caso contrário gera/copia 1D (.smi).
        Gera um DataFrame [name, canonical_smiles] e salva em INTERNAL_DATA.
        """
        try:
            # ---------- Seleção de pasta ----------
            directory = QFileDialog.getExistingDirectory(self, "Selecione a pasta com .smi/.sdf")
            if not directory:
                return

            # ---------- Pastas de saída ----------
            job_dir = getattr(self, "job_dir", None)
            if not job_dir:
                QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), "Set up the job folder first.")
                return

            out_1d_dir = os.path.join(job_dir, "DATA_BASES", "STRUCTURES", "1D")
            out_3d_dir = os.path.join(job_dir, "DATA_BASES", "STRUCTURES", "3D")
            out_internal = os.path.join(job_dir, "DATA_BASES", "INTERNAL_DATA")
            for d in (out_1d_dir, out_3d_dir, out_internal):
                os.makedirs(d, exist_ok=True)

            # ---------- Flags/UI ----------
            convert_3d = bool(getattr(self, "chk_3dconvert", None) and self.chk_3dconvert.isChecked())
            target_chembl_id = self.ed_target_chembl_id.text().strip() if hasattr(self, "ed_target_chembl_id") else ""
            target_organism  = self.ed_organism_name.text().strip()     if hasattr(self, "ed_organism_name")   else ""
            out_csv = os.path.join(out_internal, f"df3_structures_{target_chembl_id}_{target_organism}.csv")

            # ---------- Utilitários ----------
            def _safe_name(mol, fallback):
                try:
                    nm = ""
                    if mol is not None:
                        # RDKit name fields comuns
                        for k in ("_Name", "NAME", "Name", "MOLNAME", "TITLE"):
                            if mol.HasProp(k):
                                nm = mol.GetProp(k).strip()
                                if nm:
                                    break
                    return nm or fallback
                except Exception:
                    return fallback

            def _canonical(smiles_or_mol):
                try:
                    if isinstance(smiles_or_mol, str):
                        m = Chem.MolFromSmiles(smiles_or_mol)
                    else:
                        m = smiles_or_mol
                    if m is None:
                        return None
                    return Chem.MolToSmiles(m, canonical=True)
                except Exception:
                    return None

            def _is_3d_mol(mol):
                try:
                    if mol is None or mol.GetNumConformers() == 0:
                        return False
                    conf = mol.GetConformer()
                    return bool(conf.Is3D())
                except Exception:
                    return False

            def _embed_optimize_3d(mol):
                # Gera coordenadas 3D e minimiza (MMFF se possível; fallback UFF)
                m = Chem.AddHs(mol)
                params = AllChem.ETKDGv3()
                params.randomSeed = 0xC0D
                cid = AllChem.EmbedMolecule(m, params)
                if cid != 0:
                    # tenta versão antiga
                    cid = AllChem.EmbedMolecule(m, AllChem.ETKDG())
                if cid != 0:
                    return None  # falhou
                try:
                    if AllChem.MMFFHasAllMoleculeParams(m):
                        AllChem.MMFFOptimizeMolecule(m, maxIters=500)
                    else:
                        AllChem.UFFOptimizeMolecule(m, maxIters=500)
                except Exception:
                    pass
                return Chem.RemoveHs(m)

            # ---------- Varredura de arquivos ----------
            sdf_files = []
            smi_files = []
            for fn in os.listdir(directory):
                low = fn.lower()
                if low.endswith(".sdf"):
                    sdf_files.append(os.path.join(directory, fn))
                elif low.endswith(".smi"):
                    smi_files.append(os.path.join(directory, fn))

            names, smiles_list = [], []

            # ---------- Processa .smi ----------
            # Regra: copiar para 1D e padronizar canonical SMILES (um por linha).
            for smi_path in smi_files:
                try:
                    # Copia o arquivo original para 1D (mantém um registro do bruto)
                    shutil.copy2(smi_path, os.path.join(out_1d_dir, os.path.basename(smi_path)))
                except Exception:
                    pass

                # Lê e normaliza por linha
                with open(smi_path, "r", encoding="utf-8", errors="ignore") as f:
                    for i, line in enumerate(f):
                        line = line.strip()
                        if not line:
                            continue
                        # Formatos típicos: "SMILES  NAME" (tab/space)
                        parts = re.split(r"\s+", line, maxsplit=1)
                        raw_smi = parts[0]
                        nm = parts[1].strip() if len(parts) > 1 else f"{Path(smi_path).stem}_{i+1}"
                        can = _canonical(raw_smi)
                        if can:
                            names.append(nm)
                            smiles_list.append(can)

                # Também salva um .smi canonicalizado por arquivo
                if names:
                    out_smi_canon = os.path.join(out_1d_dir, f"{Path(smi_path).stem}_canonical.smi")
                    with open(out_smi_canon, "w", encoding="utf-8") as fw:
                        # revarre apenas as entradas que vieram daquele arquivo? Simplesmente escreva do pool atual
                        # (opcional: poderia separar, mas não é obrigatório)
                        pass  # já temos tudo agregado ao DF; arquivo agregado é opcional

            # ---------- Processa .sdf ----------
            for sdf_path in sdf_files:
                # Carrega todas as mols (split automático RDKit)
                suppl = Chem.SDMolSupplier(sdf_path, removeHs=False)
                mols = [m for m in suppl if m is not None]
                if not mols:
                    continue

                # Detecta 2D/3D amostrando a 1ª válida com conf
                sample_is_3d = False
                for m in mols:
                    if m is None:
                        continue
                    if _is_3d_mol(m):
                        sample_is_3d = True
                    break

                if sample_is_3d:
                    # 3D → apenas copia o SDF para a pasta 3D (mantém multiligante)
                    try:
                        shutil.copy2(sdf_path, os.path.join(out_3d_dir, os.path.basename(sdf_path)))
                    except Exception:
                        pass

                    # Extrai SMILES (canonical) e nomes para o DF
                    for idx, m in enumerate(mols, start=1):
                        can = _canonical(Chem.Mol(m))
                        if can:
                            nm = _safe_name(m, f"{Path(sdf_path).stem}_{idx}")
                            names.append(nm)
                            smiles_list.append(can)

                else:
                    # 2D
                    if convert_3d:
                        # Converte cada molécula em 3D e salva como arquivos SDF individuais em 3D
                        for idx, m in enumerate(mols, start=1):
                            if m is None:
                                continue
                            m3d = _embed_optimize_3d(m)
                            if m3d is None:
                                # fallback: tenta pelo menos salvar 2D como está
                                m3d = m
                            nm = _safe_name(m, f"{Path(sdf_path).stem}_{idx}")
                            # salva 3D
                            out_file = os.path.join(out_3d_dir, f"{nm}.sdf")
                            try:
                                w = Chem.SDWriter(out_file)
                                w.write(m3d)
                                w.close()
                            except Exception:
                                pass
                            # coleta canonical smiles
                            can = _canonical(Chem.Mol(m))
                            if can:
                                names.append(nm)
                                smiles_list.append(can)
                    else:
                        # Não converter 3D → gerar canonical SMILES e salvar .smi individuais em 1D
                        out_smi = os.path.join(out_1d_dir, f"{Path(sdf_path).stem}_canonical.smi")
                        with open(out_smi, "w", encoding="utf-8") as fw:
                            for idx, m in enumerate(mols, start=1):
                                if m is None:
                                    continue
                                nm = _safe_name(m, f"{Path(sdf_path).stem}_{idx}")
                                can = _canonical(Chem.Mol(m))
                                if not can:
                                    continue
                                fw.write(f"{can}\t{nm}\n")
                                names.append(nm)
                                smiles_list.append(can)

            # ---------- DataFrame final ----------
            df = pd.DataFrame({"name": names, "canonical_smiles": smiles_list}).dropna().reset_index(drop=True)

            # Se não encontrou nada, avisa
            if df.empty:
                QMessageBox.information(self, i18n.t("msg_title_info", self._idioma), "No valid structure found in .smi/.sdf.")
                return

            # Remove duplicatas exatas de SMILES mantendo primeira ocorrência (ordem de leitura)
            df = df.drop_duplicates(subset=["canonical_smiles"], keep="first").reset_index(drop=True)

            # Salva e exibe
            df.to_csv(out_csv, index=False)
            self.df_selecionado = df
            self.show_dataframe(df)
            self.df_name_view5.setText(os.path.basename(out_csv))
            self._refresh_step4_dataframe_widgets()

            QMessageBox.information(self, "Pronto", f"Estruturas processadas.\nArquivo salvo em:\n{out_csv}")

        except Exception as e:
            QMessageBox.critical(self, i18n.t("msg_title_error", self._idioma), f"Error selecting/managing structures:\n{e}")

    def run_generate_descriptors(self):
        try:
            import os
            import re
            
            from PyQt5.QtCore import QThread, pyqtSignal, QTimer, QEventLoop, Qt
            from PyQt5.QtWidgets import QMessageBox, QProgressDialog, QApplication

            rdkit_fp_set = {
                "ECFP4 (RDkit clsssic)",
                "FCFP6 (RDkit)",
                "ECFP4 counting (without 1D2D)",
            }

            # ================== UI selections ==================
            # Colunas obrigatórias
            structure_col = self.cb_select_structure.currentText().strip()
            if not structure_col or structure_col not in self.df_selecionado.columns:
                QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), 'Please select a valid structure column in "Select structure column".')
                return

            name_col = self.cb_select_name_column.currentText().strip()
            if not name_col or name_col not in self.df_selecionado.columns:
                QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), 'Please select a valid name column in "Select name column".')
                return

            # Colunas opcionais
            bio_col   = self.cb_select_bioactivity.currentText().strip() if hasattr(self, "cb_select_bioactivity") else ""
            class_col = self.cb_class_column.currentText().strip()       if hasattr(self, "cb_class_column")       else ""

            # Checkboxes de tipo
            use_1d2d = bool(getattr(self, "chk_1D_2D", None) and self.chk_1D_2D.isChecked())
            use_3d   = bool(getattr(self, "chk_3D", None)    and self.chk_3D.isChecked())
            use_fp   = bool(getattr(self, "chk_Fingerprint", None) and self.chk_Fingerprint.isChecked())
            if not any([use_1d2d, use_3d, use_fp]):
                QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), "Please check at least one descriptors type (1D/2D, 3D, or Fingerprint).")
                return

            # Itens selecionados na lista de descritores
            if not hasattr(self, "list_descriptors") or self.list_descriptors.count() == 0:
                QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), "Descriptors list is empty.")
                return
            selected_names = [self.list_descriptors.item(i).text().strip()
                            for i in range(self.list_descriptors.count())
                            if self.list_descriptors.item(i).isSelected()]
            if not selected_names:
                cur = self.list_descriptors.currentItem()
                if cur:
                    selected_names = [cur.text().strip()]
            if not selected_names:
                QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), "Select at least one descriptor in the list.")
                return

            # ================== Preparar .smi ==================
            smi_df = (
                self.df_selecionado[[structure_col, name_col]]
                .dropna()
                .astype({structure_col: str, name_col: str})
            )
            smi_df[structure_col] = smi_df[structure_col].str.strip()
            smi_df[name_col]      = smi_df[name_col].str.strip()

            def _normalize_name_key(series):
                return series.fillna("").astype(str).str.strip()

            def _safe_parse_smiles(smiles_text):
                log_disabled = False
                try:
                    RDLogger.DisableLog("rdApp.error")
                    log_disabled = True
                    return Chem.MolFromSmiles(smiles_text)
                except Exception:
                    return None
                finally:
                    if log_disabled:
                        try:
                            RDLogger.EnableLog("rdApp.error")
                        except Exception:
                            pass

            def _normalize_smiles_text(smiles_text):
                smiles_text = (smiles_text or "").strip()
                if not smiles_text:
                    return ""
                replacements = {
                    " ": "",
                    "\t": "",
                    "\n": "",
                    "\r": "",
                    "–": "-",
                    "—": "-",
                    "−": "-",
                    "∕": "/",
                    "⁄": "/",
                    "\\/": "/",
                    "\u201c": '"',
                    "\u201d": '"',
                    "\u2018": "'",
                    "\u2019": "'",
                }
                for old, new in replacements.items():
                    smiles_text = smiles_text.replace(old, new)
                return smiles_text

            def _candidate_smiles_repairs(smiles_text):
                candidates = []

                def _push(candidate):
                    candidate = _normalize_smiles_text(candidate)
                    if candidate and candidate not in candidates:
                        candidates.append(candidate)

                _push(smiles_text)
                normalized = _normalize_smiles_text(smiles_text)
                _push(normalized)

                # Corrige um erro comum de exportação em anéis aromáticos conjugados:
                # fragmentos como '=Crccc...c2' perdem o primeiro átomo aromático e o índice inicial do anel.
                ring_repair = re.sub(r"=Cr(?=[a-z].*\d)", "=Cc1", normalized)
                _push(ring_repair)
                ring_repair = re.sub(r"([/\\])Cr(?=[a-z].*\d)", r"\1Cc1", normalized)
                _push(ring_repair)

                return candidates

            def _canonicalize_smiles_with_repair(smiles_text):
                for candidate in _candidate_smiles_repairs(smiles_text):
                    mol = _safe_parse_smiles(candidate)
                    if mol is None:
                        continue
                    try:
                        canonical = Chem.MolToSmiles(mol, canonical=True)
                    except Exception:
                        continue
                    if canonical:
                        repaired = _normalize_smiles_text(smiles_text) != candidate
                        return canonical, repaired, candidate
                return None, False, None

            parsed_rows = smi_df[structure_col].map(_canonicalize_smiles_with_repair)
            smi_df[structure_col] = parsed_rows.map(lambda x: x[0])
            invalid_mask = smi_df[structure_col].isna() | smi_df[structure_col].eq("")
            invalid_count = int(invalid_mask.sum())
            invalid_examples = smi_df.loc[invalid_mask, name_col].astype(str).head(5).tolist()
            repaired_examples = []
            repaired_count = 0
            for idx, (_, repaired, candidate) in parsed_rows.items():
                if repaired:
                    repaired_count += 1
                    if len(repaired_examples) < 5:
                        repaired_examples.append(f"{smi_df.at[idx, name_col]} -> {candidate}")
            smi_df = smi_df.loc[~invalid_mask].copy()

            if smi_df.empty:
                QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma),
                    "No valid structures were found in the selected structure column."
                )
                return

            duplicate_smiles_removed = int(len(smi_df) - len(smi_df.drop_duplicates(subset=[structure_col], keep="first")))
            smi_df = smi_df.drop_duplicates(subset=[structure_col], keep="first")

            source_pairs = smi_df[[name_col, structure_col]].copy()
            source_pairs["Name"] = _normalize_name_key(source_pairs[name_col])
            source_pairs["SMILES"] = source_pairs[structure_col].astype(str).str.strip()
            source_pairs = source_pairs.loc[source_pairs["Name"].ne("") & source_pairs["SMILES"].ne("")].copy()
            duplicate_name_removed = int(len(source_pairs) - len(source_pairs.drop_duplicates(subset=["Name"], keep="first")))
            source_pairs = source_pairs.drop_duplicates(subset=["Name"], keep="first")[["Name", "SMILES"]]

            smi_dir = os.path.join(self.job_dir, "DATA_BASES", "STRUCTURES", "1D")
            os.makedirs(smi_dir, exist_ok=True)
            smi_path = os.path.join(
                smi_dir, f"multiligand_{self.ed_target_chembl_id.text().strip()}.smi"
            )
            smi_df[[structure_col, name_col]].to_csv(smi_path, sep="\t", header=False, index=False)

            if repaired_count or invalid_count:
                msg_lines = []
                if repaired_count:
                    repaired_msg = f"{repaired_count} structure(s) were automatically repaired before descriptor generation."
                    if repaired_examples:
                        repaired_msg += "\nRepaired examples: " + "; ".join(repaired_examples)
                    msg_lines.append(repaired_msg)
                if invalid_count:
                    invalid_msg = f"{invalid_count} invalid or empty structure(s) were ignored before descriptor generation."
                    if invalid_examples:
                        invalid_msg += "\nSkipped examples: " + ", ".join(invalid_examples)
                    msg_lines.append(invalid_msg)
                QMessageBox.warning(
                    self,
                    "Structure cleanup summary",
                    "\n\n".join(msg_lines)
                )

            # ================== Ler XML base ==================
            base_xml_path = os.path.join(self.dp_dir, "BASE", "DESCRIPTORS", "Descriptors.xml")
            if not os.path.isfile(base_xml_path):
                QMessageBox.critical(self, i18n.t("msg_title_error", self._idioma), f"Base XML not found:\n{base_xml_path}")
                return

            import xml.etree.ElementTree as ET
            base_tree = ET.parse(base_xml_path)
            base_root = base_tree.getroot()

            # Construir mapa nome→grupo a partir do seu XML:
            # Groups exatamente: "2D", "3D", "Fingerprint"
            name_to_group = {}
            for grp in base_root.findall("./Group"):
                gname = (grp.get("name") or "").strip()
                # Normaliza nome do grupo para usar nas pastas de saída
                if gname == "2D":
                    out_group = "1D2D"
                elif gname == "3D":
                    out_group = "3D"
                elif gname == "Fingerprint":
                    out_group = "fingerprint"
                else:
                    # fallback conservador
                    out_group = "1D2D"

                for desc in grp.findall("./Descriptor"):
                    dname = (desc.get("name") or "").strip()
                    if dname:
                        name_to_group[dname] = out_group

            # Helper: cria XML individual com apenas 1 descritor = true
            def _write_single_descriptor_xml(src_xml: str, descriptor_name: str, dst_xml: str) -> str:
                tree = ET.parse(src_xml)
                root = tree.getroot()
                found = False
                # zera todos
                for d in root.findall(".//Descriptor"):
                    if "value" in d.attrib:
                        d.set("value", "false")
                # liga o desejado
                for d in root.findall(".//Descriptor"):
                    nm = (d.get("name") or "").strip()
                    if nm == descriptor_name:
                        d.set("value", "true")
                        found = True
                        break
                if not found:
                    raise FileNotFoundError(f"Descriptor '{descriptor_name}' not found in base XML.")
                os.makedirs(os.path.dirname(dst_xml), exist_ok=True)
                tree.write(dst_xml, encoding="utf-8", xml_declaration=True)
                return dst_xml

            # ============ Worker para rodar PaDEL em thread (não travar UI) ============
            class PaDELWorker(QThread):
                finished_signal = pyqtSignal(str)  # csv_path
                error_signal = pyqtSignal(str)

                def __init__(self, padel_kwargs: dict):
                    super().__init__()
                    self.padel_kwargs = padel_kwargs

                def run(self):
                    try:
                        from padelpy import padeldescriptor
                        padeldescriptor(**self.padel_kwargs)
                        self.finished_signal.emit(self.padel_kwargs.get("d_file", ""))
                    except Exception as e:
                        self.error_signal.emit(str(e))

            # ================== Loop por descritor ==================
            csv_paths = []
            for dname in selected_names:
                if dname in rdkit_fp_set:
                    # gera um CSV para este fingerprint com RDKit e adiciona a csv_paths
                    try:
                        # decide bits a partir do spinner, se existir
                        fp_bits = getattr(self, "spn_ecfp_bits", None).value() if hasattr(self, "spn_ecfp_bits") else 2048
                        fp_chiral = True  # ou ler de um checkbox seu, se houver

                        # calcula um DataFrame de FP para este modo
                        df_fp = self._compute_rdkit_fp_single_mode(
                            mode=dname,
                            structure_col=structure_col,
                            name_col=name_col,
                            fp_bits=fp_bits,
                            fp_chirality=fp_chiral,
                        )

                        out_xml_dir = os.path.join(self.job_dir, "DATA_BASES", "DESCRIPTORS", "fingerprint")
                        os.makedirs(out_xml_dir, exist_ok=True)
                        csv_out = os.path.join(out_xml_dir, f"df_desc_{dname}.csv")
                        df_fp.to_csv(csv_out, index=False)

                        csv_paths.append((dname, csv_out, "fingerprint"))
                    except Exception as e:
                        QMessageBox.warning(self, "RDKit FP error", f"{dname}: {e}")
                    continue  # não deixa cair no bloco do PaDEL

                group = name_to_group.get(dname, None)
                if group is None:
                    QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), f"Descriptor not found in base XML: {dname}")
                    continue

                # respeita checkboxes
                if group == "1D2D" and not use_1d2d:
                    continue
                if group == "3D" and not use_3d:
                    continue
                if group == "fingerprint" and not use_fp:
                    continue

                out_xml_dir = os.path.join(self.job_dir, "DATA_BASES", "DESCRIPTORS", group)
                os.makedirs(out_xml_dir, exist_ok=True)
                out_xml = os.path.join(out_xml_dir, f"{dname}.xml")
                _write_single_descriptor_xml(base_xml_path, dname, out_xml)

                # CSV de saída (um por descritor)
                csv_out = os.path.join(out_xml_dir, f"df_desc_{dname}.csv")
                log_path = csv_out + ".log"  # mesmo diretório e mesmo nome base do CSV do descritor

                # remover log antigo (se houver) para começar do zero
                try:
                    if os.path.exists(log_path):
                        os.remove(log_path)
                except Exception:
                    pass

                # Flags comuns do pré-processamento no PaDEL
                removesalt  = bool(getattr(self, "chk_salt", None)         and self.chk_salt.isChecked())
                aromaticity = bool(getattr(self, "chk_aromaticity", None)  and self.chk_aromaticity.isChecked())
                tautomers   = bool(getattr(self, "chk_tautomers", None)    and self.chk_tautomers.isChecked())
                nitro_std   = bool(getattr(self, "chk_nitro", None)        and self.chk_nitro.isChecked())
                retain3d    = bool(getattr(self, "chk_3dcoord", None)      and self.chk_3dcoord.isChecked())
                convert3d   = bool(getattr(self, "chk_3dconvert", None)    and self.chk_3dconvert.isChecked())

                kwargs = dict(
                    mol_dir=smi_path,                  
                    d_file=csv_out,
                    descriptortypes=out_xml,
                    detectaromaticity=bool(aromaticity),
                    standardizenitro=bool(nitro_std),
                    standardizetautomers=bool(tautomers),
                    threads=os.cpu_count() or 8,
                    removesalt=bool(removesalt),
                    log=True,                  
                    retainorder=True,
                    d_2d=False,
                    d_3d=False,
                    retain3d=bool(retain3d),
                    convert3d=bool(convert3d),
                    fingerprints=False
                )
                if group in ("1D2D", "2D"):
                    kwargs["d_2d"] = True
                elif group in ("3D"):
                    kwargs["d_3d"] = True
                elif group in ("fingerprint", "Fingerprint"):
                    kwargs["fingerprints"] = True

                # ====== Barra de progresso para ESTE descritor ======
                progress = QProgressDialog(f"Running PaDEL-Descriptor for {dname}...", None, 0, 100, self)
                progress.setWindowTitle("PaDEL running")
                progress.setWindowModality(Qt.ApplicationModal)
                progress.setMinimumDuration(0)
                progress.setCancelButton(None)
                progress.setAutoClose(False)
                progress.setAutoReset(False)
                progress.setValue(0)

                # mostrar % dentro da barra
                bar = progress.findChild(QProgressBar)
                if bar is not None:
                    bar.setTextVisible(True)
                    bar.setFormat("%p%")

                progress.show()
                QApplication.processEvents()

                # Timer para ler o .log e atualizar
                pat = re.compile(r"\((\d+)\s*/\s*(\d+)\)")
                _last_percent = [0]

                def _update_from_log():
                    if not os.path.exists(log_path):
                        return
                    try:
                        with open(log_path, "rb") as f:
                            data = f.read().decode(errors="ignore")
                        m_all = pat.findall(data)
                        if not m_all:
                            return
                        cur, tot = m_all[-1]
                        cur = int(cur); tot = int(tot)
                        if tot <= 0:
                            return
                        percent = max(0, min(100, int(round((cur * 100.0) / tot))))
                        if percent >= _last_percent[0]:
                            _last_percent[0] = percent
                            progress.setValue(percent)
                            progress.setLabelText(f"PaDEL {dname}... {cur}/{tot} ({percent}%)")
                        QApplication.processEvents()
                    except Exception:
                        pass

                timer = QTimer(progress)
                timer.timeout.connect(_update_from_log)
                timer.start(300)

                # Dispara PaDEL em worker e espera terminar mantendo UI responsiva
                worker = PaDELWorker(kwargs)
                loop = QEventLoop()

                def _done(_csv):
                    timer.stop()
                    progress.setValue(100)
                    progress.setLabelText(f"PaDEL {dname}... done (100%)")
                    progress.close()
                    loop.quit()

                def _err(msg):
                    timer.stop()
                    progress.close()
                    QMessageBox.critical(self, "PaDEL error", f"{dname}: {msg}")
                    loop.quit()

                worker.finished_signal.connect(_done)
                worker.error_signal.connect(_err)
                worker.start()
                loop.exec_()


                # Verifica saída
                if not os.path.exists(csv_out) or os.path.getsize(csv_out) == 0:
                    QMessageBox.warning(self, i18n.t("msg_title_warning", self._idioma), f"PaDEL did not produce CSV for: {dname}\nCheck XML and .smi.")
                    continue

                csv_paths.append((dname, csv_out, group))

            if not csv_paths:
                QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), "No descriptor CSV was produced.")
                return

            # ================== Concatena por 'Name' ==================
            df_final = None
            for dname, csv_file, _grp in csv_paths:
                try:
                    df_i = pd.read_csv(csv_file)
                    # Normalizar 'Name'
                    if "Name" not in df_i.columns and "name" in df_i.columns:
                        df_i = df_i.rename(columns={"name": "Name"})
                    if "Name" not in df_i.columns:
                        raise ValueError(f"'Name' column not found in {csv_file}")

                    df_i["Name"] = _normalize_name_key(df_i["Name"])
                    df_i = df_i.loc[df_i["Name"].ne("")].copy()
                    if df_i.empty:
                        raise ValueError(f"'Name' column is empty in {csv_file}")
                    df_i = df_i.drop_duplicates(subset=["Name"], keep="first")
                    df_i["_name_key"] = df_i["Name"]

                    # Remove SMILES se presente
                    if "SMILES" in df_i.columns:
                        df_i = df_i.drop(columns=["SMILES"])

                    # Merge progressivo por Name
                    if df_final is None:
                        df_final = df_i.copy()
                    else:
                        df_i = df_i.drop(columns=["Name"], errors="ignore")
                        df_final = pd.merge(df_final, df_i, on="_name_key", how="inner")

                except Exception as e:
                    QMessageBox.warning(self, "Concat warning", f"Failed to append {dname}: {e}")

            if df_final is None or df_final.empty:
                QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), "Final descriptor frame is empty.")
                return

            df_final["Name"] = _normalize_name_key(df_final["Name"]).replace("", pd.NA)
            df_final["Name"] = df_final["Name"].fillna(df_final["_name_key"])
            df_final = df_final.loc[df_final["Name"].notna()].copy()
            df_final = df_final.drop_duplicates(subset=["Name"], keep="first")

            df_final = pd.merge(source_pairs, df_final, on="Name", how="inner")

            missing_after_generation = source_pairs.loc[~source_pairs["Name"].isin(df_final["Name"])].copy()

            ordered_cols = ["Name", "SMILES"] + [col for col in df_final.columns if col not in {"Name", "SMILES", "_name_key"}]
            df_final = df_final[ordered_cols + (["_name_key"] if "_name_key" in df_final.columns else [])]

            # ================== Converte colunas binárias float→int antes de salvar ==================
            for _col in df_final.columns:
                if _col in {"Name", "_name_key"}:
                    continue
                _s = df_final[_col]
                if pd.api.types.is_float_dtype(_s):
                    _uniq = _s.dropna().unique()
                    if set(_uniq.astype(int)).issubset({0, 1}) and (_uniq == _uniq.astype(int)).all():
                        df_final[_col] = _s.fillna(0).astype(int)

            # ================== Salvar resultado final ==================
            target_chembl_id = self.ed_target_chembl_id.text().strip() if hasattr(self, "ed_target_chembl_id") else "without_target_id"
            target_organism  = self.ed_organism_name.text().strip() if hasattr(self, "ed_organism_name") else "without_organism_name"

            def _drop_trailing_empty_column(df_out):
                if df_out is None or df_out.empty or len(df_out.columns) <= 1:
                    return df_out
                last_col = df_out.columns[-1]
                last_series = df_out[last_col]
                if last_series.isna().all():
                    return df_out.iloc[:, :-1].copy()
                if last_series.astype(str).str.strip().replace({"": pd.NA, "nan": pd.NA, "NaN": pd.NA, "None": pd.NA}).isna().all():
                    return df_out.iloc[:, :-1].copy()
                return df_out

            report_lines = []
            report_lines.append("Descriptor generation audit")
            report_lines.append(f"Input rows sent to descriptor generation: {len(source_pairs)}")
            report_lines.append(f"Rows in final descriptor result: {len(df_final)}")
            report_lines.append(f"Duplicate rows removed by SMILES before generation: {duplicate_smiles_removed}")
            report_lines.append(f"Duplicate rows removed by Name before generation: {duplicate_name_removed}")
            report_lines.append(f"Compounds removed after descriptor generation: {len(missing_after_generation)}")
            report_lines.append("")
            if not missing_after_generation.empty:
                report_lines.append("Compounds without final descriptors:")
                for _name, _smiles in missing_after_generation[["Name", "SMILES"]].itertuples(index=False):
                    report_lines.append(f"- {_name} | {_smiles}")
            else:
                report_lines.append("All compounds sent to descriptor generation were preserved in the final result.")

            internal_dir = os.path.join(self.job_dir, "DATA_BASES", "INTERNAL_DATA")
            external_dir = os.path.join(self.job_dir, "DATA_BASES", "EXTERNAL_DATA")
            if not self.cb_select_bioactivity.currentText().strip():
                bio_col = self.cb_bioactivity_column.currentText().strip() if hasattr(self, "cb_bioactivity_column") else ""
                if bio_col:  # só cria se o nome não estiver vazio
                    df_final[bio_col] = ""
                df_final = df_final.drop(columns=["_name_key"], errors="ignore")
                df_final = df_final[["Name", "SMILES"] + [col for col in df_final.columns if col not in {"Name", "SMILES"}]]
                df_final = _drop_trailing_empty_column(df_final)
                out_name = f"df_external_descriptors_{target_chembl_id}_{target_organism}.csv"
                out_path = os.path.join(external_dir, out_name)
                df_final.to_csv(out_path, index=False)
            else:
                # ================== Agregar bioatividade/classe (opcional) ==================
                source_meta = self.df_selecionado.copy()
                source_meta["_name_key"] = _normalize_name_key(source_meta[name_col])

                if bio_col and bio_col in self.df_selecionado.columns:
                    _map_bio = source_meta.loc[source_meta["_name_key"].ne("")].drop_duplicates(subset=["_name_key"]).set_index("_name_key")[bio_col]
                    df_final[bio_col] = df_final["_name_key"].map(_map_bio)

                if class_col and class_col in self.df_selecionado.columns:
                    _map_cls = source_meta.loc[source_meta["_name_key"].ne("")].drop_duplicates(subset=["_name_key"]).set_index("_name_key")[class_col]
                    df_final[class_col] = df_final["_name_key"].map(_map_cls)            

                df_final = df_final.drop(columns=["_name_key"], errors="ignore")
                df_final = df_final[["Name", "SMILES"] + [col for col in df_final.columns if col not in {"Name", "SMILES"}]]
                df_final = _drop_trailing_empty_column(df_final)
                os.makedirs(internal_dir, exist_ok=True)
                bio_col_name = bio_col.replace(" ", "_") if bio_col else "NoBioactivity"
                out_name = f"df3_descriptors_{bio_col_name}_{target_chembl_id}_{target_organism}.csv"
                out_path = os.path.join(internal_dir, out_name)
                df_final.to_csv(out_path, index=False)

            # Atualiza referência e exibe
            self.df_selecionado = df_final.copy()
            self.show_dataframe(self.df_selecionado)
            self.df_name_view5.setText(os.path.basename(out_path))
            self._refresh_step4_dataframe_widgets()
            self.show_output(report_lines, "Descriptor Generation Audit")
            QMessageBox.information(self, i18n.t("msg_title_success", self._idioma), f"Descriptors calculated and saved to:\n{out_path}")

        except Exception as e:
            QMessageBox.critical(self, i18n.t("msg_title_error", self._idioma), f"An error occurred while generating descriptors:\n{e}")

