    def _extract_usi_from_any_path(self, path):
        """Returns the USI code for any path under RESULTS/USI/<usi>/..., regardless of which
        step (PREDICTIONS, DATA, MIDIA, MODELS) wrote it."""
        if not path or not getattr(self, "job_dir", ""):
            return None
        usi_root = os.path.join(self.job_dir, "RESULTS", "USI")
        try:
            rel_path = os.path.relpath(os.path.abspath(path), os.path.abspath(usi_root))
        except Exception:
            return None
        if rel_path.startswith(".."):
            return None
        parts = [part for part in rel_path.split(os.sep) if part and part != "."]
        return parts[0] if parts else None

    def _consensus_metric_weight_for_path(self, file_path):
        """Best-effort R2 Test (regression) / F1 (classification) lookup for a consensus
        slot's source file, used only to prefill the Weighted Consensus weight field with an
        editable suggestion. Returns None (leaving the field blank for manual entry) whenever
        the file isn't traceable to a known USI or the model/metric can't be matched - this
        must never block the user from typing a weight in by hand."""
        usi = self._extract_usi_from_any_path(file_path)
        if not usi:
            return None
        usi_dir = os.path.join(self.job_dir, "RESULTS", "USI", usi)

        skl_path = os.path.join(usi_dir, "skl_session.json")
        if os.path.isfile(skl_path):
            try:
                session = json.loads(Path(skl_path).read_text(encoding="utf-8"))
                task = str(session.get("task", "")).strip().lower()
                model_name = session.get("current_model") or session.get("best_model")
                metric_col = "R2 Test" if task == "regression" else "F1"
                screening_files = sorted(
                    glob.glob(os.path.join(usi_dir, "DATA", "skl_screening_*.csv")),
                    key=os.path.getmtime, reverse=True,
                )
                if model_name and screening_files:
                    df = pd.read_csv(screening_files[0])
                    if "Model" in df.columns and metric_col in df.columns:
                        match = df.loc[df["Model"] == model_name, metric_col]
                        if not match.empty and pd.notna(match.iloc[0]):
                            return float(match.iloc[0])
            except Exception:
                pass

        pyc_path = os.path.join(usi_dir, "pycaret_session.json")
        if os.path.isfile(pyc_path):
            try:
                session = json.loads(Path(pyc_path).read_text(encoding="utf-8"))
                task = str(session.get("task", "")).strip().lower()
                model_label = str(session.get("best_model_label", ""))
                metric_col = "R2" if task == "regression" else "F1"
                compare_files = sorted(
                    glob.glob(os.path.join(usi_dir, "DATA", "df_pycaret_compare_*.csv")),
                    key=os.path.getmtime, reverse=True,
                )
                if model_label and compare_files:
                    df = pd.read_csv(compare_files[0])
                    if "Model" in df.columns and metric_col in df.columns:
                        label_norm = model_label.lower().replace(" ", "")
                        for _, row in df.iterrows():
                            name_norm = str(row["Model"]).lower().replace(" ", "")
                            if name_norm and name_norm in label_norm:
                                if pd.notna(row[metric_col]):
                                    return float(row[metric_col])
            except Exception:
                pass
        return None

    def _consensus_load_dataset(self, slot):
        try:
            base_dir = self._get_usi_predictions_initial_dir()

            file_path, _ = QFileDialog.getOpenFileName(
                self,
                f"Select dataset {slot} for consensus analysis",
                base_dir,
                "Data Files (*.csv *.xlsx);;CSV Files (*.csv);;Excel Files (*.xlsx)"
            )

            if not file_path or not os.path.isfile(file_path):
                QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), f"File not found:\n{file_path}")
                return

            df = self._read_selected_table_file(file_path)
            if df.empty:
                QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), f"Selected dataset is empty:\n{file_path}")
                return

            setattr(self, f"consensus_df{slot}", df.copy())
            setattr(self, f"consensus_file_path{slot}", file_path)

            line_edit = getattr(self, f"ed_consensus_dataset_{slot}", None)
            cb_id = getattr(self, f"cb_consensus_id_col_{slot}", None)
            cb_value = getattr(self, f"cb_consensus_value_col_{slot}", None)
            columns = df.columns.astype(str).tolist()

            if line_edit is not None:
                line_edit.setText(os.path.basename(file_path))

            for combo in (cb_id, cb_value):
                if combo is None:
                    continue
                combo.clear()
                combo.addItems([""] + columns)
                combo.setCurrentIndex(0)

            preferred_id_cols = ["molecule_chembl_id", "Molecule_ChEMBL_ID", "compound_id", "ID", "Name", "name"]
            preferred_value_cols = ["value", "Value", "bioactivity", "Bioactivity", "pIC50", "PIC50", "IC50"]

            if cb_id is not None:
                for candidate in preferred_id_cols:
                    idx = cb_id.findText(candidate)
                    if idx >= 0:
                        cb_id.setCurrentIndex(idx)
                        break

            if cb_value is not None:
                for candidate in preferred_value_cols:
                    idx = cb_value.findText(candidate)
                    if idx >= 0:
                        cb_value.setCurrentIndex(idx)
                        break

            weight_widget = getattr(self, f"ed_consensus_weight_{slot}", None)
            if weight_widget is not None:
                weight_widget.clear()
                metric = self._consensus_metric_weight_for_path(file_path)
                if metric is not None:
                    weight_widget.setText(f"{metric:.4g}")

            self.show_dataframe(df)

        except Exception as e:
            QMessageBox.critical(self, i18n.t("msg_title_error", self._idioma), f"An error occurred while loading dataset:\n{e}")

