    def _consensus_collect_selection_rows(self):
        rows = []
        for slot in range(1, 11):
            df = getattr(self, f"consensus_df{slot}", None)
            dataset_widget = getattr(self, f"ed_consensus_dataset_{slot}", None)
            id_widget = getattr(self, f"cb_consensus_id_col_{slot}", None)
            value_widget = getattr(self, f"cb_consensus_value_col_{slot}", None)
            rows.append({
                "slot": slot,
                "df": df,
                "dataset_name": dataset_widget.text().strip() if dataset_widget is not None else "",
                "id_col": id_widget.currentText().strip() if id_widget is not None else "",
                "value_col": value_widget.currentText().strip() if value_widget is not None else "",
                "file_path": getattr(self, f"consensus_file_path{slot}", ""),
            })
        return rows

    def _consensus_validate_inputs(self):
        rows = self._consensus_collect_selection_rows()
        selected_rows = []
        incomplete_slots = []

        for row in rows:
            has_any_value = bool(row["df"] is not None or row["dataset_name"] or row["id_col"] or row["value_col"])
            complete = bool(row["df"] is not None and row["dataset_name"] and row["id_col"] and row["value_col"])

            if complete:
                selected_rows.append(row)
            elif has_any_value:
                incomplete_slots.append(str(row["slot"]))

        if incomplete_slots:
            QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma),
                "Complete all consensus selections before running the analysis. Missing or incomplete rows: "
                + ", ".join(incomplete_slots)
                + "."
            )
            return None

        if len(selected_rows) < 2:
            QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma),
                "Select at least two complete dataframes before running the consensus analysis."
            )
            return None

        id_cols = [row["id_col"] for row in selected_rows]
        if len(set(id_cols)) != 1:
            QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma),
                "The selected ID column names must be the same across the chosen dataframes."
            )
            return None

        # Value Column pode ter nomes diferentes entre os dataframes selecionados (ex.: predições de
        # vários modelos da STEP 6 geram colunas como "IC50_RandomForestRegressor" e
        # "IC50_BaggingRegressor") — em vez de exigir o mesmo nome literal, valida que os dados são
        # compatíveis: mesmo número de linhas e mesma natureza numérica/escala (para não misturar por
        # engano, por exemplo, uma coluna em IC50 (nM) com outra em pIC50, escala logarítmica).
        row_counts = set()
        scale_refs = []
        for row in selected_rows:
            df = row["df"]
            value_col = row["value_col"]
            if value_col not in df.columns:
                QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma),
                    f"Column '{value_col}' was not found in dataset '{row['dataset_name']}' (slot {row['slot']})."
                )
                return None
            row_counts.add(len(df))
            numeric_vals = pd.to_numeric(df[value_col], errors="coerce")
            valid_ratio = numeric_vals.notna().mean() if len(numeric_vals) else 0
            if valid_ratio < 0.5:
                QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma),
                    f"Column '{value_col}' in dataset '{row['dataset_name']}' (slot {row['slot']}) "
                    "does not look numeric — the Value Column must contain numeric bioactivity values."
                )
                return None
            finite_vals = numeric_vals.dropna()
            if not finite_vals.empty:
                scale_refs.append((row["slot"], row["dataset_name"], value_col, float(finite_vals.abs().median())))

        if len(row_counts) != 1:
            QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma),
                "The selected dataframes have different numbers of rows "
                f"({', '.join(str(c) for c in sorted(row_counts))}). Value Column names may differ, "
                "but all selected dataframes must have the same number of records."
            )
            return None

        # Heurística de escala: medianas (em módulo) muito distantes entre colunas (>100x) costumam
        # indicar métricas diferentes misturadas por engano (ex.: IC50 em nM vs pIC50 em escala
        # logarítmica), o que invalidaria os métodos de consenso baseados em Z-Score.
        magnitudes = [abs_med for (*_ignored, abs_med) in scale_refs if abs_med > 0]
        if len(magnitudes) >= 2 and (max(magnitudes) / min(magnitudes)) > 100:
            detail = "; ".join(
                f"slot {slot} ({name}): '{col}' median={med:.4g}" for slot, name, col, med in scale_refs
            )
            QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma),
                "The selected Value Columns appear to be on very different numeric scales "
                f"(possible metric/unit mismatch — e.g. IC50 vs pIC50): {detail}\n\n"
                "Make sure all selected columns use the same bioactivity metric and scale before "
                "running the consensus analysis."
            )
            return None

        return selected_rows

    def _consensus_rank_ascending(self):
        return hasattr(self, "chk_consensus_increase") and self.chk_consensus_increase.isChecked()

    def clear_step7_consensus_group(self):
        for slot in range(1, 11):
            setattr(self, f"consensus_df{slot}", None)
            setattr(self, f"consensus_file_path{slot}", "")

            dataset_widget = getattr(self, f"ed_consensus_dataset_{slot}", None)
            id_widget = getattr(self, f"cb_consensus_id_col_{slot}", None)
            value_widget = getattr(self, f"cb_consensus_value_col_{slot}", None)
            weight_widget = getattr(self, f"ed_consensus_weight_{slot}", None)

            if dataset_widget is not None:
                dataset_widget.clear()
            if weight_widget is not None:
                weight_widget.clear()

            for combo in (id_widget, value_widget):
                if combo is None:
                    continue
                combo.clear()
                combo.addItems([""])
                combo.setCurrentIndex(0)

        if hasattr(self, "chk_consensus_increase"):
            self.chk_consensus_increase.setChecked(False)
        if hasattr(self, "chk_consensus_decrease"):
            self.chk_consensus_decrease.setChecked(True)
        if hasattr(self, "cb_consensus_method"):
            self.cb_consensus_method.setCurrentIndex(0)
        if hasattr(self, "ed_consensus_cv_max"):
            self.ed_consensus_cv_max.setText("5")
        if hasattr(self, "ed_consensus_hit_percent"):
            self.ed_consensus_hit_percent.setText("1")

    CONSENSUS_METHODS = [
        "Z-Score (Mean/SD)",
        "Z-Score (Median/MAD)",
        "Rank Sum / Borda count",
        "Reciprocal Rank Fusion (RRF)",
        "Weighted Consensus",
    ]
    CONSENSUS_RRF_K = 60  # standard constant from the reciprocal rank fusion literature

    def run_consensus_generate(self):
        rows = self._consensus_validate_inputs()
        if rows is None:
            return

        try:
            method = self.cb_consensus_method.currentText().strip() if hasattr(self, "cb_consensus_method") else self.CONSENSUS_METHODS[0]
            if method not in self.CONSENSUS_METHODS:
                method = self.CONSENSUS_METHODS[0]

            processed_frames = {}
            merged = None
            selected_slots = [row["slot"] for row in rows]
            selected_count = len(selected_slots)
            id_col_name = rows[0]["id_col"]
            # Value Column pode ter nomes diferentes por dataframe (ver _consensus_validate_inputs) —
            # usado só para o texto do relatório abaixo.
            value_col_names = [row["value_col"] for row in rows]
            value_col_label = value_col_names[0] if len(set(value_col_names)) == 1 else "; ".join(
                f"slot {row['slot']}: {row['value_col']}" for row in rows
            )
            rank_ascending = self._consensus_rank_ascending()

            weights = {}
            for row in rows:
                slot = row["slot"]
                weight_widget = getattr(self, f"ed_consensus_weight_{slot}", None)
                weight_text = weight_widget.text().strip() if weight_widget is not None else ""
                try:
                    weights[slot] = float(weight_text) if weight_text else 1.0
                except ValueError:
                    weights[slot] = 1.0

            for row in rows:
                slot = row["slot"]
                df = row["df"].copy()
                id_col = row["id_col"]
                value_col = row["value_col"]

                work_df = df[[id_col, value_col]].copy()
                work_df[id_col] = work_df[id_col].astype(str).str.strip()
                work_df[value_col] = pd.to_numeric(work_df[value_col], errors="coerce")
                work_df = work_df.dropna(subset=[id_col, value_col])
                work_df = work_df[work_df[id_col] != ""]

                if work_df.empty:
                    QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), f"Dataset {slot} has no valid numeric rows for the selected columns.")
                    return

                grouped = work_df.groupby(id_col, as_index=False)[value_col].mean()

                # Z-score (Mean/SD) - also the per-list score feeding Weighted Consensus.
                std_value = grouped[value_col].std(ddof=0)
                if pd.isna(std_value) or np.isclose(std_value, 0.0):
                    grouped[f"zscore_list_{slot}"] = 0.0
                else:
                    grouped[f"zscore_list_{slot}"] = (grouped[value_col] - grouped[value_col].mean()) / std_value

                # Z-score (Median/MAD) - robust variant (Iglewicz & Hoya "modified z-score";
                # 1.4826 scales MAD to be comparable to SD under normality).
                median_value = grouped[value_col].median()
                mad_value = (grouped[value_col] - median_value).abs().median()
                if pd.isna(mad_value) or np.isclose(mad_value, 0.0):
                    grouped[f"robust_zscore_list_{slot}"] = 0.0
                else:
                    grouped[f"robust_zscore_list_{slot}"] = (grouped[value_col] - median_value) / (mad_value * 1.4826)

                grouped[f"rank_list_{slot}"] = grouped[value_col].rank(method="min", ascending=rank_ascending).astype(int)
                grouped[f"rrf_list_{slot}"] = 1.0 / (self.CONSENSUS_RRF_K + grouped[f"rank_list_{slot}"])

                if method == "Z-Score (Median/MAD)":
                    grouped[f"score_list_{slot}"] = grouped[f"robust_zscore_list_{slot}"]
                elif method == "Rank Sum / Borda count":
                    grouped[f"score_list_{slot}"] = grouped[f"rank_list_{slot}"].astype(float)
                elif method == "Reciprocal Rank Fusion (RRF)":
                    grouped[f"score_list_{slot}"] = grouped[f"rrf_list_{slot}"]
                elif method == "Weighted Consensus":
                    grouped[f"score_list_{slot}"] = grouped[f"zscore_list_{slot}"] * weights[slot]
                else:
                    grouped[f"score_list_{slot}"] = grouped[f"zscore_list_{slot}"]

                grouped = grouped.rename(columns={
                    value_col: f"original_value_list_{slot}",
                    id_col: id_col_name,
                })

                processed_frames[slot] = grouped.copy()

                if merged is None:
                    merged = grouped
                else:
                    merged = merged.merge(grouped, on=id_col_name, how="inner")

            if merged is None or merged.empty:
                QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma),
                    f"No shared compounds were found across the {selected_count} selected dataframes."
                )
                return

            score_cols = [f"score_list_{slot}" for slot in selected_slots]
            rank_cols = [f"rank_list_{slot}" for slot in selected_slots]
            raw_cols = [f"original_value_list_{slot}" for slot in selected_slots]

            merged["consensus_score_sum"] = merged[score_cols].sum(axis=1)
            if method == "Weighted Consensus":
                weight_sum = sum(weights[slot] for slot in selected_slots) or float(selected_count)
                merged["consensus_score_mean"] = merged["consensus_score_sum"] / weight_sum
            else:
                merged["consensus_score_mean"] = merged[score_cols].mean(axis=1)

            if method == "Rank Sum / Borda count":
                score_ascending = True   # lower average rank = better; direction already applied per-list
            elif method == "Reciprocal Rank Fusion (RRF)":
                score_ascending = False  # higher RRF score = better
            else:
                score_ascending = rank_ascending

            merged["consensus_rank"] = merged["consensus_score_mean"].rank(method="min", ascending=score_ascending).astype(int)
            merged["median_rank_validation"] = merged[rank_cols].median(axis=1)
            merged["bioactivity_mean"] = merged[raw_cols].mean(axis=1)
            merged["bioactivity_sd"] = merged[raw_cols].std(axis=1, ddof=1).fillna(0.0)
            merged["bioactivity_cv_percent"] = np.where(
                merged["bioactivity_mean"].abs() > 0,
                (merged["bioactivity_sd"] / merged["bioactivity_mean"].abs()) * 100.0,
                np.nan,
            )
            merged["bioactivity_mean_sd"] = merged.apply(
                lambda series: f"{series['bioactivity_mean']:.6g} +/- {series['bioactivity_sd']:.6g}",
                axis=1
            )

            merged = merged.sort_values(
                by=["consensus_score_mean", "median_rank_validation", id_col_name],
                ascending=[score_ascending, True, True]
            ).reset_index(drop=True)

            final_columns = [
                id_col_name,
                "consensus_rank",
                "consensus_score_mean",
                "consensus_score_sum",
                "median_rank_validation",
                "bioactivity_mean",
                "bioactivity_sd",
                "bioactivity_cv_percent",
                "bioactivity_mean_sd",
            ] + raw_cols + score_cols + rank_cols
            consensus_df = merged[final_columns].copy()

            # ---- CV% / Hit% filter -> the authoritative "hits" table the final report reads ----
            cv_text = self.ed_consensus_cv_max.text().strip() if hasattr(self, "ed_consensus_cv_max") else ""
            hit_text = self.ed_consensus_hit_percent.text().strip() if hasattr(self, "ed_consensus_hit_percent") else ""
            try:
                cv_max = float(cv_text) if cv_text else None
            except ValueError:
                cv_max = None
            try:
                hit_percent = float(hit_text) if hit_text else None
            except ValueError:
                hit_percent = None

            eligible = consensus_df.copy()
            if cv_max is not None:
                eligible = eligible[eligible["bioactivity_cv_percent"].abs() <= cv_max]
            total_rows = len(consensus_df)
            if hit_percent is not None and total_rows:
                hit_count = max(1, int(round(total_rows * hit_percent / 100.0)))
            else:
                hit_count = len(eligible)
            hits_df = eligible.sort_values("consensus_rank").head(hit_count).reset_index(drop=True)

            target_chembl_id = self.ed_target_chembl_id.text().strip() if hasattr(self, "ed_target_chembl_id") else ""
            target_organism = self.ed_organism_name.text().strip() if hasattr(self, "ed_organism_name") else ""
            suffix_parts = [part for part in [target_chembl_id, target_organism] if part]
            suffix = "_".join(suffix_parts) if suffix_parts else datetime.now().strftime("%Y%m%d_%H%M%S")
            out_dir = self._ensure_rank_results_dir()
            out_path = os.path.join(out_dir, f"df_consensus_analysis_{suffix}_{selected_count}modelos.csv")
            hits_path = os.path.join(out_dir, f"df_consensus_hits_{suffix}_{selected_count}modelos.csv")

            pair_lines = []
            for left_index, left in enumerate(selected_slots):
                for right in selected_slots[left_index + 1:]:
                    pair_df = processed_frames[left][[id_col_name, f"original_value_list_{left}"]].merge(
                    processed_frames[right][[id_col_name, f"original_value_list_{right}"]],
                    on=id_col_name,
                    how="inner"
                    ).dropna()
                    if len(pair_df) < 2:
                        pair_lines.append(
                            f"List {left} vs List {right}: insufficient shared compounds for Spearman correlation (n={len(pair_df)})."
                        )
                        continue
                    rho, pval = stats.spearmanr(
                        pair_df[f"original_value_list_{left}"],
                        pair_df[f"original_value_list_{right}"],
                        nan_policy="omit"
                    )
                    pair_lines.append(
                        f"List {left} vs List {right}: rho = {rho:.4f}, p-value = {pval:.4g}, shared compounds = {len(pair_df)}"
                    )

            report_lines = [
                "Consensus Analysis Report",
                "=" * 40,
                f"ID column: {id_col_name}",
                f"Value column: {value_col_label}",
                f"Selected dataframes: {selected_count}",
                f"Consensus method: {method}",
                f"Ranking direction: {'Increase (lower to higher)' if rank_ascending else 'Decrease (higher to lower)'}",
                f"Input compounds shared across all selected lists: {len(consensus_df)}",
                f"Max CV% filter: {cv_max if cv_max is not None else 'none'}",
                f"Top Hits %: {hit_percent if hit_percent is not None else 'none (all eligible compounds)'}",
                f"Hits produced: {len(hits_df)}",
                "",
                "Consensus methodology:",
                f"1. Per-list score computed using the {method} method.",
                f"2. Consensus score computed from the mean and sum of the {selected_count} selected list scores.",
                "3. Final ranking sorted by consensus score mean, using median rank as validation.",
                "4. Original bioactivity summarized as mean +/- SD for each shared compound.",
                "5. Coefficient of variation reported as CV% = (SD / abs(mean)) x 100.",
                "6. Pairwise concordance evaluated with Spearman rank correlation.",
                "",
                "Top hits (up to 20 shown):",
            ]

            for _, series in hits_df.head(20).iterrows():
                report_lines.append(
                    f"Rank {int(round(series['consensus_rank']))}: {series[id_col_name]} | score-mean = {series['consensus_score_mean']:.4f} | "
                    f"median-rank = {series['median_rank_validation']:.2f} | mean +/- SD = {series['bioactivity_mean']:.6g} +/- {series['bioactivity_sd']:.6g} | "
                    f"CV% = {series['bioactivity_cv_percent']:.2f}"
                )

            report_lines.extend(["", "Pairwise Spearman concordance:"])
            report_lines.extend(pair_lines)
            report_lines.extend(["", f"Full result saved to: {out_path}", f"Hits saved to: {hits_path}"])

            self.df_selecionado = consensus_df.copy()
            self._next_dataframe_save_path = out_path
            try:
                os.makedirs(os.path.dirname(out_path), exist_ok=True)
                consensus_df.to_csv(out_path, index=False)
                hits_df.to_csv(hits_path, index=False)
            except OSError:
                pass
            self._step8_last_result_file = out_path
            self._step8_last_hits_file = hits_path
            self._save_step8_state()
            self.show_dataframe(consensus_df)
            self.show_output(report_lines, "Consensus Analysis Report")
            QMessageBox.information(self, i18n.t("msg_title_success", self._idioma), "Consensus analysis completed.")

        except Exception as e:
            QMessageBox.critical(self, i18n.t("msg_title_error", self._idioma), f"An error occurred during consensus analysis:\n{e}")

    def generate_final_report(self) -> None:
        """STEP 6 'Generate Final Report' button: builds <job_name>_REPORT_<timestamp>.docx under the
        job's RESULTS folder from the unified per-job JSON (job_dir/<job_name>.json) plus the
        result files each STEP has written to disk so far. Mirrors CODOC's STEP 5 handler of
        the same name (CODOC.py, generate_final_report)."""
        job_dir = getattr(self, "job_dir", "")
        if not job_dir:
            QMessageBox.warning(self, i18n.t("msg_title_generate_final_report", self._idioma), "Set a run folder first (CONFIG tab).")
            return

        job_name = os.path.basename(os.path.normpath(job_dir))
        state = self._load_job_state(job_dir)
        if not state:
            QMessageBox.warning(self, i18n.t("msg_title_generate_final_report", self._idioma),
                "No recorded state was found for this job yet. Run at least one STEP "
                "(Generate Base Dataset, Outlier Elimination, Compute AD, Consensus Generate, "
                "etc.) before generating the final report."
            )
            return

        QApplication.setOverrideCursor(Qt.WaitCursor)
        try:
            output_path = _generate_final_report_docx(
                job_dir=job_dir, job_name=job_name, state=state,
                idioma=self._idioma, app_dir=self.dp_dir,
            )
        except Exception as e:
            QApplication.restoreOverrideCursor()
            QMessageBox.critical(self, i18n.t("msg_title_generate_final_report", self._idioma), f"Failed to generate the final report:\n{e}")
            return
        QApplication.restoreOverrideCursor()
        QMessageBox.information(self, i18n.t("msg_title_generate_final_report", self._idioma), f"Final report saved to:\n{output_path}")

    def _compute_rdkit_fp_single_mode(self, mode, structure_col, name_col, fp_bits=2048, fp_chirality=True):
        
        
        from rdkit import Chem
        from rdkit.Chem import rdMolDescriptors

        def _molf(s):
            try:
                return Chem.MolFromSmiles(str(s)) if pd.notna(s) else None
            except Exception:
                return None

        @lru_cache(maxsize=16)
        def _get_morgan_gen(radius: int, n_bits: int, include_chirality: bool, use_features: bool):
            """
            Compatível com RDKit antigo: em vez de 'useFeatures', usamos o gerador de invariantes apropriado.
            """
            atom_inv_gen = rfg.GetMorganFeatureAtomInvGen() if use_features else rfg.GetMorganAtomInvGen()
            return rfg.GetMorganGenerator(
                radius=radius,
                includeChirality=include_chirality,
                useBondTypes=True,
                fpSize=n_bits,
                atomInvariantsGenerator=atom_inv_gen
                # (demais parâmetros ficam nos defaults: countSimulation=False etc.)
            )

        def _ecfp4_bits(m):
            """ECFP4 (raio=2) como vetor binário 0/1."""
            if m is None:
                return np.zeros(fp_bits, dtype=np.int8)
            gen = _get_morgan_gen(2, fp_bits, bool(fp_chirality), use_features=False)
            bv = gen.GetFingerprint(m)  # ExplicitBitVect
            arr = np.zeros((fp_bits,), dtype=np.int8)
            DataStructs.ConvertToNumpyArray(bv, arr)
            return arr

        def _fcfp6_bits(m):
            """FCFP6 (raio=3, feature-based) como vetor binário 0/1."""
            if m is None:
                return np.zeros(fp_bits, dtype=np.int8)
            gen = _get_morgan_gen(3, fp_bits, bool(fp_chirality), use_features=True)
            bv = gen.GetFingerprint(m)
            arr = np.zeros((fp_bits,), dtype=np.int8)
            DataStructs.ConvertToNumpyArray(bv, arr)
            return arr

        def _ecfp4_count(m):
            """ECFP4 counting (raio=2) como vetor de contagens (ints)."""
            if m is None:
                return np.zeros(fp_bits, dtype=np.int32)
            gen = _get_morgan_gen(2, fp_bits, bool(fp_chirality), use_features=False)
            sv = gen.GetCountFingerprint(m)  # SparseIntVect
            arr = np.zeros((fp_bits,), dtype=np.int32)
            for idx, cnt in sv.GetNonzeroElements().items():
                arr[int(idx)] = int(cnt)      # índices já dentro de [0, fp_bits]
            return arr

        df = self.df_selecionado.dropna(subset=[structure_col]).copy()
        names = df[name_col].astype(str).tolist()
        mols  = [ _molf(s) for s in df[structure_col].astype(str).tolist() ]

        rows = []
        if mode == "ECFP4 (RDkit clsssic)":
            rows = [_ecfp4_bits(m) for m in mols]
            cols = [f"ECFP4_{i}" for i in range(fp_bits)]
        elif mode == "FCFP6 (RDkit)":
            rows = [_fcfp6_bits(m) for m in mols]
            cols = [f"FCFP6_{i}" for i in range(fp_bits)]
        else:  # counting
            rows = [_ecfp4_count(m) for m in mols]
            cols = [f"ECFP4_count_{i}" for i in range(fp_bits)]

        arr = np.vstack(rows)
        df_fp = pd.DataFrame(arr, columns=cols)
        df_fp.insert(0, "Name", names)  # 'Name' para casar com o merge posterior
        return df_fp

    def _set_items(self, combo, items):
        combo.blockSignals(True)
        combo.clear()
        # remove duplicates preserving order
        seen = set()
        unique = [x for x in items if not (x in seen or seen.add(x))]
        combo.addItems(unique if unique else ["(no recommendation)"])
        combo.setCurrentIndex(0)
        combo.blockSignals(False)

    def _selected(self, combo):
        txt = combo.currentText().strip()
        return txt if txt else None

    def update_recommendations(self):
        feat = (self._selected(self.cb_features_types) or "").lower()          # "continuous numeric", "binary", "categorical", "ordinal"
        attr = (self._selected(self.cb_attribute_options) or "").lower()       # "noisy/outliers", "dense", "sparse", "low cardinality", "high cardinality", "high correlation", "non-linear relationship"
        model = (self._selected(self.cb_model_types) or "").lower()            # e.g., "linear/glm", "tree-based", "svm", "knn", "neural network", "naive bayes", "clustering", etc.

        # ---------- Start with sane defaults ----------
        rec_scale = []
        rec_select = []
        rec_proj = []

        # ---------- Feature-type driven rules ----------
        if "continuous" in feat:
            rec_scale += ["StandardScaler", "MinMaxScaler"]
            # handle skew
            rec_scale += ["RobustScaler", "Q.Transformer(Norm)", "PowerTransformer(Yeo-Johnson)"]
            rec_select += ["Variance Threshold", "Lasso (L1)", "Elastic Net", "Mutual Information", "RFE"]
            rec_proj   += ["PCA", "UMAP", "Kernel PCA"]
        elif "binary" in feat:
            # scaling often unnecessary; normalizer helpful for distance-based models
            rec_scale += ["Normalizer(L1/L2 norm)"]
            rec_select += ["Variance Threshold", "Mutual Information", "Tree-based Importance (RandomForest)"]
            rec_proj   += ["UMAP", "t-SNE", "Isomap"]
        elif "categorical" in feat:
            rec_scale += ["OneHotEncoder(Cat)"]
            # high-cardinality handling will be added below if flagged
            rec_select += ["SelectKBest (Chi2)", "Mutual Information", "Tree-based Importance (RandomForest)", "SelectKBest (Chi2)"]
            rec_proj   += ["UMAP"]
        elif "ordinal" in feat:
            rec_scale += ["OrdinalEncoder(Cat)", "StandardScaler"]
            rec_select += ["Mutual Information", "RFE", "Tree-based Importance (RandomForest)"]
            rec_proj   += ["PCA", "UMAP"]

        # ---------- Attribute-options driven rules ----------
        if "noisy" in attr or "outlier" in attr:
            rec_scale = ["RobustScaler", "Q.Transformer(Uniform)", "Q.Transformer(Norm)"] + rec_scale
            rec_select += ["Variance Threshold", "Lasso (L1)"]
            rec_proj   += ["PCA"]  # PCA often helps denoise

        if "sparse" in attr:
            # avoid centering -> MaxAbsScaler/Normalizer; for cat high-dim keep OHE sparse matrices intact
            rec_scale = ["MaxAbsScaler", "Normalizer(L1/L2 norm)"] + [x for x in rec_scale if x not in ("StandardScaler", "MinMaxScaler")]
            rec_select += ["Variance Threshold", "SelectPercentile", "Mutual Information"]
            rec_proj   = ["TruncatedSVD"] + rec_proj

        if "dense" in attr:
            # OK for standard scalers and PCA
            pass

        if "low cardinal" in attr:
            # standard OHE ok
            pass

        if "high cardinal" in attr:
            rec_scale = ["BinaryEncoder", "OneHotEncoder(Cat)"] + rec_scale
            rec_select += ["Mutual Information", "Tree-based Importance (RandomForest)"]
            rec_proj   += ["UMAP"]

        if "correlation" in attr or "colline" in attr:
            rec_select = ["Correlation Threshold", "Lasso (L1)", "Elastic Net"] + rec_select
            rec_proj   = ["PCA"] + rec_proj

        if "non-linear" in attr or "nonlinear" in attr or "non linear" in attr:
            # relações não-lineares: métodos lineares de seleção/projeção (correlação,
            # Lasso/Ridge, PCA/LDA/SVD puros) capturam mal essa estrutura.
            rec_select = ["Mutual Information", "RFE", "Tree-based Importance (RandomForest)"] + rec_select
            rec_proj   = ["Kernel PCA", "UMAP", "t-SNE", "Isomap"] + rec_proj

        # ---------- Model-type driven rules ----------
        if "linear" in model or "glm" in model or "logistic" in model or "linear regression" in model:
            rec_scale = ["StandardScaler", "MinMaxScaler", "RobustScaler"] + rec_scale
            rec_select = ["Stepwise AIC", "Stepwise BIC", "Lasso (L1)", "Elastic Net", "Ridge (L2)", "Correlation Threshold"] + rec_select
            rec_proj   = ["PCA"] + rec_proj

        if "svm" in model:
            rec_scale = ["StandardScaler", "MinMaxScaler"] + rec_scale
            rec_select = ["RFE", "SFS (Forward)"] + rec_select
            rec_proj   = ["Kernel PCA", "PCA"] + rec_proj

        if "knn" in model or "distance" in model:
            rec_scale = ["StandardScaler", "MinMaxScaler", "Normalizer(L1/L2 norm)"] + rec_scale
            rec_select = ["Mutual Information", "SelectKBest (ANOVA F-test)"] + rec_select
            rec_proj   = ["UMAP", "PCA"] + rec_proj

        if "tree" in model or "random forest" in model or "xgboost" in model or "gradient" in model or "boost" in model:
            # trees are largely scale-insensitive, so no scaling-method addition here
            # (an earlier version injected a "(no scaling required for tree-based)"
            # placeholder string into this combobox, which isn't a real method - picking
            # it and clicking "Run Scaling" would fail).
            rec_select = ["Tree-based Importance (RandomForest)", "GB Importance"] + rec_select
            rec_proj   = ["PCA", "UMAP"] + rec_proj

        if "neural" in model or "mlp" in model or "deep" in model:
            rec_scale = ["StandardScaler", "MinMaxScaler"] + rec_scale
            rec_select = ["Mutual Information", "Variance Threshold"] + rec_select
            rec_proj   = ["UMAP", "PCA"] + rec_proj

        if "naive bayes" in model:
            # GaussianNB benefits from scaling; MultinomialNB expects counts/non-negative
            rec_scale = ["StandardScaler", "MinMaxScaler"] + rec_scale
            rec_select = ["Mutual Information", "SelectKBest (Chi2)"] + rec_select
            rec_proj   = ["PCA"] + rec_proj

        if "clustering" in model or "k-means" in model or "kmeans" in model:
            # k-Means/clustering são distance-based: escala é essencial, features quase
            # constantes atrapalham as distâncias, e projeção ajuda tanto a "curse of
            # dimensionality" quanto a visualização dos clusters.
            rec_scale = ["StandardScaler", "MinMaxScaler"] + rec_scale
            rec_select = ["Variance Threshold", "Correlation Threshold"] + rec_select
            rec_proj   = ["PCA", "UMAP"] + rec_proj

        # ---------- Final polishing: fallbacks if empty ----------
        if not rec_scale:
            rec_scale = ["StandardScaler"] if "continuous" in feat else ["OneHotEncoder(Cat)"]

        if not rec_select:
            rec_select = ["Variance Threshold", "Mutual Information"]

        if not rec_proj:
            rec_proj = ["PCA", "UMAP"]

        # ---------- Apply to combos ----------
        self._set_items(self.cb_recommended_scaling, rec_scale)
        self._set_items(self.cb_recommended_selection, rec_select)
        self._set_items(self.cb_recommended_projection, rec_proj)

        # (Optional) tooltips for quick guidance
        self.cb_recommended_scaling.setToolTip("Recommended scaling/encoding based on feature type, data attributes, and target model.")
        self.cb_recommended_selection.setToolTip("Recommended feature selection methods matching your data/model constraints.")
        self.cb_recommended_projection.setToolTip("Recommended dimensionality reduction (projection) methods.")

