            # Escala inversa/direta: mutuamente exclusivas, e atualizam o operador padrão de
            # Class 1/Class 3 (o usuário ainda pode trocar manualmente depois).
            def _cat_update_class_operators():
                if self.chk_cat_direct_scale.isChecked():
                    self._set_combo_text(self.cb_class1_op, ">")
                    self._set_combo_text(self.cb_class3_op, "<")
                elif self.chk_cat_inverse_scale.isChecked():
                    self._set_combo_text(self.cb_class1_op, "<")
                    self._set_combo_text(self.cb_class3_op, ">")

            def _on_cat_inverse_scale_changed(state):
                if state == Qt.Checked:
                    self.chk_cat_direct_scale.setChecked(False)
                _cat_update_class_operators()

            def _on_cat_direct_scale_changed(state):
                if state == Qt.Checked:
                    self.chk_cat_inverse_scale.setChecked(False)
                _cat_update_class_operators()

            def _on_cat_column_changed(_text=None):
                scale = self._cat_infer_scale(self.list_columns_cat.currentText())
                if scale == "inverse":
                    self.chk_cat_inverse_scale.setChecked(True)
                elif scale == "direct":
                    self.chk_cat_direct_scale.setChecked(True)

            self.chk_cat_inverse_scale.stateChanged.connect(_on_cat_inverse_scale_changed)
            self.chk_cat_direct_scale.stateChanged.connect(_on_cat_direct_scale_changed)
            self.list_columns_cat.currentTextChanged.connect(_on_cat_column_changed)

