    def _fit_window_to_content(self):
        """
        Dimensiona a janela principal, uma vez, logo após montar a interface, para caber
        por inteiro o conteúdo da aba mais larga e da aba mais alta — usando como referência
        o sizeHint() do widget "de dentro" do QScrollArea de cada aba (não o
        minimumSizeHint(), que é propositalmente pequeno por causa do próprio QScrollArea;
        ver correção do encaixe nas bordas da tela). Isso faz a janela abrir grande o
        suficiente para mostrar qualquer aba (ex.: STEP 2) sem scroll, com o tamanho em
        pixels acompanhando a resolução da tela — mas nunca maior que a área útil dela. Se o
        conteúdo não couber mesmo assim (tela pequena demais para o conjunto de abas), a aba
        correspondente volta a exibir scroll normalmente, como reserva.
        """
        screen = QGuiApplication.primaryScreen()
        if screen is None or not self._tab_content_widgets:
            return

        available = screen.availableGeometry()
        # Largura: sizeHint() (tamanho "natural"/confortável do conteúdo) — a janela abre
        # com a largura da aba mais larga, sem sobras.
        max_width = max(w.sizeHint().width() for w in self._tab_content_widgets)
        # Altura: minimumSizeHint() (não sizeHint()) — graças ao stretch já aplicado em
        # algumas abas (STEP 2 "Select columns of interest", STEP 4 Models/Status), o
        # conteúdo comprime sem precisar de scroll bem abaixo do seu tamanho "preferido".
        # Usar sizeHint() aqui abria a janela ~100-150px mais alta do que o necessário.
        max_height = max(w.minimumSizeHint().height() for w in self._tab_content_widgets)

        # Margem para a barra de abas e bordas — evita que uma barra de rolagem
        # apareça só por causa de poucos pixels de folga.
        tab_bar = self.tabs.tabBar()
        extra_height = (tab_bar.sizeHint().height() if tab_bar else 0) + 45
        extra_width = 60

        target_width = min(available.width(), max_width + extra_width)
        target_height = min(available.height(), max_height + extra_height)

        self.resize(target_width, target_height)
        self.move(
            available.x() + (available.width() - self.width()) // 2,
            available.y() + (available.height() - self.height()) // 2,
        )

    # ==========================================================================================================================================
    # ============================ STEP 6 (SCIKIT-LEARN): SCREENING, TUNING, EVALUATE, SAVE/PREDICT, PLOT =====================================
    # ==========================================================================================================================================

    def _get_skl_registry(self):
        task = (getattr(self, "task_type", None) or "").strip().lower()
        if task.startswith("class"):
            return SKL_CLASSIFIERS, "classification"
        if task.startswith("clust"):
            return SKL_CLUSTERERS, "clustering"
        if task.startswith("reg"):
            return SKL_REGRESSORS, "regression"
        return {}, ""

    def _skl_resolve_base_model_name(self, display_name):
        """Resolve o nome de exibição de um modelo (ex.: 'RandomForestRegressor', uma variante
        otimizada 'RandomForestRegressor_1' ou um nome derivado de um modelo carregado via Load) para
        o nome da classe correspondente no registry (usado para obter a classe/kwargs padrão e a
        grade de hiperparâmetros na hora de rodar um novo Tuning). Retorna None se não for possível
        resolver para nenhuma classe conhecida do registry atual."""
        display_name = (display_name or "").strip()
        if not display_name:
            return None
        registry, _task = self._get_skl_registry()
        if display_name in registry:
            return display_name
        model_obj = getattr(self, "skl_trained_models", {}).get(display_name)
        if model_obj is not None:
            cls_name = type(model_obj).__name__
            if cls_name in registry:
                return cls_name
        base = re.sub(r"_\d+$", "", display_name)
        if base in registry:
            return base
        return None

    def _add_skl_tuned_model_variant(self, base_name, model):
        """Registra uma nova versão otimizada de 'base_name' (ex.: 'RandomForestRegressor_1') em
        self.skl_trained_models, sem sobrescrever a versão original nem outras variantes já geradas,
        permitindo ao usuário escolher depois qual versão salvar."""
        if not hasattr(self, "skl_trained_models") or self.skl_trained_models is None:
            self.skl_trained_models = {}
        n = 1
        while f"{base_name}_{n}" in self.skl_trained_models:
            n += 1
        new_name = f"{base_name}_{n}"
        self.skl_trained_models[new_name] = model
        return new_name

    def _refresh_skl_model_combo(self, select=None, preserve_order=False):
        """Repopula o único combobox 'Model' (cb_skl_tune_model, no grupo Hyperparameter Tuning) com
        os modelos disponíveis em self.skl_trained_models — usado como referência única por Tuning,
        Validation, Remove Model and Predict e Performance Charts.

        preserve_order=False (padrão): reconstrói a lista do zero na ordem de
        self.skl_trained_models - correto ao carregar uma USI salva, cujo dict acabou de ser
        recriado na ordem persistida (ranking + variantes otimizadas, nessa ordem).

        preserve_order=True: mantém a ordem já exibida no combobox (o ranking melhor->pior
        definido uma única vez em _on_skl_screening_finished) e só ACRESCENTA ao final os
        modelos que ainda não estavam na lista. Usado por Run Tuning ao registrar uma nova
        variante otimizada (ex. "BaggingRegressor_1") - sem isso, um rebuild do zero a
        partir do dict (cuja ordem de chaves não é o ranking) descartava o ranking e a lista
        "voltava" para a ordem em que os modelos foram treinados/inseridos no dict."""
        if not hasattr(self, "cb_skl_tune_model"):
            return
        available = list(getattr(self, "skl_trained_models", {}) or {})
        if preserve_order:
            current_order = [self.cb_skl_tune_model.itemText(i) for i in range(self.cb_skl_tune_model.count())]
            names = [n for n in current_order if n in available] + [n for n in available if n not in current_order]
        else:
            names = available
        self.cb_skl_tune_model.blockSignals(True)
        self.cb_skl_tune_model.clear()
        self.cb_skl_tune_model.addItems(names)
        if select and select in names:
            self.cb_skl_tune_model.setCurrentText(select)
        self.cb_skl_tune_model.blockSignals(False)
        self._refresh_skl_hyperparam_table(self.cb_skl_tune_model.currentText())
        self._refresh_skl_tune_param_options(self.cb_skl_tune_model.currentText())
        self._refresh_skl_model_settings_widgets(self.cb_skl_tune_model.currentText())

        # Lista de seleção múltipla "Remove Model" (grupo Remove Model and Predict) — sempre a mesma
        # lista/ordem exibida no combobox "Model" acima.
        if hasattr(self, "list_skl_saved_models"):
            self.list_skl_saved_models.blockSignals(True)
            self.list_skl_saved_models.clear()
            self.list_skl_saved_models.addItems(names)
            self.list_skl_saved_models.blockSignals(False)

    def _get_skl_random_state(self):
        try:
            return int(self.ed_skl_random_state.text().strip())
        except Exception:
            return 123

    def _get_current_sklearn_usi(self, fallback="LOAD"):
        raw = ""
        if hasattr(self, "ed_skl_USI") and self.ed_skl_USI is not None:
            try:
                raw = self.ed_skl_USI.currentText().strip()
            except Exception:
                raw = ""
        if not raw:
            raw = str(getattr(self, "skl_usi_key", "") or "").strip()
        return _normalize_usi_key(raw or fallback)

    def _set_current_sklearn_usi_context(self, usi_key=None):
        current_usi = _normalize_usi_key(usi_key or self._get_current_sklearn_usi())
        paths = _ensure_sklearn_usi_dirs(self.job_dir, current_usi)
        self.skl_usi_key = current_usi
        self.skl_base_path = paths["base"]
        self.skl_plot_path = paths["midia"]
        self.skl_out_data = paths["data"]
        self.skl_models_path = paths["models"]
        self.skl_predictions_path = paths["predictions"]

        if hasattr(self, "ed_skl_USI") and self.ed_skl_USI.currentText().strip() != current_usi:
            self.ed_skl_USI.blockSignals(True)
            self.ed_skl_USI.setCurrentText(current_usi)
            self.ed_skl_USI.blockSignals(False)

        self._refresh_skl_usi_combo()

        return paths

    def _refresh_skl_usi_combo(self):
        """Repopula o dropdown do combobox USI com os códigos existentes em RESULTS/USI/ que possuem
        uma sessão STEP 5 (marcados pela presença de skl_session.json na própria pasta da USI),
        preservando o texto atualmente exibido/digitado."""
        if not hasattr(self, "ed_skl_USI") or self.ed_skl_USI is None:
            return
        job_dir = getattr(self, "job_dir", None)
        if not job_dir:
            return
        usi_root = os.path.join(job_dir, "RESULTS", "USI")
        try:
            codes = sorted(
                d for d in os.listdir(usi_root)
                if os.path.isfile(os.path.join(usi_root, d, "skl_session.json"))
            )
        except Exception:
            codes = []

        existing_items = [self.ed_skl_USI.itemText(i) for i in range(self.ed_skl_USI.count())]
        if codes == existing_items:
            return

        current_text = self.ed_skl_USI.currentText()
        self.ed_skl_USI.blockSignals(True)
        self.ed_skl_USI.clear()
        self.ed_skl_USI.addItems(codes)
        self.ed_skl_USI.setCurrentText(current_text)
        self.ed_skl_USI.blockSignals(False)

    def _skl_session_config_path(self):
        base_path = getattr(self, "skl_base_path", None)
        if not base_path:
            return None
        return os.path.join(base_path, "skl_session.json")

    def _skl_train_test_data_path(self):
        data_path = getattr(self, "skl_out_data", None)
        if not data_path:
            return None
        return os.path.join(data_path, "skl_train_test_split.joblib")

    def _save_skl_model_to_models_dir(self, name, model):
        """Salva automaticamente uma cópia estável (sem timestamp) de 'model' em
        RESULTS/USI/<usi_key>/MODELS/<name>.joblib, para que o combobox USI consiga recarregar essa
        versão depois, sem depender de o usuário ter clicado manualmente em Save Model."""
        models_path = getattr(self, "skl_models_path", None)
        if not models_path:
            return
        try:
            joblib.dump(model, os.path.join(models_path, f"{name}.joblib"))
        except Exception:
            pass

    def _save_skl_train_test_data(self):
        path = self._skl_train_test_data_path()
        if not path:
            return
        try:
            joblib.dump({
                "x": getattr(self, "skl_x", None), "y": getattr(self, "skl_y", None),
                "x_train": getattr(self, "skl_x_train", None), "x_test": getattr(self, "skl_x_test", None),
                "y_train": getattr(self, "skl_y_train", None), "y_test": getattr(self, "skl_y_test", None),
            }, path)
        except Exception:
            pass

    def _load_skl_train_test_data(self):
        path = self._skl_train_test_data_path()
        if not path or not os.path.isfile(path):
            return False
        try:
            data = joblib.load(path)
        except Exception:
            return False
        self.skl_x = data.get("x")
        self.skl_y = data.get("y")
        self.skl_x_train = data.get("x_train")
        self.skl_x_test = data.get("x_test")
        self.skl_y_train = data.get("y_train")
        self.skl_y_test = data.get("y_test")
        return True

    def _save_skl_session_config(self):
        """Grava/atualiza RESULTS/USI/<usi_key>/skl_session.json com as informações necessárias para
        repopular o combobox 'Model' único (Hyperparameter Tuning), os campos de configuração do
        Screening (Sort metric/X range/Y column/Test Size) e, por modelo, as grades de hiperparâmetros
        e demais campos dos grupos Hyperparameter Tuning/Validation usados no Tuning/Cross-Validation
        de cada um — tudo o que é preciso para essa USI ser recarregada por completo."""
        config_path = self._skl_session_config_path()
        if not config_path:
            return
        _registry, task = self._get_skl_registry()
        # A ordem salva deve ser a ordem exibida no combobox "Model" (melhor -> pior, com variantes
        # tunadas anexadas ao final) e não a ordem de inserção de self.skl_trained_models — essa dict
        # segue a ordem de treino/tuning, não o ranking, e usá-la aqui reverteria a USI recarregada
        # para uma ordem não-ranqueada.
        if hasattr(self, "cb_skl_tune_model") and self.cb_skl_tune_model.count() > 0:
            model_order = [self.cb_skl_tune_model.itemText(i) for i in range(self.cb_skl_tune_model.count())]
        else:
            model_order = list(getattr(self, "skl_trained_models", {}) or {})
        config = {
            "task": task,
            "random_state": self._get_skl_random_state(),
            "models": model_order,
            "best_model": getattr(self, "skl_screening_best_model_name", None),
            "current_model": getattr(self, "skl_current_model_name", None),
            "tuned_param_grids": getattr(self, "_skl_tuned_param_grids", {}) or {},
            "tuning_settings": getattr(self, "_skl_tuning_settings", {}) or {},
            "validation_settings": getattr(self, "_skl_validation_settings", {}) or {},
            "screening_settings": {
                "sort_metric": self.cb_skl_metric.currentText() if hasattr(self, "cb_skl_metric") else "",
                "x_first_col": self.ed_skl_x_first_col.text() if hasattr(self, "ed_skl_x_first_col") else "",
                "x_last_col": self.ed_skl_x_last_col.text() if hasattr(self, "ed_skl_x_last_col") else "",
                "y_column": self.cb_skl_y.currentText() if hasattr(self, "cb_skl_y") else "",
                "test_size": self.dsp_skl_test_size.value() if hasattr(self, "dsp_skl_test_size") else None,
            },
            "updated": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        }
        try:
            with open(config_path, "w", encoding="utf-8") as fh:
                json.dump(config, fh, indent=2, ensure_ascii=False)
        except Exception:
            pass

    def _on_skl_usi_selected(self, index):
        """Carrega automaticamente uma corrida anterior da STEP 6 quando o usuário seleciona um
        código existente no combobox USI: modelos treinados, dados de treino/teste (para Performance
        Charts), os campos de Screening (Sort metric/X range/Y column/Test Size) e, por modelo, as
        grades de hiperparâmetros e os demais campos de Hyperparameter Tuning/Validation usados no
        Tuning/Cross-Validation de cada um."""
        code = self.ed_skl_USI.itemText(index) if index >= 0 else self.ed_skl_USI.currentText()
        code = (code or "").strip()
        if not code:
            return

        self._set_current_sklearn_usi_context(code)
        config_path = self._skl_session_config_path()
        if not config_path or not os.path.isfile(config_path):
            return

        try:
            with open(config_path, "r", encoding="utf-8") as fh:
                config = json.load(fh)
        except Exception as e:
            QMessageBox.warning(self, i18n.t("msg_title_usi", self._idioma), f"Could not read the session file for USI '{code}':\n{e}")
            return

        _registry, current_task = self._get_skl_registry()
        saved_task = config.get("task")
        if saved_task and current_task and saved_task != current_task:
            QMessageBox.warning(self, i18n.t("msg_title_usi", self._idioma),
                f"USI '{code}' was saved as '{saved_task}', but the current Task Type "
                f"(CONFIG tab) is '{current_task}'. Loading it anyway, but Tuning/Evaluate may not "
                "behave correctly until the Task Type matches."
            )

        self.skl_trained_models = {}
        for name in config.get("models", []):
            model_path = os.path.join(self.skl_models_path, f"{name}.joblib")
            if os.path.isfile(model_path):
                try:
                    self.skl_trained_models[name] = joblib.load(model_path)
                except Exception:
                    continue

        self._load_skl_train_test_data()
        self._skl_tuned_param_grids = config.get("tuned_param_grids", {}) or {}
        # Precisam estar prontos ANTES de _refresh_skl_model_combo() abaixo, que já dispara
        # _refresh_skl_model_settings_widgets() para o modelo selecionado.
        self._skl_tuning_settings = config.get("tuning_settings", {}) or {}
        self._skl_validation_settings = config.get("validation_settings", {}) or {}

        # Campos de configuração do Screening (Sort metric, X range, Y column, Test Size) — não são
        # por modelo, valem para a USI inteira.
        screening_settings = config.get("screening_settings", {}) or {}
        if hasattr(self, "cb_skl_metric") and screening_settings.get("sort_metric"):
            idx = self.cb_skl_metric.findText(screening_settings["sort_metric"])
            if idx != -1:
                self.cb_skl_metric.setCurrentIndex(idx)
        if hasattr(self, "ed_skl_x_first_col") and screening_settings.get("x_first_col", "") != "":
            self.ed_skl_x_first_col.setText(str(screening_settings["x_first_col"]))
        if hasattr(self, "ed_skl_x_last_col") and screening_settings.get("x_last_col", "") != "":
            self.ed_skl_x_last_col.setText(str(screening_settings["x_last_col"]))
        if hasattr(self, "cb_skl_y") and screening_settings.get("y_column"):
            self.cb_skl_y.setCurrentText(screening_settings["y_column"])
        if hasattr(self, "dsp_skl_test_size") and screening_settings.get("test_size") is not None:
            self.dsp_skl_test_size.setValue(float(screening_settings["test_size"]))

        names = list(self.skl_trained_models)
        select_name = config.get("current_model") or config.get("best_model")
        if select_name not in names and names:
            select_name = names[0]

        self._refresh_skl_model_combo(select=select_name)

        self.skl_current_model = self.skl_trained_models.get(select_name)
        self.skl_current_model_name = select_name
        self.skl_screening_best_model_name = config.get("best_model")

        if not names:
            QMessageBox.warning(self, i18n.t("msg_title_usi", self._idioma), f"No saved models were found on disk for USI '{code}'.")
        else:
            QMessageBox.information(self, i18n.t("msg_title_usi", self._idioma),
                f"USI '{code}' loaded: {len(names)} model(s) available"
                f"{' (with train/test data)' if getattr(self, 'skl_x_train', None) is not None else ''}."
            )

    def _populate_skl_model_list(self):
        if not hasattr(self, "list_skl_models"):
            return
        registry, task = self._get_skl_registry()

        self.list_skl_models.clear()
        self.list_skl_models.addItems(sorted(registry.keys()))

        self.cb_skl_metric.clear()
        if task == "regression":
            self.cb_skl_metric.addItems(["R2 Test", "RMSE", "MAE", "MSE"])
        elif task == "classification":
            self.cb_skl_metric.addItems(["Accuracy Test", "F1", "Precision", "Recall", "AUC"])
        elif task == "clustering":
            self.cb_skl_metric.addItems(["Silhouette", "Davies-Bouldin", "Calinski-Harabasz"])

        if hasattr(self, "list_skl_charts"):
            self.list_skl_charts.clear()
            if task == "regression":
                self.list_skl_charts.addItems([
                    "predicted_vs_actual - Predicted vs Experimental",
                    "residuals - Residuals Plot",
                    "feature_importance - Feature Importance (Top 15)",
                    "learning_curve - Learning Curve",
                    "manifold - t-SNE Projection (colored by residual)",
                    "tree - Decision Tree Diagram",
                ])
            elif task == "classification":
                self.list_skl_charts.addItems([
                    "confusion_matrix - Confusion Matrix",
                    "roc_auc - ROC Curve (AUC)",
                    "class_report - Classification Report",
                    "feature_importance - Feature Importance (Top 15)",
                    "learning_curve - Learning Curve",
                    "pr - Precision-Recall Curve",
                    "threshold - Precision/Recall/F1 vs Threshold",
                    "calibration - Calibration Curve",
                    "lift - Lift Curve",
                    "gain - Cumulative Gains Curve",
                    "ks - Kolmogorov-Smirnov Statistic",
                    "manifold - t-SNE Projection (colored by class)",
                    "tree - Decision Tree Diagram",
                ])
            elif task == "clustering":
                self.list_skl_charts.addItems([
                    "pca_scatter - 2D PCA Scatter (colored by cluster)",
                    "tsne - 2D t-SNE Scatter (colored by cluster)",
                    "elbow - Elbow Method",
                    "silhouette - Silhouette Plot",
                    "distribution - Cluster Size Distribution",
                ])

        is_clustering = (task == "clustering")
        tune_eval_widgets = [
            getattr(self, "cb_skl_tune_model", None), getattr(self, "cb_skl_tune_method", None),
            getattr(self, "sp_skl_tune_folds", None), getattr(self, "sp_skl_tune_n_iter", None),
            getattr(self, "tbl_skl_hyperparams", None), getattr(self, "btn_skl_run_tune", None),
            getattr(self, "cb_skl_tune_param", None), getattr(self, "btn_skl_tune_plot", None),
            getattr(self, "cb_skl_cv_method", None), getattr(self, "sp_skl_cv_folds", None),
            getattr(self, "sp_skl_cv_p", None), getattr(self, "chk_skl_cv_shuffle", None),
            getattr(self, "btn_skl_run_eval", None),
        ]
        for w in tune_eval_widgets:
            if w is not None:
                w.setEnabled(not is_clustering)

        # Reaplica o refinamento por método (ex.: n_iter só para Randomized/Bayesian, p só para Leave-P-Out)
        # agora que o estado de habilitação por tarefa já foi definido:
        if hasattr(self, "_update_skl_tune_method_widgets"):
            self._update_skl_tune_method_widgets()
        if hasattr(self, "_update_skl_cv_method_widgets"):
            self._update_skl_cv_method_widgets()
        if hasattr(self, "lbl_skl_tune_note"):
            self.lbl_skl_tune_note.setText(
                "Tuning and Cross-Validation are not available for clustering (unsupervised, no held-out labels)."
                if is_clustering else ""
            )

        if hasattr(self, "cb_skl_tune_model"):
            self.cb_skl_tune_model.clear()
        if hasattr(self, "tbl_skl_hyperparams"):
            self.tbl_skl_hyperparams.setRowCount(0)
        self._skl_tuned_param_grids = {}
        self._skl_tuning_settings = {}
        self._skl_validation_settings = {}

    def _refresh_skl_hyperparam_table(self, model_name):
        if not hasattr(self, "tbl_skl_hyperparams"):
            return
        model_name = (model_name or "").strip()
        # Se esse modelo já passou por Tuning (nesta sessão ou numa USI recarregada), restaura a
        # grade de hiperparâmetros que o usuário efetivamente usou/editou, em vez do padrão genérico.
        tuned_grids = getattr(self, "_skl_tuned_param_grids", None) or {}
        if model_name in tuned_grids:
            grid = tuned_grids[model_name]
        else:
            base_name = self._skl_resolve_base_model_name(model_name) or model_name
            grid = SKL_PARAM_GRIDS.get(base_name, [])
        self.tbl_skl_hyperparams.setRowCount(len(grid))
        for i, (param, values) in enumerate(grid):
            self.tbl_skl_hyperparams.setItem(i, 0, QTableWidgetItem(param))
            self.tbl_skl_hyperparams.setItem(i, 1, QTableWidgetItem(values))
        self.tbl_skl_hyperparams.resizeColumnsToContents()

    def _refresh_skl_tune_param_options(self, model_name):
        if not hasattr(self, "cb_skl_tune_param"):
            return
        model_name = (model_name or "").strip()
        tuned_grids = getattr(self, "_skl_tuned_param_grids", None) or {}
        if model_name in tuned_grids:
            grid = tuned_grids[model_name]
        else:
            base_name = self._skl_resolve_base_model_name(model_name) or model_name
            grid = SKL_PARAM_GRIDS.get(base_name, [])
        current = self.cb_skl_tune_param.currentText()
        self.cb_skl_tune_param.blockSignals(True)
        self.cb_skl_tune_param.clear()
        self.cb_skl_tune_param.addItem("n_features")
        for param_name, _values in grid:
            self.cb_skl_tune_param.addItem(param_name)
        idx = self.cb_skl_tune_param.findText(current)
        self.cb_skl_tune_param.setCurrentIndex(idx if idx != -1 else 0)
        self.cb_skl_tune_param.blockSignals(False)

    def _refresh_skl_model_settings_widgets(self, model_name):
        """Restaura, para o modelo selecionado no combobox 'Model' único, os valores dos grupos
        Hyperparameter Tuning (Method/CV folds/n_iter) e Validation (Method/shuffle/Folds/p) usados da
        última vez que Run Tuning / Run Cross-Validation rodaram para ESSE modelo especificamente —
        gravados em _skl_tuning_settings/_skl_validation_settings (por sua vez persistidos em
        skl_session.json) para que uma USI recarregada restaure tudo por completo."""
        model_name = (model_name or "").strip()

        tuning = (getattr(self, "_skl_tuning_settings", None) or {}).get(model_name)
        if tuning:
            method = tuning.get("method")
            if method and hasattr(self, "cb_skl_tune_method"):
                idx = self.cb_skl_tune_method.findText(method)
                if idx != -1:
                    self.cb_skl_tune_method.setCurrentIndex(idx)
            if tuning.get("folds") is not None and hasattr(self, "sp_skl_tune_folds"):
                self.sp_skl_tune_folds.setValue(int(tuning["folds"]))
            if tuning.get("n_iter") is not None and hasattr(self, "sp_skl_tune_n_iter"):
                self.sp_skl_tune_n_iter.setValue(int(tuning["n_iter"]))

        validation = (getattr(self, "_skl_validation_settings", None) or {}).get(model_name)
        if validation:
            method = validation.get("method")
            if method and hasattr(self, "cb_skl_cv_method"):
                idx = self.cb_skl_cv_method.findText(method)
                if idx != -1:
                    self.cb_skl_cv_method.setCurrentIndex(idx)
            if validation.get("shuffle") is not None and hasattr(self, "chk_skl_cv_shuffle"):
                self.chk_skl_cv_shuffle.setChecked(bool(validation["shuffle"]))
            if validation.get("folds") is not None and hasattr(self, "sp_skl_cv_folds"):
                self.sp_skl_cv_folds.setValue(int(validation["folds"]))
            if validation.get("p") is not None and hasattr(self, "sp_skl_cv_p"):
                self.sp_skl_cv_p.setValue(int(validation["p"]))

    def _skl_get_param_values_from_table(self, parameter_name):
        for row in range(self.tbl_skl_hyperparams.rowCount()):
            param_item = self.tbl_skl_hyperparams.item(row, 0)
            values_item = self.tbl_skl_hyperparams.item(row, 1)
            if param_item and param_item.text().strip() == parameter_name:
                values_text = values_item.text().strip() if values_item else ""
                return [_skl_parse_grid_value(v) for v in _skl_split_grid_values(values_text) if v.strip()]
        return []

    def _update_skl_tune_method_widgets(self):
        if not hasattr(self, "cb_skl_tune_method"):
            return
        method = self.cb_skl_tune_method.currentText()
        needs_n_iter = method in ("RandomizedSearchCV", "Bayesian Optimization (Optuna)")
        # Só habilita o n_iter se o método precisar dele E o grupo de tuning não estiver
        # desabilitado por conta de uma tarefa de clusterização selecionada:
        if self.cb_skl_tune_method.isEnabled():
            self.sp_skl_tune_n_iter.setEnabled(needs_n_iter)

    def _update_skl_cv_method_widgets(self):
        if not hasattr(self, "cb_skl_cv_method"):
            return
        method = self.cb_skl_cv_method.currentText()
        notes = {
            "Leave-One-Out (LOOCV)": "Trains one model per sample (n_samples folds) — can be slow for larger datasets.",
            "Leave-P-Out": "Trains one model per combination of p held-out samples — extremely slow for p > 1 or larger datasets.",
            "Time Series Split (Walk-Forward Validation)": "Assumes rows are already ordered chronologically.",
            "Nested CV": "Uses the Tuning group's hyperparameter grid as the inner search space (GridSearchCV) inside each outer fold.",
            "Bootstrap": "Trains on a bootstrap resample and evaluates on the out-of-bag samples, repeated 'Folds' times.",
        }
        if hasattr(self, "lbl_skl_cv_note"):
            self.lbl_skl_cv_note.setText(notes.get(method, ""))

        group_enabled = self.cb_skl_cv_method.isEnabled()
        if hasattr(self, "sp_skl_cv_p"):
            self.sp_skl_cv_p.setEnabled(group_enabled and method == "Leave-P-Out")
        if hasattr(self, "sp_skl_cv_folds"):
            needs_folds = method not in ("Leave-One-Out (LOOCV)", "Leave-P-Out")
            self.sp_skl_cv_folds.setEnabled(group_enabled and needs_folds)

    def _get_skl_xy(self):
        df = getattr(self, "df_int", None)
        if df is None or (hasattr(df, "empty") and df.empty):
            raise ValueError("Select an Internal DataFrame first — Screening always trains on the internal dataframe.")

        try:
            first_col = int(self.ed_skl_x_first_col.text().strip())
        except (ValueError, AttributeError):
            first_col = 0
        last_text = self.ed_skl_x_last_col.text().strip() if hasattr(self, "ed_skl_x_last_col") else ""
        try:
            last_col = int(last_text) if last_text else len(df.columns) - 1
        except ValueError:
            last_col = len(df.columns) - 1

        x = df.iloc[:, first_col:last_col + 1]

        _registry, task = self._get_skl_registry()
        y_col = self.cb_skl_y.currentText().strip() if hasattr(self, "cb_skl_y") else ""

        if task == "clustering":
            if y_col and y_col in x.columns:
                x = x.drop(columns=[y_col])
            x = x.select_dtypes(include=[np.number])
            if x.empty:
                raise ValueError("No numeric columns available for clustering in the selected X range.")
            return x, None

        if not y_col or y_col not in df.columns:
            raise ValueError("Select a valid Y column.")
        y = df[y_col]
        if y_col in x.columns:
            x = x.drop(columns=[y_col])
        x = x.select_dtypes(include=[np.number])
        if x.empty:
            raise ValueError("No numeric feature columns available in the selected X range.")
        return x, y

    def _fill_table_from_df(self, table, df):
        table.setRowCount(0)
        table.setColumnCount(len(df.columns))
        table.setHorizontalHeaderLabels([str(c) for c in df.columns])
        table.setRowCount(len(df))
        for i in range(len(df)):
            for j, col in enumerate(df.columns):
                val = df.iloc[i, j]
                text = f"{val:.4f}" if isinstance(val, float) else str(val)
                table.setItem(i, j, QTableWidgetItem(text))
        table.resizeColumnsToContents()

    # ---------- SCREENING ----------

    def run_skl_screening(self):
        try:
            registry, task = self._get_skl_registry()
            if not task:
                QMessageBox.warning(self, i18n.t("msg_title_screening", self._idioma), "Select a problem type (Classification/Regression/Clustering) in the CONFIG tab first.")
                return
            selected_items = self.list_skl_models.selectedItems()
            if not selected_items:
                QMessageBox.warning(self, i18n.t("msg_title_screening", self._idioma), "Select at least one model.")
                return
            try:
                x, y = self._get_skl_xy()
            except Exception as e:
                QMessageBox.warning(self, i18n.t("msg_title_screening", self._idioma), str(e))
                return

            # Cada execução de Run Screening grava em uma pasta USI nova, para não misturar/sobrescrever
            # os resultados de tentativas anteriores (ranking, modelos treinados, tuning, etc.).
            self._set_current_sklearn_usi_context(_generate_new_usi_code(self.job_dir))
            random_state = self._get_skl_random_state()

            model_specs = []
            for item in selected_items:
                name = item.text()
                cls, kwargs = registry[name]
                model_specs.append((name, cls, kwargs))

            self.txt_skl_status.clear()
            self.pb_skl_screening.setMaximum(len(model_specs))
            self.pb_skl_screening.setValue(0)
            self._skl_screening_done = 0

            test_size = self.dsp_skl_test_size.value() if hasattr(self, "dsp_skl_test_size") else 0.3
            self._skl_screening_worker = SklScreeningWorker(task, model_specs, x, y, random_state, test_size=test_size)
            self._skl_screening_worker.progress.connect(self._on_skl_screening_progress)
            self._skl_screening_worker.finished_all.connect(self._on_skl_screening_finished)
            self._skl_screening_worker.error.connect(self._on_skl_screening_error)
            self.btn_skl_run_screening.setEnabled(False)
            # Executa de forma síncrona na própria thread da GUI (não usa QThread.start()/nova thread em
            # background): rodar o treino de vários modelos em uma QThread separada causava fechamentos
            # inesperados da aplicação (crash nativo, sem exceção Python), especialmente ao selecionar
            # todos os modelos de uma vez. A interface fica congelada durante o cálculo, mas de forma estável.
            self._skl_screening_worker.run()
        except Exception as e:
            import traceback; traceback.print_exc()
            QMessageBox.critical(self, i18n.t("msg_title_screening_error", self._idioma), str(e))

    def _on_skl_screening_progress(self, message, row):
        self.txt_skl_status.append(message)
        self._skl_screening_done = getattr(self, "_skl_screening_done", 0) + 1
        self.pb_skl_screening.setValue(min(self._skl_screening_done, self.pb_skl_screening.maximum()))

    def _on_skl_screening_finished(self, rank_df):
        self.btn_skl_run_screening.setEnabled(True)
        if rank_df is None or rank_df.empty:
            QMessageBox.warning(self, i18n.t("msg_title_screening", self._idioma), "No model was successfully evaluated.")
            return

        metric = self.cb_skl_metric.currentText().strip()
        lower_is_better = metric in ("RMSE", "MAE", "MSE", "Davies-Bouldin")
        sort_col = metric if metric in rank_df.columns else rank_df.columns[-1]
        rank_df = rank_df.sort_values(by=sort_col, ascending=lower_is_better, na_position="last").reset_index(drop=True)
        self.skl_screening_rank = rank_df

        worker = self._skl_screening_worker
        self.skl_trained_models = dict(worker.trained_models)
        self.skl_x, self.skl_y = worker.x, worker.y
        self.skl_x_train, self.skl_x_test = worker.x_train, worker.x_test
        self.skl_y_train, self.skl_y_test = worker.y_train, worker.y_test
        # Nova USI (gerada em run_skl_screening) => nenhum histórico de Tuning/Validation anterior ainda.
        self._skl_tuned_param_grids = {}
        self._skl_tuning_settings = {}
        self._skl_validation_settings = {}

        # Combobox "Model" único (grupo Hyperparameter Tuning), na ordem do ranking (melhor primeiro) —
        # usado como referência por Tuning, Validation, Remove Model and Predict e Performance Charts.
        self.cb_skl_tune_model.blockSignals(True)
        self.cb_skl_tune_model.clear()
        self.cb_skl_tune_model.addItems(rank_df["Model"].astype(str).tolist())
        self.cb_skl_tune_model.blockSignals(False)
        self._refresh_skl_hyperparam_table(self.cb_skl_tune_model.currentText())
        self._refresh_skl_tune_param_options(self.cb_skl_tune_model.currentText())
        self._refresh_skl_model_settings_widgets(self.cb_skl_tune_model.currentText())

        best_name = str(rank_df.iloc[0]["Model"])
        self.skl_current_model = self.skl_trained_models.get(best_name)
        self.skl_current_model_name = best_name
        self.skl_screening_best_model_name = best_name

        # Auto-persiste modelos + dados de treino/teste + config da sessão, para que essa USI possa
        # ser recarregada depois selecionando o código no combobox USI.
        for name, model in self.skl_trained_models.items():
            self._save_skl_model_to_models_dir(name, model)
        self._save_skl_train_test_data()
        self._save_skl_session_config()
        self._save_step6_sklearn_state()
        # skl_session.json só passa a existir agora, então o combobox USI só consegue detectar
        # esse código como uma sessão STEP 5 depois que o arquivo é gravado.
        self._refresh_skl_usi_combo()

        try:
            out_path = os.path.join(self.skl_out_data, f"skl_screening_{self.skl_usi_key}_{datetime.now().strftime('%Y%m%d_%H%M%S')}.csv")
            rank_df.to_csv(out_path, index=False)
        except Exception:
            pass

        self.show_dataframe(rank_df)

    def _on_skl_screening_error(self, message):
        self.btn_skl_run_screening.setEnabled(True)
        QMessageBox.critical(self, i18n.t("msg_title_screening_error", self._idioma), message)

    # ---------- TUNING ----------

    def run_skl_tune(self):
        try:
            model_name = self.cb_skl_tune_model.currentText().strip()
            if not model_name:
                QMessageBox.warning(self, i18n.t("msg_title_tuning", self._idioma), "Run Screening first to obtain a ranked model list.")
                return
            registry, task = self._get_skl_registry()
            if task == "clustering":
                QMessageBox.information(self, i18n.t("msg_title_tuning", self._idioma), "Tuning is not available for clustering models.")
                return
            base_name = self._skl_resolve_base_model_name(model_name)
            if base_name is None:
                QMessageBox.warning(self, i18n.t("msg_title_tuning", self._idioma), f"Unknown model: {model_name}")
                return
            if getattr(self, "skl_x_train", None) is None:
                QMessageBox.warning(self, i18n.t("msg_title_tuning", self._idioma), "Run Screening first.")
                return

            param_grid = {}
            raw_grid_rows = []
            for row in range(self.tbl_skl_hyperparams.rowCount()):
                param_item = self.tbl_skl_hyperparams.item(row, 0)
                values_item = self.tbl_skl_hyperparams.item(row, 1)
                if not param_item or not values_item:
                    continue
                param_name = param_item.text().strip()
                values_text = values_item.text().strip()
                if not param_name or not values_text:
                    continue
                param_grid[param_name] = [_skl_parse_grid_value(v) for v in _skl_split_grid_values(values_text)]
                raw_grid_rows.append([param_name, values_text])

            if not param_grid:
                QMessageBox.warning(self, i18n.t("msg_title_tuning", self._idioma), "No hyperparameter range defined for this model.")
                return

            method = self.cb_skl_tune_method.currentText()
            if method == "Bayesian Optimization (Optuna)":
                try:
                    import optuna  # noqa: F401
                except ImportError:
                    QMessageBox.critical(self, i18n.t("msg_title_tuning_error", self._idioma), "Optuna is not installed. Install it with 'pip install optuna'.")
                    return

            cls, base_kwargs = registry[base_name]
            random_state = self._get_skl_random_state()
            folds = self.sp_skl_tune_folds.value()
            n_iter = self.sp_skl_tune_n_iter.value()

            self._skl_tune_task = task
            self._skl_tune_model_name = model_name
            self._skl_tune_base_name = base_name
            self._skl_tune_raw_grid_rows = raw_grid_rows
            self._skl_tune_method = method
            self._skl_tune_folds = folds
            self._skl_tune_n_iter = n_iter
            self._skl_tune_worker = SklTuneWorker(
                cls, base_kwargs, param_grid, method, folds, n_iter, random_state,
                self.skl_x_train, self.skl_y_train
            )
            self._skl_tune_worker.finished_ok.connect(self._on_skl_tune_finished)
            self._skl_tune_worker.error.connect(self._on_skl_tune_error)
            self.btn_skl_run_tune.setEnabled(False)
            # Mensagem de espera (sem barra de progresso), fechada em _on_skl_tune_finished()/
            # _on_skl_tune_error() assim que o cálculo termina, logo antes de exibir o resultado.
            self._skl_tune_progress_dlg = self.show_wait_message_dialog(
                "Hyperparameter Tuning", "Tuning hyperparameters... Please wait for it to finish!"
            )
            # Síncrono na thread da GUI — ver comentário em run_skl_screening() sobre os crashes
            # causados pelo uso de QThread em background para esses cálculos.
            self._skl_tune_worker.run()
        except Exception as e:
            dlg = getattr(self, "_skl_tune_progress_dlg", None)
            if dlg is not None:
                dlg.close()
                self._skl_tune_progress_dlg = None
            import traceback; traceback.print_exc()
            QMessageBox.critical(self, i18n.t("msg_title_tuning_error", self._idioma), str(e))

    def _on_skl_tune_finished(self, best_model, best_params, cv_results):
        dlg = getattr(self, "_skl_tune_progress_dlg", None)
        if dlg is not None:
            dlg.close()
            self._skl_tune_progress_dlg = None
        self.btn_skl_run_tune.setEnabled(True)
        task = self._skl_tune_task
        base_name = getattr(self, "_skl_tune_base_name", None) or self._skl_tune_model_name

        # Registra a versão otimizada como uma NOVA entrada (ex.: "RandomForestRegressor_1"), sem
        # sobrescrever a versão original/anterior, e já a seleciona no combobox "Model" único —
        # unificado entre Tuning, Validation, Remove Model and Predict e Performance Charts.
        new_name = self._add_skl_tuned_model_variant(base_name, best_model)
        self.skl_current_model = best_model
        self.skl_current_model_name = new_name
        self._refresh_skl_model_combo(select=new_name, preserve_order=True)

        # Lembra a grade de hiperparâmetros usada para "model_name" (o que estava selecionado no
        # combobox Model do Hyperparameter Tuning na hora de tunar), para restaurá-la depois quando
        # essa USI for recarregada e o mesmo modelo for reselecionado — evita voltar ao grid padrão de
        # SKL_PARAM_GRIDS quando o usuário já havia customizado os valores testados.
        if not hasattr(self, "_skl_tuned_param_grids") or self._skl_tuned_param_grids is None:
            self._skl_tuned_param_grids = {}
        self._skl_tuned_param_grids[self._skl_tune_model_name] = getattr(self, "_skl_tune_raw_grid_rows", [])

        # Lembra também Method/CV folds/n_iter usados para esse modelo, pelo mesmo motivo.
        if not hasattr(self, "_skl_tuning_settings") or self._skl_tuning_settings is None:
            self._skl_tuning_settings = {}
        self._skl_tuning_settings[self._skl_tune_model_name] = {
            "method": getattr(self, "_skl_tune_method", None),
            "folds": getattr(self, "_skl_tune_folds", None),
            "n_iter": getattr(self, "_skl_tune_n_iter", None),
        }

        self._save_skl_model_to_models_dir(new_name, best_model)
        self._save_skl_session_config()
        self._save_step6_sklearn_state()
        self._refresh_skl_usi_combo()

        y_test_pred = self.skl_current_model.predict(self.skl_x_test)
        if task == "regression":
            msg = (f"New optimized model: {new_name}\n\n"
                   f"Best params: {best_params}\n"
                   f"R2 Test: {r2_score(self.skl_y_test, y_test_pred):.4f}  "
                   f"RMSE: {mse(self.skl_y_test, y_test_pred) ** 0.5:.4f}  "
                   f"MAE: {mae(self.skl_y_test, y_test_pred):.4f}")
        else:
            msg = (f"New optimized model: {new_name}\n\n"
                   f"Best params: {best_params}\n"
                   f"Accuracy Test: {accuracy_score(self.skl_y_test, y_test_pred):.4f}  "
                   f"F1: {f1_score(self.skl_y_test, y_test_pred, average='weighted'):.4f}")
        QMessageBox.information(self, i18n.t("msg_title_tuning_complete", self._idioma), msg)

        try:
            out_path = os.path.join(self.skl_out_data, f"skl_tune_{new_name}_{self.skl_usi_key}_{datetime.now().strftime('%Y%m%d_%H%M%S')}.csv")
            cv_results.to_csv(out_path, index=False)
        except Exception:
            pass

        self.show_dataframe(cv_results)

    def _on_skl_tune_error(self, message):
        dlg = getattr(self, "_skl_tune_progress_dlg", None)
        if dlg is not None:
            dlg.close()
            self._skl_tune_progress_dlg = None
        self.btn_skl_run_tune.setEnabled(True)
        QMessageBox.critical(self, i18n.t("msg_title_tuning_error", self._idioma), message)

    # ---------- TUNING: SORT METRIC vs. PARAMETER / N_FEATURES CURVE ----------

    def run_skl_tune_plot(self):
        try:
            model_name = self.cb_skl_tune_model.currentText().strip()
            if not model_name:
                QMessageBox.warning(self, i18n.t("msg_title_plot", self._idioma), "Run Screening first to obtain a ranked model list.")
                return
            registry, task = self._get_skl_registry()
            if task == "clustering":
                QMessageBox.information(self, i18n.t("msg_title_plot", self._idioma), "This plot is not available for clustering models.")
                return
            base_name = self._skl_resolve_base_model_name(model_name)
            if base_name is None:
                QMessageBox.warning(self, i18n.t("msg_title_plot", self._idioma), f"Unknown model: {model_name}")
                return
            if getattr(self, "skl_x_train", None) is None:
                QMessageBox.warning(self, i18n.t("msg_title_plot", self._idioma), "Run Screening first.")
                return

            metric = self.cb_skl_metric.currentText().strip()
            if not metric:
                QMessageBox.warning(self, i18n.t("msg_title_plot", self._idioma), "Select a Sort metric first.")
                return

            parameter = self.cb_skl_tune_param.currentText().strip()
            values = None
            if parameter != "n_features":
                values = self._skl_get_param_values_from_table(parameter)
                if not values:
                    QMessageBox.warning(self, i18n.t("msg_title_plot", self._idioma), f"No values defined for '{parameter}' in the hyperparameter table.")
                    return

            cls, base_kwargs = registry[base_name]
            random_state = self._get_skl_random_state()

            self._skl_tune_plot_metric = metric
            self._skl_tune_plot_model_name = model_name
            self._skl_tune_plot_worker = SklTuneCurveWorker(
                cls, base_kwargs, parameter, metric, random_state,
                self.skl_x_train, self.skl_y_train, self.skl_x_test, self.skl_y_test, values=values
            )
            self._skl_tune_plot_worker.finished_ok.connect(self._on_skl_tune_plot_finished)
            self._skl_tune_plot_worker.error.connect(self._on_skl_tune_plot_error)
            self.btn_skl_tune_plot.setEnabled(False)
            # Mensagem de espera (sem barra de progresso), fechada em _on_skl_tune_plot_finished()/
            # _on_skl_tune_plot_error() assim que o cálculo termina, logo antes de exibir o resultado.
            self._skl_tune_plot_progress_dlg = self.show_wait_message_dialog(
                "Hyperparameter Tuning", "Building metric curve... Please wait for it to finish!"
            )
            # Síncrono na thread da GUI — ver comentário em run_skl_screening() sobre os crashes
            # causados pelo uso de QThread em background para esses cálculos.
            self._skl_tune_plot_worker.run()
        except Exception as e:
            dlg = getattr(self, "_skl_tune_plot_progress_dlg", None)
            if dlg is not None:
                dlg.close()
                self._skl_tune_plot_progress_dlg = None
            import traceback; traceback.print_exc()
            QMessageBox.critical(self, i18n.t("msg_title_plot_error", self._idioma), str(e))

    def _on_skl_tune_plot_finished(self, result):
        dlg = getattr(self, "_skl_tune_plot_progress_dlg", None)
        if dlg is not None:
            dlg.close()
            self._skl_tune_plot_progress_dlg = None
        self.btn_skl_tune_plot.setEnabled(True)
        try:
            x_values = result["x_values"]
            train_values = result["train_values"]
            test_values = result["test_values"]
            x_label = result["x_label"]
            metric = self._skl_tune_plot_metric
            model_name = self._skl_tune_plot_model_name

            lower_is_better = metric in ("RMSE", "MAE", "MSE", "Davies-Bouldin")
            valid_test = [v for v in test_values if v == v]  # descarta NaN
            if not valid_test:
                QMessageBox.warning(self, i18n.t("msg_title_plot", self._idioma), "No valid metric values were computed for this curve.")
                return
            best_val = min(valid_test) if lower_is_better else max(valid_test)
            best_idx = test_values.index(best_val)
            best_x = x_values[best_idx]

            is_numeric_x = all(isinstance(v, (int, float)) and not isinstance(v, bool) for v in x_values)
            plot_x = x_values if is_numeric_x else list(range(len(x_values)))

            fig, ax = plt.subplots(figsize=(9, 5))
            ax.plot(plot_x, train_values, label=f"{metric} (Train)", color="steelblue", marker="o")
            ax.plot(plot_x, test_values, label=f"{metric} (Test)", color="tomato", marker="o")
            if is_numeric_x:
                ax.axvline(plot_x[best_idx], linestyle="--", color="gray", linewidth=1)
            ax.annotate(
                f"{x_label}={best_x}\n{metric}={best_val:.3f}",
                xy=(plot_x[best_idx], best_val),
                xytext=(plot_x[best_idx] + max(1, len(plot_x) // 20), best_val),
                arrowprops=dict(arrowstyle="->", color="gray"), fontsize=9,
            )
            if not is_numeric_x:
                ax.set_xticks(plot_x)
                ax.set_xticklabels([str(v) for v in x_values], rotation=30, ha="right")
            ax.set_xlabel(x_label, fontsize=12)
            ax.set_ylabel(metric, fontsize=12)
            ax.set_title(f"{metric} vs. {x_label} — {model_name}", fontsize=13)
            ax.legend()
            fig.tight_layout()

            self._set_current_sklearn_usi_context()
            self._show_skl_plot_dialog(fig, f"{x_label}_curve", f"{model_name}_{x_label}_curve_{self.skl_usi_key}")
        except Exception as e:
            import traceback; traceback.print_exc()
            QMessageBox.critical(self, i18n.t("msg_title_plot_error", self._idioma), str(e))

    def _on_skl_tune_plot_error(self, message):
        dlg = getattr(self, "_skl_tune_plot_progress_dlg", None)
        if dlg is not None:
            dlg.close()
            self._skl_tune_plot_progress_dlg = None
        self.btn_skl_tune_plot.setEnabled(True)
        QMessageBox.critical(self, i18n.t("msg_title_plot_error", self._idioma), message)

    # ---------- EVALUATE (CROSS-VALIDATION) ----------

    def run_skl_evaluate(self):
        try:
            # Cross-Validation roda sobre o modelo selecionado no combobox "Model" do grupo
            # Hyperparameter Tuning (não sobre self.skl_current_model).
            model_name = self.cb_skl_tune_model.currentText().strip() if hasattr(self, "cb_skl_tune_model") else ""
            model = getattr(self, "skl_trained_models", {}).get(model_name) if model_name else None
            if model is None:
                QMessageBox.warning(self, i18n.t("msg_title_evaluate", self._idioma),
                    "Select a model in the Hyperparameter Tuning group's 'Model' combobox "
                    "(Run Screening first to populate it)."
                )
                return
            _registry, task = self._get_skl_registry()
            if task == "clustering":
                QMessageBox.information(self, i18n.t("msg_title_evaluate", self._idioma), "Cross-validation is not available for clustering models.")
                return
            x = getattr(self, "skl_x", None)
            y = getattr(self, "skl_y", None)
            if x is None or y is None:
                QMessageBox.warning(self, i18n.t("msg_title_evaluate", self._idioma), "Run Screening first.")
                return

            method = self.cb_skl_cv_method.currentText()
            x_reset = x.reset_index(drop=True)
            y_reset = y.reset_index(drop=True)

            folds = self.sp_skl_cv_folds.value()
            shuffle = self.chk_skl_cv_shuffle.isChecked()
            random_state = self._get_skl_random_state()

            if method == "Nested CV":
                registry, _task2 = self._get_skl_registry()
                base_name = self._skl_resolve_base_model_name(model_name)
                if base_name is None:
                    QMessageBox.warning(self, i18n.t("msg_title_evaluate", self._idioma), "Nested CV requires a model that maps to a known registry class.")
                    return
                cls, base_kwargs = registry[base_name]

                param_grid = {}
                for row in range(self.tbl_skl_hyperparams.rowCount()):
                    param_item = self.tbl_skl_hyperparams.item(row, 0)
                    values_item = self.tbl_skl_hyperparams.item(row, 1)
                    if not param_item or not values_item:
                        continue
                    param_name = param_item.text().strip()
                    values_text = values_item.text().strip()
                    if not param_name or not values_text:
                        continue
                    param_grid[param_name] = [_skl_parse_grid_value(v) for v in _skl_split_grid_values(values_text)]
                if not param_grid:
                    QMessageBox.warning(self, i18n.t("msg_title_evaluate", self._idioma), "Define a hyperparameter grid in the Tuning group first (used as the inner search space for Nested CV).")
                    return

                mode = "nested"
                worker_kwargs = dict(
                    cls=cls, base_kwargs=base_kwargs, param_grid=param_grid,
                    folds=folds, shuffle=shuffle, random_state=random_state,
                    inner_folds=self.sp_skl_tune_folds.value(),
                )
            elif method == "Bootstrap":
                mode = "bootstrap"
                worker_kwargs = dict(n_iterations=folds, random_state=random_state)
            else:
                mode = "standard"
                worker_kwargs = dict(
                    method=method, folds=folds, shuffle=shuffle, random_state=random_state,
                    p=self.sp_skl_cv_p.value(),
                )

            self._skl_evaluate_model_name = model_name
            self._skl_evaluate_cv_method = method
            self._skl_evaluate_cv_folds = folds
            self._skl_evaluate_cv_shuffle = shuffle
            self._skl_evaluate_cv_p = self.sp_skl_cv_p.value()
            self._skl_evaluate_worker = SklEvaluateWorker(
                mode, task, model, x_reset, y_reset, **worker_kwargs
            )
            self._skl_evaluate_worker.finished_ok.connect(self._on_skl_evaluate_finished)
            self._skl_evaluate_worker.error.connect(self._on_skl_evaluate_error)
            self.btn_skl_run_eval.setEnabled(False)
            # Mensagem de espera (sem barra de progresso), fechada em _on_skl_evaluate_finished()/
            # _on_skl_evaluate_error() assim que o cálculo termina, logo antes de exibir o resultado.
            self._skl_evaluate_progress_dlg = self.show_wait_message_dialog(
                "Validation", "Running cross-validation... Please wait for it to finish!"
            )
            # Síncrono na thread da GUI — ver comentário em run_skl_screening() sobre os crashes
            # causados pelo uso de QThread em background para esses cálculos.
            self._skl_evaluate_worker.run()
        except Exception as e:
            dlg = getattr(self, "_skl_evaluate_progress_dlg", None)
            if dlg is not None:
                dlg.close()
                self._skl_evaluate_progress_dlg = None
            import traceback; traceback.print_exc()
            QMessageBox.critical(self, i18n.t("msg_title_evaluate_error", self._idioma), str(e))

    def _on_skl_evaluate_finished(self, cv_df):
        dlg = getattr(self, "_skl_evaluate_progress_dlg", None)
        if dlg is not None:
            dlg.close()
            self._skl_evaluate_progress_dlg = None
        self.btn_skl_run_eval.setEnabled(True)
        self._fill_table_from_df(self.tbl_skl_cv, cv_df)

        eval_model_name = getattr(self, "_skl_evaluate_model_name", "model")
        # Lembra Method/shuffle/Folds/p usados para esse modelo, para restaurá-los quando essa USI for
        # recarregada e o mesmo modelo for reselecionado.
        if not hasattr(self, "_skl_validation_settings") or self._skl_validation_settings is None:
            self._skl_validation_settings = {}
        self._skl_validation_settings[eval_model_name] = {
            "method": getattr(self, "_skl_evaluate_cv_method", None),
            "folds": getattr(self, "_skl_evaluate_cv_folds", None),
            "shuffle": getattr(self, "_skl_evaluate_cv_shuffle", None),
            "p": getattr(self, "_skl_evaluate_cv_p", None),
        }
        self._save_skl_session_config()
        self._save_step6_sklearn_state()

        try:
            out_path = os.path.join(self.skl_out_data, f"skl_cv_{eval_model_name}_{self.skl_usi_key}_{datetime.now().strftime('%Y%m%d_%H%M%S')}.csv")
            cv_df.to_csv(out_path, index=False)
        except Exception:
            pass

    def _on_skl_evaluate_error(self, message):
        dlg = getattr(self, "_skl_evaluate_progress_dlg", None)
        if dlg is not None:
            dlg.close()
            self._skl_evaluate_progress_dlg = None
        self.btn_skl_run_eval.setEnabled(True)
        QMessageBox.critical(self, i18n.t("msg_title_evaluate_error", self._idioma), message)

    # ---------- REMOVE MODEL ----------

    def run_skl_remove_model(self):
        try:
            if not hasattr(self, "list_skl_saved_models"):
                return
            selected = [item.text() for item in self.list_skl_saved_models.selectedItems()]
            if not selected:
                QMessageBox.warning(self, i18n.t("msg_title_remove_model", self._idioma), "Select at least one model in the list to remove.")
                return
            reply = QMessageBox.question(self, i18n.t("msg_title_remove_model", self._idioma),
                "Permanently delete the following model file(s) from disk?\n\n" + "\n".join(selected),
                QMessageBox.Yes | QMessageBox.No, QMessageBox.No
            )
            if reply != QMessageBox.Yes:
                return

            self._set_current_sklearn_usi_context()
            removed = []
            for name in selected:
                model_path = os.path.join(self.skl_models_path, f"{name}.joblib")
                try:
                    if os.path.isfile(model_path):
                        os.remove(model_path)
                    removed.append(name)
                except Exception:
                    continue
                if hasattr(self, "skl_trained_models") and self.skl_trained_models and name in self.skl_trained_models:
                    del self.skl_trained_models[name]
                if getattr(self, "skl_current_model_name", None) == name:
                    self.skl_current_model = None
                    self.skl_current_model_name = None

            # Repopula o combobox "Model" e a própria lista de seleção múltipla sem os modelos removidos.
            self._refresh_skl_model_combo()
            self._save_skl_session_config()
            self._save_step6_sklearn_state()
            QMessageBox.information(self, i18n.t("msg_title_remove_model", self._idioma), f"Removed {len(removed)} model(s).")
        except Exception as e:
            import traceback; traceback.print_exc()
            QMessageBox.critical(self, i18n.t("msg_title_remove_model_error", self._idioma), str(e))

    # ---------- PREDICT ----------

    def run_skl_predict(self):
        try:
            # Predict roda sobre o(s) modelo(s) selecionado(s) na caixa de seleção múltipla deste
            # próprio grupo (list_skl_saved_models), não sobre o combobox "Model" único do
            # Hyperparameter Tuning — permite gerar predições de vários modelos de uma vez.
            if not hasattr(self, "list_skl_saved_models"):
                return
            selected_names = [item.text() for item in self.list_skl_saved_models.selectedItems()]
            if not selected_names:
                QMessageBox.warning(self, i18n.t("msg_title_predict", self._idioma),
                    "Select at least one model in the list on the left of this group "
                    "(Run Screening first to populate it)."
                )
                return
            models = {}
            for name in selected_names:
                model = getattr(self, "skl_trained_models", {}).get(name)
                if model is None:
                    QMessageBox.warning(self, i18n.t("msg_title_predict", self._idioma), f"Model '{name}' is not loaded/trained in this session.")
                    return
                models[name] = model

            # Predict roda sempre sobre o External Dataframe.
            df = getattr(self, "df_ext", None)
            if df is None:
                # Selecionar uma USI no combobox restaura os modelos e os dados de treino/teste, mas
                # não o DataFrame original — o usuário ainda precisa clicar em "Select External
                # DataFrame" nesta sessão antes de rodar o Predict.
                QMessageBox.warning(self, i18n.t("msg_title_predict", self._idioma),
                    "Select the External DataFrame first — click 'Select External DataFrame' above. "
                    "Loading a USI restores the trained models and train/test data, but not the "
                    "original DataFrame used for Predict."
                )
                return
            try:
                first_col = int(self.ed_skl_pd_first_col.text().strip())
                last_text = self.ed_skl_pd_last_col.text().strip()
                last_col = int(last_text) if last_text else len(df.columns) - 1
            except ValueError:
                QMessageBox.warning(self, i18n.t("msg_title_predict", self._idioma), "Enter valid column indices.")
                return

            # Colunas que não existem no Internal Dataframe (usado no treino) são "diferentes" — não
            # fazem parte dos descritores do modelo — e são ignoradas na predição e removidas do
            # resultado final.
            _missing_in_ext, extra_in_ext = self._get_external_columns_diff(df)
            different_cols = extra_in_ext or []

            x_new = df.iloc[:, first_col:last_col + 1].select_dtypes(include=[np.number])
            if different_cols:
                x_new = x_new.drop(columns=[c for c in different_cols if c in x_new.columns], errors="ignore")
            if x_new.empty:
                QMessageBox.warning(self, i18n.t("msg_title_predict", self._idioma), "No numeric columns found in the selected range.")
                return

            _registry, task = self._get_skl_registry()
            # Nome das colunas de predição: <métrica de bioatividade>_<nome do modelo> (ex.:
            # "IC50_RandomForestRegressor") — usa a mesma coluna Y escolhida no Screening
            # ("Select Y column (internal df):"), para que STEP 8/Value Column consiga reconhecer a
            # natureza da métrica mesmo com vários modelos gerando várias colunas de predição.
            y_col = self.cb_skl_y.currentText().strip() if hasattr(self, "cb_skl_y") else ""

            df_result = df.drop(columns=different_cols, errors="ignore").copy() if different_cols else df.copy()

            # Mensagem de espera (sem barra de progresso), fechada assim que a predição termina, logo
            # antes de exibir o resultado.
            dlg = self.show_wait_message_dialog("Predict", "Running prediction... Please wait for it to finish!")
            try:
                for name, model in models.items():
                    if task == "clustering" and not hasattr(model, "predict"):
                        y_pred = model.fit_predict(x_new)
                        col_name = f"cluster_pred_{name}"
                    elif task == "clustering":
                        y_pred = model.predict(x_new)
                        col_name = f"cluster_pred_{name}"
                    else:
                        y_pred = model.predict(x_new)
                        col_name = f"{y_col}_{name}" if y_col else f"{name}_pred"
                    df_result[col_name] = y_pred
            finally:
                dlg.close()

            # "Remove Descriptors" (marcado por padrão): mantém só Name, SMILES e as colunas de
            # predição, descartando as colunas de descritores do intervalo "Descriptors Columns Range".
            if hasattr(self, "chk_skl_pd_remove_descriptors") and self.chk_skl_pd_remove_descriptors.isChecked():
                descriptor_cols = list(df.columns[first_col:last_col + 1])
                df_result = df_result.drop(columns=[c for c in descriptor_cols if c in df_result.columns], errors="ignore")

            self._set_current_sklearn_usi_context()
            timestamp = datetime.now().strftime('%Y%m%d_%H%M%S')
            file_suffix = selected_names[0] if len(selected_names) == 1 else f"{len(selected_names)}models"
            self._next_dataframe_save_path = os.path.join(
                self.skl_predictions_path, f"{timestamp}_df_predicted_{file_suffix}_{self.skl_usi_key}.csv"
            )
            self.show_dataframe(df_result)
        except Exception as e:
            import traceback; traceback.print_exc()
            QMessageBox.critical(self, i18n.t("msg_title_predict_error", self._idioma), str(e))

    # ---------- CHARTS ----------

    def run_view_skl_train_test_frequency(self):
        """Botão "View Frequency" do grupo Model Screening (STEP 4): gráfico de barras com o
        tamanho do conjunto de treino e do conjunto de teste, calculados a partir de "Select Test
        Size" e do número de linhas do DataFrame Interno selecionado - não depende de Run
        Screening já ter sido executado (não faz nenhum split de fato). Salva automaticamente em
        MIDIA da USI atual e exibe o gráfico; o nome proposto ao clicar em "Save Chart" usa a
        coluna escolhida em "Select Column Y (internal df)" como prefixo."""
        if getattr(self, "df_int", None) is None:
            QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), "No Internal DataFrame loaded.")
            return

        n_total = len(self.df_int)
        if n_total == 0:
            QMessageBox.warning(self, i18n.t("msg_title_attention", self._idioma), "The Internal DataFrame has no rows.")
            return

        test_size = self.dsp_skl_test_size.value() if hasattr(self, "dsp_skl_test_size") else 0.3
        # Mesma conta usada por train_test_split (sklearn) quando só test_size é informado.
        n_test = int(np.ceil(test_size * n_total))
        n_test = max(0, min(n_total, n_test))
        n_train = n_total - n_test

        y_col = self.cb_skl_y.currentText().strip() if hasattr(self, "cb_skl_y") else ""

        fig, ax = plt.subplots(figsize=(6, 5))
        counts = [n_train, n_test]
        bars = ax.bar(["Train", "Test"], counts, color=["#357fb4", "#bd793d"])
        ax.spines[['top', 'right']].set_visible(False)
        ax.grid(False)
        ax.set_ylabel("Count", fontsize=10, fontweight="bold")
        max_val = max(counts) if counts else 0
        y_offset = 0.02 * max_val if max_val > 0 else 0.1
        for bar, val in zip(bars, counts):
            ax.text(bar.get_x() + bar.get_width() / 2, val + y_offset, f"{val}", va="bottom", ha="center", fontweight="bold")
        fig.suptitle(f"Train/Test Split (Test Size = {test_size:.2f}, n = {n_total})", fontweight="bold")
        fig.tight_layout(rect=[0, 0, 1, 0.94])

        self._set_current_sklearn_usi_context()
        file_stem = f"{y_col}_Train_Test_Plot" if y_col else "Train_Test_Plot"
        file_stem = f"{file_stem}_{self.skl_usi_key}"
        auto_path = os.path.join(self.skl_plot_path, f"{file_stem}.png")
        try:
            fig.savefig(auto_path, dpi=300, bbox_inches="tight", facecolor="white")
        except Exception as e:
            QMessageBox.warning(self, i18n.t("msg_title_plot", self._idioma), f"Could not auto-save chart to MIDIA:\n{e}")

        self._show_skl_plot_dialog(fig, "train_test_frequency", file_stem)

    def run_skl_plot(self):
        try:
            # Plot Model roda sobre o modelo selecionado no combobox "Model" único (grupo
            # Hyperparameter Tuning), não sobre self.skl_current_model.
            model_name = self.cb_skl_tune_model.currentText().strip() if hasattr(self, "cb_skl_tune_model") else ""
            model = getattr(self, "skl_trained_models", {}).get(model_name) if model_name else None
            if model is None:
                QMessageBox.warning(self, i18n.t("msg_title_plot", self._idioma),
                    "Select a model in the Hyperparameter Tuning group's 'Model' combobox "
                    "(Run Screening first to populate it)."
                )
                return
            selected = self.list_skl_charts.selectedItems()
            if not selected:
                QMessageBox.warning(self, i18n.t("msg_title_plot", self._idioma), "Select at least one chart.")
                return
            _registry, task = self._get_skl_registry()
            self._set_current_sklearn_usi_context()

            # Com 2+ gráficos selecionados, todos são salvos automaticamente em MIDIA (da USI atual)
            # sem exibir nenhum deles — a exibição interativa (com o botão "Save Chart" no diálogo) só
            # ocorre ao gerar um único gráfico por vez.
            auto_save_only = len(selected) > 1
            saved_paths = []
            for item in selected:
                kind = item.text().split(" - ")[0].strip()
                # Mensagem de espera (sem barra de progresso) por gráfico, fechada assim que ele
                # termina de ser construído, logo antes de exibir/salvar o resultado (permite
                # selecionar vários gráficos de uma vez, cada um com seu próprio ciclo).
                dlg = self.show_wait_message_dialog("Plot", "Building chart... Please wait for it to finish!")
                try:
                    fig = self._build_skl_plot_figure(kind, task, model=model, model_name=model_name)
                finally:
                    dlg.close()
                if fig is None:
                    continue
                if auto_save_only:
                    path = os.path.join(self.skl_plot_path, f"{model_name}_{kind}_{self.skl_usi_key}.png")
                    try:
                        fig.savefig(path, dpi=300, bbox_inches="tight", facecolor="white")
                        saved_paths.append(path)
                    finally:
                        plt.close(fig)
                else:
                    self._show_skl_plot_dialog(fig, kind, f"{model_name}_{kind}_{self.skl_usi_key}")

            if auto_save_only and saved_paths:
                QMessageBox.information(self, i18n.t("msg_title_plot", self._idioma),
                    f"{len(saved_paths)} chart(s) saved to:\n" + "\n".join(saved_paths)
                )
        except Exception as e:
            import traceback; traceback.print_exc()
            QMessageBox.critical(self, i18n.t("msg_title_plot_error", self._idioma), str(e))

    def _build_skl_plot_figure(self, kind, task, model=None, model_name=None):
        if model is None:
            model = self.skl_current_model
        if model_name is None:
            model_name = getattr(self, "skl_current_model_name", "model")

        # Esses gráficos precisam do split de treino/teste gerado pelo Run Screening (self.skl_x_test/
        # skl_y_test). Um modelo obtido via Load (sem nunca ter rodado Screening nesta sessão) não tem
        # esses atributos definidos — sem essa checagem, o acesso direto abaixo derruba a interface com
        # AttributeError em vez de avisar o usuário.
        needs_test_split = kind in (
            "predicted_vs_actual", "residuals", "confusion_matrix", "roc_auc", "class_report",
            "manifold", "pr", "threshold", "calibration", "lift", "gain", "ks",
        )
        if needs_test_split and (getattr(self, "skl_x_test", None) is None or getattr(self, "skl_y_test", None) is None):
            QMessageBox.warning(self, i18n.t("msg_title_plot", self._idioma),
                "This chart needs the train/test split from Run Screening. Run Screening at least once "
                "in this session (Tuning/Load can be used afterward) before plotting this chart."
            )
            return None

        show_metric_legend = (
            getattr(self, "chk_skl_metric_legend", None) is not None
            and self.chk_skl_metric_legend.isChecked()
        )

        if kind == "predicted_vs_actual" and task == "regression":
            y_pred = model.predict(self.skl_x_test)
            fig, ax = plt.subplots(figsize=(6, 5))
            ax.scatter(self.skl_y_test, y_pred, alpha=0.5, color="tomato")
            lims = [min(self.skl_y_test.min(), y_pred.min()), max(self.skl_y_test.max(), y_pred.max())]
            ax.plot(lims, lims, "--", color="gray")
            ax.set_xlabel("Experimental"); ax.set_ylabel("Predicted")
            ax.set_title(f"{model_name}: Predicted vs Experimental")
            if show_metric_legend:
                ax.plot([], [], " ", label=_skl_regression_metrics_label(self.skl_y_test, y_pred))
                ax.legend(loc="best")
            return fig

        if kind == "residuals" and task == "regression":
            y_pred = model.predict(self.skl_x_test)
            residuals = self.skl_y_test - y_pred
            # Histograma marginal projetado à direita, mostrando a distribuição dos resíduos ao longo
            # do mesmo eixo Y (Residuals) do gráfico principal — 20% da largura para o histograma e
            # 80% para o gráfico de resíduos original.
            fig, (ax, ax_hist) = plt.subplots(
                1, 2, figsize=(7.5, 5), gridspec_kw={"width_ratios": [4, 1]}, sharey=True
            )
            ax.scatter(y_pred, residuals, alpha=0.5, color="tomato")
            ax.axhline(0, linestyle="--", color="gray")
            ax.set_xlabel("Predicted"); ax.set_ylabel("Residuals")
            ax.set_title(f"{model_name}: Residuals")
            if show_metric_legend:
                ax.plot([], [], " ", label=_skl_regression_metrics_label(self.skl_y_test, y_pred))
                ax.legend(loc="best")

            ax_hist.hist(residuals, bins=20, orientation="horizontal", color="tomato", alpha=0.8)
            ax_hist.axhline(0, linestyle="--", color="gray")
            ax_hist.set_xlabel("Count")
            ax_hist.tick_params(axis="y", labelleft=False)
            fig.tight_layout()
            return fig

        if kind == "manifold" and task in ("regression", "classification"):
            n_samples = len(self.skl_x_test)
            if n_samples < 4:
                QMessageBox.information(self, i18n.t("msg_title_plot", self._idioma), "Not enough test samples for a t-SNE projection.")
                return None
            perplexity = min(30, max(2, n_samples - 1))
            tsne = TSNE(n_components=2, random_state=self._get_skl_random_state(), perplexity=perplexity)
            coords = tsne.fit_transform(self.skl_x_test)
            fig, ax = plt.subplots(figsize=(6, 5))
            if task == "regression":
                y_pred = model.predict(self.skl_x_test)
                color_vals = np.abs(self.skl_y_test - y_pred)
                scatter = ax.scatter(coords[:, 0], coords[:, 1], c=color_vals, cmap="viridis", alpha=0.7)
                fig.colorbar(scatter, ax=ax, label="|Residual|")
                ax.set_title(f"{model_name}: t-SNE Projection (colored by |residual|)")
            else:
                classes = sorted(set(self.skl_y_test))
                class_to_idx = {c: i for i, c in enumerate(classes)}
                color_vals = [class_to_idx[c] for c in self.skl_y_test]
                scatter = ax.scatter(coords[:, 0], coords[:, 1], c=color_vals, cmap="tab10", alpha=0.7)
                cbar = fig.colorbar(scatter, ax=ax, ticks=range(len(classes)))
                cbar.ax.set_yticklabels([str(c) for c in classes])
                cbar.set_label("Class")
                ax.set_title(f"{model_name}: t-SNE Projection (colored by class)")
            ax.set_xlabel("t-SNE 1"); ax.set_ylabel("t-SNE 2")
            return fig

        if kind == "feature_importance":
            importances = getattr(model, "feature_importances_", None)
            if importances is None:
                coefs = getattr(model, "coef_", None)
                importances = np.abs(coefs).flatten() if coefs is not None else None
            if importances is None:
                QMessageBox.information(self, i18n.t("msg_title_plot", self._idioma), f"{model_name} does not expose feature importances.")
                return None
            feat_names = list(self.skl_x_train.columns) if getattr(self, "skl_x_train", None) is not None else [f"F{i}" for i in range(len(importances))]
            order = np.argsort(importances)[::-1][:15]
            fig, ax = plt.subplots(figsize=(8, 6))
            ax.barh([feat_names[i] for i in order][::-1], [importances[i] for i in order][::-1])
            ax.set_xlabel("Importance")
            ax.set_title(f"{model_name}: Top 15 Feature Importances")
            fig.tight_layout()
            return fig

        if kind == "learning_curve":
            x = getattr(self, "skl_x", None); y = getattr(self, "skl_y", None)
            if x is None or y is None:
                return None

            # Usa a mesma métrica escolhida em "Sort metric" (Model Screening) em vez do
            # score padrão do sklearn (R² para regressão, Acurácia para classificação) -
            # mapeada para os scorers nativos do sklearn, que já fazem a validação cruzada
            # internamente. Métricas sem equivalente direto (ex.: as de clustering) caem
            # no comportamento anterior (scoring=None -> score padrão do modelo).
            metric_scoring_map = {
                "R2 Test": "r2", "R2": "r2",
                "RMSE": "neg_root_mean_squared_error",
                "MAE": "neg_mean_absolute_error",
                "MSE": "neg_mean_squared_error",
                "Accuracy Test": "accuracy", "Accuracy": "accuracy",
                "F1": "f1_weighted",
                "Precision": "precision_weighted",
                "Recall": "recall_weighted",
                "AUC": "roc_auc_ovr_weighted",
            }
            selected_metric = self.cb_skl_metric.currentText().strip() if hasattr(self, "cb_skl_metric") else ""
            scoring = metric_scoring_map.get(selected_metric)
            # Métricas "neg_*" do sklearn vêm com sinal invertido (convenção interna para
            # manter "maior é melhor" em toda a API) - invertido de volta para exibir na
            # escala usual (ex.: RMSE positivo).
            sign = -1.0 if scoring and scoring.startswith("neg_") else 1.0
            y_label = selected_metric if scoring else "Score"

            try:
                # shuffle=True: por padrão o sklearn NÃO embaralha antes de repartir os 5 folds
                # (shuffle=False), e sem shuffle=True o random_state é ignorado. Sem embaralhar,
                # os folds viram blocos contíguos na ordem original das linhas do dataset — que
                # em datasets do ChEMBL costuma estar agrupada por alvo/assay/fonte, não é
                # aleatória — derrubando artificialmente o score de Cross-Validation exibido.
                train_sizes, train_scores, test_scores = learning_curve(
                    clone(model), x, y, cv=5, scoring=scoring, shuffle=True,
                    random_state=self._get_skl_random_state()
                )
            except Exception:
                # Scorer incompatível com o modelo/tarefa atual (ex.: AUC sem predict_proba) -
                # volta para o score padrão do sklearn em vez de falhar o gráfico.
                train_sizes, train_scores, test_scores = learning_curve(
                    clone(model), x, y, cv=5, shuffle=True, random_state=self._get_skl_random_state()
                )
                sign, y_label = 1.0, "Score"

            fig, ax = plt.subplots(figsize=(7, 5))
            ax.plot(train_sizes, sign * train_scores.mean(axis=1), label="Train", marker="o", color="steelblue")
            ax.plot(train_sizes, sign * test_scores.mean(axis=1), label="Cross-Validation", marker="o", color="tomato")
            ax.set_xlabel("Training examples"); ax.set_ylabel(y_label)
            ax.set_title(f"{model_name}: Learning Curve")
            ax.legend()
            return fig

        if kind == "tree":
            target_tree_model = model
            note = ""
            if not hasattr(target_tree_model, "tree_"):
                estimators = getattr(target_tree_model, "estimators_", None)
                if estimators is not None and len(estimators) > 0 and hasattr(estimators[0], "tree_"):
                    target_tree_model = estimators[0]
                    note = " (first estimator of the ensemble)"
                else:
                    QMessageBox.information(self, i18n.t("msg_title_plot", self._idioma), f"{model_name} is not a decision tree and has no tree-based estimators to plot.")
                    return None
            feat_names = list(self.skl_x_train.columns) if getattr(self, "skl_x_train", None) is not None else None
            fig, ax = plt.subplots(figsize=(14, 8))
            plot_tree(target_tree_model, feature_names=feat_names, filled=True, max_depth=3, fontsize=8, ax=ax)
            ax.set_title(f"{model_name}: Decision Tree{note} (max depth shown: 3)")
            return fig

        if kind == "confusion_matrix" and task == "classification":
            y_pred = model.predict(self.skl_x_test)
            labels = sorted(set(self.skl_y_test) | set(y_pred))
            cm = confusion_matrix(self.skl_y_test, y_pred, labels=labels)
            fig, ax = plt.subplots(figsize=(6, 5))
            im = ax.imshow(cm, cmap="Blues")
            ax.set_xticks(range(len(labels))); ax.set_xticklabels(labels)
            ax.set_yticks(range(len(labels))); ax.set_yticklabels(labels)
            ax.set_xlabel("Predicted"); ax.set_ylabel("True")
            ax.set_title(f"{model_name}: Confusion Matrix")
            thresh = cm.max() / 2.0
            for i in range(cm.shape[0]):
                for j in range(cm.shape[1]):
                    ax.text(j, i, format(cm[i, j], "d"), ha="center", va="center",
                            color="white" if cm[i, j] > thresh else "black")
            fig.colorbar(im, ax=ax)
            return fig

        if kind == "roc_auc" and task == "classification":
            if not hasattr(model, "predict_proba"):
                QMessageBox.information(self, i18n.t("msg_title_plot", self._idioma), f"{model_name} does not support predict_proba.")
                return None
            classes = sorted(set(self.skl_y_test))
            y_score = model.predict_proba(self.skl_x_test)
            fig, ax = plt.subplots(figsize=(6, 5))
            if len(classes) == 2:
                fpr, tpr, _ = roc_curve(self.skl_y_test, y_score[:, 1])
                roc_auc_val = auc(fpr, tpr)
                ax.plot(fpr, tpr, label=f"ROC (AUC = {roc_auc_val:.2f})", color="tomato")
            else:
                y_test_bin = LabelBinarizer().fit(classes).transform(self.skl_y_test)
                fpr, tpr, _ = roc_curve(y_test_bin.ravel(), y_score.ravel())
                roc_auc_val = auc(fpr, tpr)
                ax.plot(fpr, tpr, label=f"Micro-average ROC (AUC = {roc_auc_val:.2f})", color="tomato")
            ax.plot([0, 1], [0, 1], "k--")
            ax.set_xlabel("False Positive Rate"); ax.set_ylabel("True Positive Rate")
            ax.set_title(f"{model_name}: ROC Curve")
            ax.legend(loc="lower right")
            return fig

        if kind == "pr" and task == "classification":
            if not hasattr(model, "predict_proba"):
                QMessageBox.information(self, i18n.t("msg_title_plot", self._idioma), f"{model_name} does not support predict_proba.")
                return None
            classes = sorted(set(self.skl_y_test))
            if len(classes) != 2:
                QMessageBox.information(self, i18n.t("msg_title_plot", self._idioma), "The Precision-Recall Curve is only available for binary classification.")
                return None
            y_score = model.predict_proba(self.skl_x_test)[:, 1]
            precision, recall, _ = precision_recall_curve(self.skl_y_test, y_score, pos_label=classes[1])
            fig, ax = plt.subplots(figsize=(6, 5))
            ax.plot(recall, precision, color="tomato")
            ax.set_xlabel("Recall"); ax.set_ylabel("Precision")
            ax.set_title(f"{model_name}: Precision-Recall Curve")
            return fig

        if kind == "threshold" and task == "classification":
            if not hasattr(model, "predict_proba"):
                QMessageBox.information(self, i18n.t("msg_title_plot", self._idioma), f"{model_name} does not support predict_proba.")
                return None
            classes = sorted(set(self.skl_y_test))
            if len(classes) != 2:
                QMessageBox.information(self, i18n.t("msg_title_plot", self._idioma), "The Threshold plot is only available for binary classification.")
                return None
            y_score = model.predict_proba(self.skl_x_test)[:, 1]
            precision, recall, thresholds = precision_recall_curve(self.skl_y_test, y_score, pos_label=classes[1])
            f1_scores = np.where((precision + recall) > 0, 2 * precision * recall / (precision + recall + 1e-12), 0.0)
            fig, ax = plt.subplots(figsize=(7, 5))
            ax.plot(thresholds, precision[:-1], label="Precision", color="steelblue")
            ax.plot(thresholds, recall[:-1], label="Recall", color="tomato")
            ax.plot(thresholds, f1_scores[:-1], label="F1", color="seagreen")
            ax.set_xlabel("Threshold"); ax.set_ylabel("Score")
            ax.set_title(f"{model_name}: Precision / Recall / F1 vs Threshold")
            ax.legend()
            return fig

        if kind == "calibration" and task == "classification":
            if not hasattr(model, "predict_proba"):
                QMessageBox.information(self, i18n.t("msg_title_plot", self._idioma), f"{model_name} does not support predict_proba.")
                return None
            classes = sorted(set(self.skl_y_test))
            if len(classes) != 2:
                QMessageBox.information(self, i18n.t("msg_title_plot", self._idioma), "The Calibration Curve is only available for binary classification.")
                return None
            y_score = model.predict_proba(self.skl_x_test)[:, 1]
            y_true_bin = np.asarray(self.skl_y_test == classes[1]).astype(int)
            frac_pos, mean_pred = calibration_curve(y_true_bin, y_score, n_bins=10)
            fig, ax = plt.subplots(figsize=(6, 5))
            ax.plot(mean_pred, frac_pos, marker="o", color="tomato", label=model_name)
            ax.plot([0, 1], [0, 1], "k--", label="Perfectly calibrated")
            ax.set_xlabel("Mean Predicted Probability"); ax.set_ylabel("Fraction of Positives")
            ax.set_title(f"{model_name}: Calibration Curve")
            ax.legend()
            return fig

        if kind == "lift" and task == "classification":
            if not hasattr(model, "predict_proba"):
                QMessageBox.information(self, i18n.t("msg_title_plot", self._idioma), f"{model_name} does not support predict_proba.")
                return None
            classes = sorted(set(self.skl_y_test))
            if len(classes) != 2:
                QMessageBox.information(self, i18n.t("msg_title_plot", self._idioma), "The Lift Curve is only available for binary classification.")
                return None
            y_score = model.predict_proba(self.skl_x_test)[:, 1]
            y_true_bin = np.asarray(self.skl_y_test == classes[1]).astype(int)
            order = np.argsort(-y_score)
            y_sorted = y_true_bin[order]
            overall_rate = y_sorted.mean()
            n = len(y_sorted)
            deciles = np.linspace(0.1, 1.0, 10)
            lift_values = [
                (y_sorted[:max(1, int(round(frac * n)))].mean() / overall_rate) if overall_rate > 0 else 0.0
                for frac in deciles
            ]
            fig, ax = plt.subplots(figsize=(6, 5))
            ax.plot(deciles * 100, lift_values, marker="o", color="tomato", label=model_name)
            ax.axhline(1.0, linestyle="--", color="gray", label="Baseline")
            ax.set_xlabel("% of Population (sorted by predicted probability)"); ax.set_ylabel("Lift")
            ax.set_title(f"{model_name}: Lift Curve")
            ax.legend()
            return fig

        if kind == "gain" and task == "classification":
            if not hasattr(model, "predict_proba"):
                QMessageBox.information(self, i18n.t("msg_title_plot", self._idioma), f"{model_name} does not support predict_proba.")
                return None
            classes = sorted(set(self.skl_y_test))
            if len(classes) != 2:
                QMessageBox.information(self, i18n.t("msg_title_plot", self._idioma), "The Cumulative Gains Curve is only available for binary classification.")
                return None
            y_score = model.predict_proba(self.skl_x_test)[:, 1]
            y_true_bin = np.asarray(self.skl_y_test == classes[1]).astype(int)
            order = np.argsort(-y_score)
            y_sorted = y_true_bin[order]
            n = len(y_sorted)
            total_positives = y_sorted.sum()
            cum_gains = np.cumsum(y_sorted) / total_positives if total_positives > 0 else np.zeros(n)
            pop_frac = np.arange(1, n + 1) / n
            fig, ax = plt.subplots(figsize=(6, 5))
            ax.plot(pop_frac * 100, cum_gains * 100, color="tomato", label=model_name)
            ax.plot([0, 100], [0, 100], "k--", label="Baseline")
            ax.set_xlabel("% of Population (sorted by predicted probability)"); ax.set_ylabel("% of Positives Captured")
            ax.set_title(f"{model_name}: Cumulative Gains Curve")
            ax.legend()
            return fig

        if kind == "ks" and task == "classification":
            if not hasattr(model, "predict_proba"):
                QMessageBox.information(self, i18n.t("msg_title_plot", self._idioma), f"{model_name} does not support predict_proba.")
                return None
            classes = sorted(set(self.skl_y_test))
            if len(classes) != 2:
                QMessageBox.information(self, i18n.t("msg_title_plot", self._idioma), "The KS plot is only available for binary classification.")
                return None
            y_score = model.predict_proba(self.skl_x_test)[:, 1]
            fpr, tpr, thresholds = roc_curve(self.skl_y_test, y_score, pos_label=classes[1])
            finite_mask = np.isfinite(thresholds)
            thresholds, fpr, tpr = thresholds[finite_mask], fpr[finite_mask], tpr[finite_mask]
            ks_diff = tpr - fpr
            ks_idx = ks_diff.argmax()
            ks_stat = ks_diff[ks_idx]
            fig, ax = plt.subplots(figsize=(7, 5))
            ax.plot(thresholds, tpr, label="TPR (sensitivity)", color="tomato")
            ax.plot(thresholds, fpr, label="FPR", color="steelblue")
            ax.axvline(thresholds[ks_idx], linestyle="--", color="gray", label=f"KS = {ks_stat:.3f} @ {thresholds[ks_idx]:.3f}")
            ax.set_xlabel("Threshold"); ax.set_ylabel("Rate")
            ax.set_title(f"{model_name}: Kolmogorov-Smirnov Statistic")
            ax.legend()
            return fig

        if kind == "class_report" and task == "classification":
            y_pred = model.predict(self.skl_x_test)
            report = classification_report(self.skl_y_test, y_pred, output_dict=True)
            report_df = pd.DataFrame(report).transpose().round(3)
            fig, ax = plt.subplots(figsize=(8, 4))
            ax.axis("off")
            tbl = ax.table(cellText=report_df.values, rowLabels=report_df.index,
                            colLabels=report_df.columns, cellLoc="center", loc="center")
            tbl.auto_set_font_size(False); tbl.set_fontsize(9)
            ax.set_title(f"{model_name}: Classification Report")
            return fig

        if kind == "pca_scatter" and task == "clustering":
            x = getattr(self, "skl_x", None)
            if x is None:
                return None
            labels = model.labels_ if hasattr(model, "labels_") else model.predict(x)
            pca = PCA(n_components=2, random_state=self._get_skl_random_state())
            coords = pca.fit_transform(x)
            fig, ax = plt.subplots(figsize=(6, 5))
            scatter = ax.scatter(coords[:, 0], coords[:, 1], c=labels, cmap="tab10", alpha=0.7)
            ax.set_xlabel("PC1"); ax.set_ylabel("PC2")
            ax.set_title(f"{model_name}: PCA Scatter by Cluster")
            fig.colorbar(scatter, ax=ax, label="Cluster")
            return fig

        if kind == "tsne" and task == "clustering":
            x = getattr(self, "skl_x", None)
            if x is None:
                return None
            labels = model.labels_ if hasattr(model, "labels_") else model.predict(x)
            n_samples = len(x)
            perplexity = min(30, max(2, n_samples - 1))
            tsne = TSNE(n_components=2, random_state=self._get_skl_random_state(), perplexity=perplexity)
            coords = tsne.fit_transform(x)
            fig, ax = plt.subplots(figsize=(6, 5))
            scatter = ax.scatter(coords[:, 0], coords[:, 1], c=labels, cmap="tab10", alpha=0.7)
            ax.set_xlabel("t-SNE 1"); ax.set_ylabel("t-SNE 2")
            ax.set_title(f"{model_name}: t-SNE Scatter by Cluster")
            fig.colorbar(scatter, ax=ax, label="Cluster")
            return fig

        if kind == "elbow" and task == "clustering":
            x = getattr(self, "skl_x", None)
            if x is None:
                return None
            if "n_clusters" not in model.get_params():
                QMessageBox.information(self, i18n.t("msg_title_plot", self._idioma), f"{model_name} does not expose 'n_clusters'; the Elbow chart is not applicable.")
                return None
            k_range = list(range(2, 11))
            metric_values = []
            use_inertia = True
            for k in k_range:
                candidate = clone(model)
                candidate.set_params(n_clusters=k)
                candidate.fit(x)
                if hasattr(candidate, "inertia_"):
                    metric_values.append(candidate.inertia_)
                else:
                    use_inertia = False
                    labels_k = candidate.labels_ if hasattr(candidate, "labels_") else candidate.predict(x)
                    metric_values.append(silhouette_score(x, labels_k) if len(set(labels_k)) > 1 else 0.0)
            fig, ax = plt.subplots(figsize=(6, 5))
            ax.plot(k_range, metric_values, marker="o", color="tomato")
            ax.set_xlabel("Number of Clusters (k)")
            ax.set_ylabel("Inertia" if use_inertia else "Silhouette Score")
            ax.set_title(f"{model_name}: Elbow Method")
            return fig

        if kind == "silhouette" and task == "clustering":
            x = getattr(self, "skl_x", None)
            if x is None:
                return None
            labels = np.asarray(model.labels_ if hasattr(model, "labels_") else model.predict(x))
            unique_labels = sorted(set(labels))
            if len(unique_labels) < 2:
                QMessageBox.information(self, i18n.t("msg_title_plot", self._idioma), "Silhouette Plot needs at least 2 clusters.")
                return None
            sample_values = silhouette_samples(x, labels)
            avg_score = sample_values.mean()
            fig, ax = plt.subplots(figsize=(7, 6))
            y_lower = 10
            cmap = plt.get_cmap("tab10")
            for i, cluster_id in enumerate(unique_labels):
                cluster_values = np.sort(sample_values[labels == cluster_id])
                size = len(cluster_values)
                y_upper = y_lower + size
                ax.fill_betweenx(np.arange(y_lower, y_upper), 0, cluster_values, facecolor=cmap(i % 10), alpha=0.8)
                ax.text(-0.05, y_lower + 0.5 * size, str(cluster_id))
                y_lower = y_upper + 10
            ax.axvline(avg_score, linestyle="--", color="red", label=f"Average = {avg_score:.3f}")
            ax.set_xlabel("Silhouette Coefficient"); ax.set_ylabel("Cluster")
            ax.set_yticks([])
            ax.set_title(f"{model_name}: Silhouette Plot")
            ax.legend()
            return fig

        if kind == "distribution" and task == "clustering":
            x = getattr(self, "skl_x", None)
            if x is None:
                return None
            labels = model.labels_ if hasattr(model, "labels_") else model.predict(x)
            counts = pd.Series(labels).value_counts().sort_index()
            fig, ax = plt.subplots(figsize=(6, 5))
            ax.bar([str(c) for c in counts.index], counts.values, color="tomato")
            ax.set_xlabel("Cluster"); ax.set_ylabel("Number of Samples")
            ax.set_title(f"{model_name}: Cluster Size Distribution")
            return fig

        QMessageBox.information(self, i18n.t("msg_title_plot", self._idioma), f"Chart '{kind}' is not applicable to the current model/task.")
        return None

    def _show_skl_plot_dialog(self, fig, kind, file_stem):
        dialog = QDialog(self)
        dialog.setWindowTitle(f"Scikit-learn Plot: {kind}")
        layout = QVBoxLayout(dialog)

        canvas = FigureCanvas(fig)
        toolbar = NavigationToolbar(canvas, dialog)
        layout.addWidget(toolbar)
        layout.addWidget(canvas)

        btn_row = QHBoxLayout()
        btn_save = QPushButton("Save Chart")
        btn_close = QPushButton("Close")
        _style_dialog_buttons(btn_save, btn_close)
        btn_save.setFixedWidth(200)
        btn_close.setFixedWidth(200)
        btn_row.addWidget(btn_save)
        btn_row.addWidget(btn_close)
        layout.addLayout(btn_row)

        def _apply_ext(path, selected_filter, default_ext=".png"):
            root, ext = os.path.splitext(path)
            if ext:
                return path
            if "SVG" in (selected_filter or ""):
                return path + ".svg"
            if "PNG" in (selected_filter or ""):
                return path + ".png"
            return path + default_ext

        def save_figure():
            file_path, selected_filter = QFileDialog.getSaveFileName(
                dialog, "Save chart",
                os.path.join(self.skl_plot_path, f"{file_stem}.png"),
                "PNG Files (*.png);;SVG Files (*.svg);;All Files (*)"
            )
            if not file_path:
                return
            file_path = _apply_ext(file_path, selected_filter, default_ext=".png")
            ext = os.path.splitext(file_path)[1].lower()
            if ext == ".svg":
                fig.savefig(file_path, format="svg", bbox_inches="tight")
            else:
                fig.savefig(file_path, dpi=300, bbox_inches="tight", facecolor="white")
            QMessageBox.information(dialog, "Saved", f"Chart saved to:\n{file_path}")

        btn_save.clicked.connect(save_figure)
        btn_close.clicked.connect(dialog.close)
        dialog.resize(1000, 750)
        dialog.exec_()

