# ==========================================================================================================================================
if __name__ == "__main__":
    app = QApplication(sys.argv)
    dp_dir = os.path.abspath(os.path.dirname(__file__))

    splash = SplashScreen(dp_dir)
    splash.show()
    splash.start_checks()

    def start_mainwindow(status):
        splash.close()
        # Mensagem para download de pastas faltantes
        if not status['folders_ok']:
            missing = ', '.join(status['missing_folders'])
            QMessageBox.warning(
                None,
                "Missing required folders",
                f"The following required folders were not found: {missing}\n"
                f"Download the complete project structure from GitHub."
            )
            webbrowser.open("https://github.com/moimaian/CODRUG")

        window = MainWindow()
        window.show()

    splash.check_complete.connect(start_mainwindow)
    sys.exit(app.exec_())
